def main() -> None:
    every = int(sys.argv[1]) if len(sys.argv) > 1 else 5
    db = sqlite3.connect(f"file:{DB}?mode=ro", uri=True)
    now = int(time.time())
    logged = db.execute("SELECT ts, key FROM forecast_log WHERE ts < ?", (now - H - 120,)).fetchall()[::every]
    keys = sorted({k for _, k in logged})
    started = dict(db.execute("SELECT site, MIN(first_seen) FROM rooms GROUP BY site").fetchall())
    hist: dict[str, list] = defaultdict(list)
    for i in range(0, len(keys), 500):
        part = keys[i:i + 500]
        q = f"SELECT key, started, ended FROM sessions WHERE key IN ({','.join('?' * len(part))})"
        for k, s, e in db.execute(q, part):
            hist[k].append((s, e))
    full = {k: F.merge(hist[k], now) for k in keys}
    ends = {k: [e for _, e in full[k]] for k in keys}
    came = {(ts, k): F._first_live(full[k], ends[k], ts, ts + H) is not None for ts, k in logged}
    print(f"{len(logged)} forecasts, {len(keys)} rooms", flush=True)
    for decay in (0.75, 0.85, 0.95):
        for prior in (1, 2, 3, 5, 8):
            F.PRIOR, F.DECAY = prior, decay
            se = 0.0
            for ts, k in logged:
                c = F.forecast(F.until(full[k], ts), int(started[k.split(":", 1)[0]]), ts, H).chance
                se += (c - came[(ts, k)]) ** 2
            print(f"decay {decay}  prior {prior}  brier {se / len(logged):.4f}", flush=True)

def widen(x: np.ndarray) -> np.ndarray:
    """A vector (features or weights) from before long clips, with zeros for the profile."""
    if x.shape[-1] != OLD_X_DIM:
        return x
    pad = np.zeros(x.shape[:-1] + (P_DIM,), x.dtype)
    return np.concatenate([x[..., :V_DIM + A_DIM], pad, x[..., -2:]], axis=-1)

def modality_mask(visual: str, sound: str) -> np.ndarray:
    """The feature dims an action may learn from: a sound-only action never learns pixels."""
    m = np.zeros(X_DIM, bool)
    if visual.strip():
        m[:V_DIM] = True
    if sound.strip():
        m[V_DIM:V_DIM + A_DIM] = True
    return m

def cv_auc(fit, X: np.ndarray, y: np.ndarray) -> float:
    """Held-out AUC of ``fit(X, y) -> predict`` (leave-one-out up to 40 labels, else 5 folds)."""
    n = len(y)
    folds = [np.array([i]) for i in range(n)] if n <= 40 else [np.arange(k, n, 5) for k in range(5)]
    p = np.zeros(n)
    for te in folds:
        tr = np.setdiff1d(np.arange(n), te)
        if not ((y[tr] == 1).any() and (y[tr] == 0).any()):
            return float("nan")
        p[te] = fit(X[tr], y[tr])(X[te])
    return auc(p, y)

def sides(y: np.ndarray) -> tuple[int, int]:
    """(clear yes, clear no): "in between" answers (0.5) are on neither side."""
    return int((y == 1).sum()), int((y == 0).sum())

def label_target(y: int) -> float:
    """A stored answer as a training target: 1 yes, 0 no, 2 "in between" (operator, 6 Oct 2026:
    many "dancing" clips are neither, and yes or no was simply wrong) → 0.5."""
    return 0.5 if y == 2 else float(y)

def auc(p: np.ndarray, y: np.ndarray) -> float:
    pos, neg = p[y == 1], p[y == 0]
    if not len(pos) or not len(neg):
        return float("nan")
    return float(((pos[:, None] > neg[None, :]) + 0.5 * (pos[:, None] == neg[None, :])).mean())

