def pca_fit(Xt: np.ndarray, yt: np.ndarray):
    mu, V = basis  # type: ignore[misc]
    def feats(Z):
        return np.hstack([(Z @ w0 + b0)[:, None], (Z[:, m] - mu) @ V.T, Z[:, -EXTRA:], ones(len(Z))])
    th0 = np.zeros(V.shape[0] + EXTRA + 2)
    th0[0] = 1.0
    lam = np.full(len(th0), 0.1)
    lam[-1 - EXTRA:-1] = EXTRA_LAM
    lam[-1] = 0.0
    th = _fit(feats(Xt), yt, th0, lam, steps=400, lr=0.1)
    return th, (lambda Z: _sigmoid(feats(Z) @ th))

def full_fit(Xt: np.ndarray, yt: np.ndarray):
    Zt = np.hstack([Xt * fm, ones(len(Xt))])
    lam = np.concatenate([np.full(X_DIM, ANCHOR / np.sqrt(len(yt))), [0.0]])
    th = _fit(Zt, yt, np.concatenate([w0, [b0]]), lam, steps=300, lr=0.05)
    return th, (lambda Z: _sigmoid(np.hstack([Z * fm, ones(len(Z))]) @ th))

def direction_fit(Xt: np.ndarray, yt: np.ndarray):
    # Rocchio: yes-mean minus no-mean in the modality, 5 numbers fitted.
    d = np.zeros_like(w0)
    d[m] = Xt[yt == 1][:, m].mean(0) - Xt[yt == 0][:, m].mean(0)
    d /= np.linalg.norm(d) or 1.0
    scale = float(np.linalg.norm(w0)) or VISUAL_SCALE
    def feats(Z):
        return np.hstack([(Z @ w0 / scale)[:, None], (Z @ d)[:, None], Z[:, -EXTRA:], ones(len(Z))])
    th0 = np.concatenate([[scale, 0.0], np.zeros(EXTRA), [b0]])
    lam = np.concatenate([[1e-4, 1e-4], np.full(EXTRA, EXTRA_LAM), [0.0]])
    th = _fit(feats(Xt), yt, th0, lam, steps=500, lr=0.5)
    return (th, d, scale), (lambda Z: _sigmoid(feats(Z) @ th))

def fit_head_apart(X: np.ndarray, y: np.ndarray, w0: np.ndarray, b0: float, mask: np.ndarray | None,
                   basis: tuple[np.ndarray, np.ndarray] | None) -> tuple[np.ndarray, float, dict[str, Any]]:
    """``fit_head`` in a process of its own (one, spawned once, kept). In the API's threads
    the cross-validation's numpy work starved the event loop: ticks 0.5–0.9 s late every few
    seconds during a refit on the 4-core VPS (5 Oct 2026). Falls back to this thread."""
    global _fitter
    import multiprocessing
    from concurrent.futures import ProcessPoolExecutor
    from concurrent.futures.process import BrokenProcessPool

    with _fitter_lock:
        if _fitter is None:
            _fitter = ProcessPoolExecutor(1, mp_context=multiprocessing.get_context("spawn"))
        pool = _fitter
    try:
        return pool.submit(fit_head, X, y, w0, b0, mask, basis).result(timeout=600)
    except (BrokenProcessPool, OSError, TimeoutError) as e:
        log.warning("actions: fit process failed (%s), fitting here", e)
        with _fitter_lock:
            if _fitter is pool:
                pool.shutdown(wait=False, cancel_futures=True)
                _fitter = None
        return fit_head(X, y, w0, b0, mask, basis)

