def train(X: np.ndarray, y: np.ndarray, w0: np.ndarray, b0: float,
          mask: np.ndarray | None = None, basis: tuple[np.ndarray, np.ndarray] | None = None,
          ) -> tuple[np.ndarray, float]:
    w, b, _ = fit_head(X, y, w0, b0, mask, basis)
    return w, b

def prompt_variants(text: str) -> list[str]:
    """Wordings tried against the labels: CLAP heard "a woman moaning" at AUC 0.97
    where "moaning" alone got 0.72 on the same answers."""
    t = " ".join(text.lower().split())
    if not t:
        return [""]
    if t.startswith(("a ", "an ", "the ", "someone", "people", "women", "men ")):
        return [t]
    return [t, f"a woman {t}", f"a person {t}"]

def unload_if_idle(self, idle_s: float = 15 * 60) -> bool:
    with self._lock:
        if self._sess is None or time.time() - self.used < idle_s:
            return False
        self._sess = None
        return True

def __init__(self, store: Store, index: Index, visual_text: TextEncoder):
    self.store = store
    self.index = index
    self.vtext = visual_text
    self._live_cache: tuple[float, list[str], np.ndarray] | None = None
    self.stext = SoundText(settings.data_dir / "models" / "clap-htsat-unfused")
    #: key → (ts, x) of the room's latest clip, short or long (x kept float16: ~46k rooms in 3 days)
    self.feats: dict[str, tuple[int, np.ndarray]] = {}
    #: key → (ts, x) of the room's latest long clip (a day at most): what visual actions teach from
    self.long: dict[str, tuple[int, np.ndarray]] = {}
    #: id → action row (w, b as arrays)
    self.actions: dict[int, dict[str, Any]] = {}
    #: action id → {key: (ts, y)} of what has been labelled
    self.labelled: dict[int, dict[str, tuple[int, int]]] = {}
    #: modality mask bytes → (built at, mean, axes)
    self._bases: dict[bytes, tuple[float, np.ndarray, np.ndarray]] = {}
    #: action id -> latest ``truth_check`` (the chat's labels, judged before learning them)
    self.truth: dict[int, dict[str, Any]] = {}
    #: actions whose answers came in since their last fit (``_retrain_soon``)
    self._stale: set[int] = set()
    self._retrainer: Any = None
    #: called with (key, ts, x) for every new clip (taste.LiveTaste.on_clip, set by app.py)
    self.on_clip: Any = None

async def load(self) -> None:
    await self.store.c.executescript(SCHEMA)
    have = {r["name"] for r in await self.store.rows("PRAGMA table_info(actions)")}
    for col, ddl in (("visual_used", "TEXT NOT NULL DEFAULT ''"), ("sound_used", "TEXT NOT NULL DEFAULT ''"),
                     ("pinned", "INTEGER NOT NULL DEFAULT 0"), ("head", "TEXT NOT NULL DEFAULT '{}'")):
        if col not in have:
            await self.store.c.execute(f"ALTER TABLE actions ADD COLUMN {col} {ddl}")
    await self.store.c.commit()
    have = {r["name"] for r in await self.store.rows("PRAGMA table_info(action_labels)")}
    # src: 'you' (the operator's answer) or 'chat' (the room's chat said so, see chattruth.py);
    # p: what the head in force said when a chat label came in (an honest, prospective check).
    for col, ddl in (("src", "TEXT NOT NULL DEFAULT 'you'"), ("p", "REAL")):
        if col not in have:
            await self.store.c.execute(f"ALTER TABLE action_labels ADD COLUMN {col} {ddl}")
    await self.store.c.commit()
    have = {r["name"] for r in await self.store.rows("PRAGMA table_info(clip_feats)")}
    if "prof" not in have:
        await self.store.c.execute("ALTER TABLE clip_feats ADD COLUMN prof BLOB")
        await self.store.c.commit()
    for table, into in (("clip_feats", self.feats), ("long_feats", self.long)):
        async for r in self.store.stream(f"SELECT * FROM {table} WHERE ts >= ?", (int(time.time() - RAM_S),)):
            a = np.frombuffer(r["a"], np.float16).astype(np.float32) if r["a"] else None
            prof = np.frombuffer(r["prof"], np.float32) if r["prof"] else None
            into[r["key"]] = (r["ts"], featurize(np.frombuffer(r["v"], np.float16).astype(np.float32), a,
                                                 r["motion"], r["loud"], prof).astype(np.float16))
    for r in await self.store.rows("SELECT * FROM actions"):
        self.actions[r["id"]] = self._row(r)
    for r in await self.store.rows("SELECT action_id, key, ts, y FROM action_labels WHERE src = 'you'"):
        self.labelled.setdefault(r["action_id"], {})[r["key"]] = (r["ts"], r["y"])
    log.info("actions: %d actions, %d clips", len(self.actions), len(self.feats))

def _row(r: dict[str, Any]) -> dict[str, Any]:
    return {"id": r["id"], "name": r["name"], "visual": r["visual"], "sound": r["sound"], "created": r["created"],
            "w0": widen(np.frombuffer(r["w0"], np.float32).copy()), "b0": r["b0"],
            "w": widen(np.frombuffer(r["w"], np.float32).copy()), "b": r["b"], "trained": r["trained"],
            "visual_used": r.get("visual_used") or r["visual"], "sound_used": r.get("sound_used") or r["sound"],
            "pinned": bool(r.get("pinned")), "head": json.loads(r.get("head") or "{}")}

# ---- clips from the worker --------------------------------------------------------------

def clip(self, key: str, ts: int) -> tuple[np.ndarray, bool] | None:
    """(x, is long) of the clip of ``key`` taken at ``ts``, if it is still known."""
    for src, is_long in ((self.long, True), (self.feats, False)):
        got = src.get(key)
        if got is not None and got[0] == ts:
            return got[1].astype(np.float32), is_long
    return None

def forget(self, keys: list[str]) -> None:
    for k in keys:
        self.feats.pop(k, None)
        self.long.pop(k, None)

# ---- actions -------------------------------------------------------------------------------

def live_count(self) -> int:
    now = time.time()
    return sum(1 for k, (ts, _) in list(self.feats.items()) if now - ts < FRESH_S and self.index.in_scope(k))

def _prior(self, visual: str, sound: str) -> tuple[np.ndarray, float]:
    w0 = np.zeros(X_DIM, np.float32)
    if visual.strip():
        w0[:V_DIM] = VISUAL_SCALE * self.vtext.embed(visual)
    if sound.strip():
        w0[V_DIM:V_DIM + A_DIM] = SOUND_SCALE * self.stext.embed(sound)
    _, X = self._live()
    # Calibrate on what is live: the top PRIOR_TOP start above one half.
    b0 = -float(np.quantile(X @ w0, 1 - PRIOR_TOP)) if len(X) >= 20 else -float(VISUAL_SCALE * 0.1)
    return w0, b0

async def _retrain_stale(self) -> None:
    while self._stale:
        aid = self._stale.pop()
        if aid in self.actions:
            try:
                await self._retrain(aid)
            except Exception as e:
                log.warning("retrain %s: %s", aid, e)

def _fit(self, act: dict[str, Any], X: np.ndarray, y: np.ndarray) -> dict[str, Any]:
    """(thread) Pick the prompt wording the labels agree with most, then fit the head."""
    visual, sound = act["visual"], act["sound"]
    if len(y) and min(sides(y)) >= 3:
        best: tuple[float, str, str] | None = None
        for v in prompt_variants(visual):
            for a in prompt_variants(sound):
                w = np.zeros(X_DIM, np.float32)
                if v:
                    w[:V_DIM] = VISUAL_SCALE * self.vtext.embed(v)
                if a:
                    w[V_DIM:V_DIM + A_DIM] = SOUND_SCALE * self.stext.embed(a)
                sc = auc(X.astype(np.float64) @ w, y)
                if best is None or sc > best[0] + 1e-9:
                    best = (sc, v, a)
        assert best is not None
        _, visual, sound = best
    w0, b0 = self._prior(visual, sound)
    mask = modality_mask(visual, sound)
    w, b, info = fit_head_apart(X, y, w0, b0, mask, self._basis(mask))
    info["v"] = TRAINER_VERSION
    return {"w0": w0, "b0": b0, "w": w, "b": b, "head": info, "visual_used": visual, "sound_used": sound}

async def upgrade(self) -> None:
    """Retrain heads from an older trainer once enough rooms are live to calibrate on."""
    if len(self._live()[0]) < 200:
        return
    for aid, act in list(self.actions.items()):
        if act["head"].get("v") != TRAINER_VERSION:
            await self._retrain(aid)

def pinned_hits(self) -> dict[str, list[int]]:
    """room → pinned actions it is doing right now (p >= PINNED_P), for cards and filters."""
    pinned = [(aid, a) for aid, a in list(self.actions.items()) if a["pinned"]]
    if not pinned:
        return {}
    keys, X = self._live()
    out: dict[str, list[int]] = {}
    for aid, a in pinned:
        for i in np.flatnonzero(_sigmoid(X @ a["w"] + a["b"]) >= PINNED_P):
            out.setdefault(keys[i], []).append(aid)
    return out

def scores(self, aid: int) -> dict[str, float]:
    act = self.actions[aid]
    keys, X = self._live()
    if not keys:
        return {}
    p = _sigmoid(X @ act["w"] + act["b"])
    return dict(zip(keys, p.tolist(), strict=True))

def score_keys(self, keys: list[str]) -> dict[int, dict[str, float]]:
    """action → {room: p} for just these rooms' latest clips (for alert rules)."""
    have = [k for k in keys if k in self.feats]
    if not have or not self.actions:
        return {}
    X = np.stack([self.feats[k][1] for k in have]).astype(np.float32)
    return {aid: dict(zip(have, _sigmoid(X @ a["w"] + a["b"]).tolist(), strict=True))
            for aid, a in self.actions.items()}

def _pick(sc: list[tuple[str, int, float]], limit: int, long: bool) -> list[dict[str, Any]]:
    if not sc:
        return []
    top = sorted(sc, key=lambda c: -c[2])
    unsure = sorted(sc, key=lambda c: abs(c[2] - 0.5))
    out: list[dict[str, Any]] = []
    seen: set[str] = set()
    for i in range(max(len(top), len(unsure))):
        for src, why in ((top, "likely"), (unsure, "unsure")):
            if i < len(src) and src[i][0] not in seen and len(out) < limit:
                k, ts, p = src[i]
                out.append({"key": k, "ts": ts, "p": round(p, 3), "why": why, "long": long})
                seen.add(k)
    return out

def status(self) -> dict[str, Any]:
    return {"clips": len(self.feats), "clips_fresh_live": self.live_count(), "actions": len(self.actions),
            "long_clips": len(self.long)}

def _words(text: str) -> list[str]:
    folded = unicodedata.normalize("NFD", text.lower())
    return re.findall(r"[^\W_]+", "".join(c for c in folded if not unicodedata.combining(c)))

def said_matches(phrase: str, text: str) -> bool:
    """Every word of ``phrase`` starts a word of ``text`` (accents and case ignored); an empty phrase never."""
    want, have = _words(phrase), _words(text)
    return bool(want) and all(any(h.startswith(w) for h in have) for w in want)

def matches(self, r: Room) -> bool:
    if self.keys and r.key not in self.keys:
        return False
    if self.sites and r.site not in self.sites:
        return False
    if self.genders and r.gender not in self.genders:
        return False
    if r.viewers < self.min_viewers:
        return False
    if self.tags:
        have = {t.lower() for t in r.tags}
        if not all(t.lower() in have for t in self.tags):
            return False
    if self.q:
        ql = self.q.lower()
        if ql not in r.room and ql not in r.name.lower() and ql not in r.subject.lower() \
                and not any(ql in t.lower() for t in r.tags):
            return False
    return True

def matches_offline(self, key: str, rec: dict[str, Any] | None) -> bool:
    """:meth:`matches` for a room that isn't live: only what its stored record can tell."""
    if self.keys and key not in self.keys:
        return False
    site = key.split(":", 1)[0]
    if self.sites and site not in self.sites:
        return False
    rec = rec or {}
    if self.genders and rec.get("gender") not in self.genders:
        return False
    if self.q:
        ql = self.q.lower()
        if ql not in key and ql not in (rec.get("name") or "").lower():
            return False
    return True

def from_json(cls, d: dict[str, Any]) -> Rule:
    known = {k: v for k, v in d.items() if k in cls.__dataclass_fields__}
    r = cls(**known)
    if r.event not in EVENTS:
        raise ValueError(f"event must be one of {EVENTS}")
    r.keys = [k.lower() for k in r.keys]
    return r

def __init__(self, store: Store):
    self.store = store
    self.rules: list[Rule] = []
    self._fired: dict[tuple[int, str], float] = {}
    #: (action id, room) → the model's last p, so ``action`` rules fire on the way up only
    self._action_p: dict[tuple[int, str], float] = {}
    #: (room, habit) → (share, readings) or None; the app wires ``traits.share`` here
    self.habit_of: Any = None
    #: key -> the same performer's rooms that are live and public on other sites (``elsewhere``)
    self.public_twins: Any = None
    #: ``match`` rule id -> the rooms that passed its filters last minute
    self._matching: dict[int, set[str]] = {}

async def evaluate_states(self, changes: list[tuple[str, str, str]], tracked: dict[str, Tracked]) -> None:
    """Fire ``state`` rules for frame-state changes reported by the vision worker."""
    rules = [r for r in self.rules if r.enabled and r.event == "state"]
    if not rules or not changes:
        return
    now = time.time()
    for key, old, new in changes:
        t = tracked.get(key)
        if t is None:
            continue
        for rule in rules:
            if new not in rule.states or not rule.matches(t.room):
                continue
            k = (rule.id, key)
            if now - self._fired.get(k, 0) < rule.cooldown:
                continue
            self._fired[k] = now
            data = {"from": old, "to": new}
            await self.log("state", key, rule, data)
            bus.publish("alert", {"rule": rule.to_json(), "event": "state", "room": t.room.to_json(), "data": data})

async def evaluate_tip(self, ev: dict[str, Any], tracked: dict[str, Tracked]) -> None:
    """Fire ``tip`` rules for one tip seen in a followed chat (``chat.py``)."""
    t = tracked.get(ev["key"])
    if t is None:
        return
    now = time.time()
    for rule in self.rules:
        if not rule.enabled or rule.event != "tip" or ev["amount"] < rule.tip_min or not rule.matches(t.room):
            continue
        k = (rule.id, ev["key"])
        if now - self._fired.get(k, 0) < rule.cooldown:
            continue
        self._fired[k] = now
        data = {"amount": ev["amount"], "user": ev.get("user") or "", "text": (ev.get("text") or "")[:120]}
        await self.log("tip", ev["key"], rule, data)
        bus.publish("alert", {"rule": rule.to_json(), "event": "tip", "room": t.room.to_json(), "data": data})

def _elsewhere(self, key: str, show: str) -> dict[str, Any] | None:
    twins = self.public_twins(key) if self.public_twins is not None else []
    if not twins:
        return None
    return {"show": show or "private", "public_on": twins}

async def evaluate_actions(self, scores: dict[int, dict[str, float]], names: dict[int, str],
                           tracked: dict[str, Tracked]) -> None:
    """Fire ``action`` rules for freshly analysed clips. ``scores``: action → {room: p}."""
    rules = [r for r in self.rules if r.enabled and r.event == "action" and r.action_id in scores]
    now = time.time()
    for aid, per_room in scores.items():
        for key, p in per_room.items():
            before = self._action_p.get((aid, key), 0.0)
            self._action_p[(aid, key)] = p
            t = tracked.get(key)
            if t is None:
                continue
            for rule in rules:
                if rule.action_id != aid or not (before < rule.action_p <= p) or not rule.matches(t.room):
                    continue
                k = (rule.id, key)
                if now - self._fired.get(k, 0) < rule.cooldown:
                    continue
                self._fired[k] = now
                data = {"action": names.get(aid, str(aid)), "p": round(p, 2)}
                await self.log("action", key, rule, data)
                bus.publish("alert", {"rule": rule.to_json(), "event": "action", "room": t.room.to_json(),
                                      "data": data})
    if len(self._action_p) > 100_000:
        self._action_p.clear()

