async def _act() -> None:
    """Turn events into work: favourites' auto-record, and alert rules' actions."""
    q = bus.subscribe()
    try:
        while True:
            kind, data = await q.get()
            try:
                if kind == "online" and (data.get("favorite") or {}).get("auto_record"):
                    await _record(data["room"], "favourite")
                elif kind == "chat_toy":
                    # The chat says the toy runs now: the surest positive for the YOLO frames.
                    toys.chat_toy(data["key"], data.get("secs"))
                    truth.notice(data["key"])
                elif kind == "chat_tip":
                    await alerts.evaluate_tip(data, index.rooms)
                elif kind == "heard_line":
                    await alerts.evaluate_said(data, index.rooms)
                elif kind == "chat_private":
                    await alerts.evaluate_private(data["key"], data["show"], index.rooms)
                elif kind == "alert":
                    rule = data["rule"]
                    if rule.get("record") and data["room"].get("playable", True):
                        await _record(data["room"], f"rule {rule['name']}")
                    if rule.get("wall"):
                        await _add_to_wall(data["room"]["key"])
