async def _forecasts(keys: list[str], horizon: int) -> dict[str, Forecast]:
    """Each room's chance of being live within ``horizon`` seconds, from its sessions."""
    if not keys:
        return {}
    def run() -> dict[str, Forecast]:  # in a thread: thousands of rooms is ~a second of Python
        now = int(time.time())
        hist, started = store.broadcasts(now - (forecast.MAX_DAYS + 1) * forecast.DAY, keys)
        return {k: forecast.forecast(forecast.merge(hist.get(k, ()), now),
                                     int(started.get(k.split(":", 1)[0]) or now), now, horizon) for k in keys}
    return await asyncio.to_thread(run)

