                                 int(started.get(k.split(":", 1)[0]) or now), now, horizon) for k in keys}

async def _forecast_group(keys: list[str], horizon: int) -> Forecast | None:
    """One person across several rooms: their sessions merged, observed since the
    earliest of their sites' first poll."""
    if not keys:
        return None
    def run() -> Forecast:
        now = int(time.time())
        hist, started = store.broadcasts(now - (forecast.MAX_DAYS + 1) * forecast.DAY, keys)
        since = min(int(started.get(k.split(":", 1)[0]) or now) for k in keys)
        return forecast.forecast(forecast.merge([iv for k in keys for iv in hist.get(k, ())], now), since, now,
                                 horizon)
    return await asyncio.to_thread(run)

