    if await store.get_kv("forecast_model") != forecast.MODEL:
        # A new model: its track record is made again, so it only ever shows the model in use.
        try:
            await store.c.execute("DELETE FROM forecast_log")
            await store.set_kv("forecast_logged", str(int(time.time())))
            n = await _hindcast()
            await store.set_kv("forecast_model", forecast.MODEL)
            log.info("forecasts: hindcast %d past forecasts for the track record", n)
        except Exception as e:
            log.warning("forecast hindcast: %s", e)
    while True:
        try:
            await _soon_rules()
        except Exception as e:
            log.warning("soon rules: %s", e)
        try:
            last = int(await store.get_kv("forecast_logged") or 0)
            if time.time() - last >= FORECAST_LOG_S:
                as_of, fc = await _soon_forecasts(SOON_HOURS)
                ts = int(as_of)
                rows = [(k, f.chance, f.share, f.eta) for k, f in fc if index.get(k) is None and f.days]
                await store.log_forecasts(ts, SOON_HOURS * 3600, rows)
                await store.set_kv("forecast_logged", str(ts))
                log.info("forecasts: logged %d offline rooms' next %d h", len(rows), SOON_HOURS)
        except Exception as e:
            log.warning("forecast log: %s", e)
        await asyncio.sleep(SOON_EVERY_S)
