async def _soon_rules() -> None:
    rules = [r for r in alerts.rules if r.enabled and r.event == "soon"]
    if not rules:
        return
    wanted: dict[int, set[str]] = {}  # horizon → rooms
    per_rule: list[tuple[Any, list[str]]] = []
    for rule in rules:
        keys = [k for k in (rule.keys or list(index.favorites)) if index.get(k) is None]
        per_rule.append((rule, keys))
        wanted.setdefault(max(600, min(rule.soon_within, 12 * 3600)), set()).update(keys)
    fcs = {h: await _forecasts(sorted(keys), h) for h, keys in wanted.items()}
    meta = await _meta(sorted({k for _, keys in per_rule for k in keys}))
    for rule, keys in per_rule:
        fc = fcs[max(600, min(rule.soon_within, 12 * 3600))]
        for k in keys:
            f = fc.get(k)
            if f is None or f.eta is None or f.eta > rule.soon_within or f.chance < rule.soon_p:
                continue
            rec = meta.get(k)
            if index.get(k) is not None or not rule.matches_offline(k, rec):
                continue
            await alerts.evaluate_soon(rule, k, rec, f.chance, f.eta, int((rec or {}).get("last_seen") or 0))

