def __init__(self) -> None:
    self.inner = httpx.AsyncHTTPTransport()
    self.good = self.PC_PORTS[0]

async def handle_async_request(self, request: httpx.Request) -> httpx.Response:
    if request.url.port not in self.PC_PORTS:
        return await self.inner.handle_async_request(request)
    order = [self.good, *(p for p in self.PC_PORTS if p != self.good)]
    for i, port in enumerate(order):
        request.url = request.url.copy_with(port=port)
        try:
            res = await self.inner.handle_async_request(request)
        except (httpx.ConnectError, httpx.ReadError, httpx.RemoteProtocolError):
            if i == len(order) - 1:
                raise
            continue
        self.good = port
        return res
    raise AssertionError("unreachable")

async def delete_recording(job_id: str) -> dict[str, Any]:
    """Delete a finished recording: the workstation sends the file (and its sidecar)
    to its Recycle Bin, and it leaves the list. A file already gone just leaves the list."""
    row = next((r for r in await store.recent_recordings(1000) if r["job_id"] == job_id), None)
    if row is None:
        raise HTTPException(404, "no such recording")
    if row["ended"] is None and row["status"] in ("queued", "claimed", "running"):
        raise HTTPException(409, "still recording: stop it first")
    try:
        job = next((j for j in await recorder.jobs(200) if j["id"] == job_id), None)
    except Exception as e:
        raise HTTPException(502, f"vaultwares-api: {e}")
    name = _recording_file(job)
    recycled: list[str] = []
    if name:
        try:
            res = await _pc.delete(f"/rec/{quote(name)}", headers={"X-Token": settings.vision_token}, timeout=30)
        except httpx.HTTPError as e:
            raise HTTPException(503, f"the workstation isn't reachable ({type(e).__name__})")
        if res.status_code == 200:
            recycled = res.json().get("recycled") or []
        elif res.status_code != 404:
            raise HTTPException(502, f"workstation answered {res.status_code}: {res.text[:200]}")
    await store.delete_recording(job_id)
    return {"ok": True, "recycled": recycled}

async def recording_video(job_id: str, request: Request) -> StreamingResponse:
    """Play a finished recording: proxied from the workstation (remuxed to MP4 there), Range-aware."""
    if not recorder.enabled:
        raise HTTPException(409, "recording is not configured")
    try:
        job = next((j for j in await recorder.jobs(200) if j["id"] == job_id), None)
    except Exception as e:
        raise HTTPException(502, f"vaultwares-api: {e}")
    name = _recording_file(job)
    if not name:
        raise HTTPException(404, "no file for that recording")
    headers = {"X-Token": settings.vision_token}
    if rng := request.headers.get("range"):
        headers["Range"] = rng
    try:
        req = _pc.build_request("GET", f"/rec/{quote(name)}", headers=headers)
        up = await _pc.send(req, stream=True)
    except httpx.HTTPError as e:
        raise HTTPException(503, f"the workstation isn't reachable ({type(e).__name__})")
    if up.status_code >= 400:
        body = (await up.aread()).decode(errors="replace")[:200]
        await up.aclose()
        raise HTTPException(404 if up.status_code == 404 else 502, body or f"workstation answered {up.status_code}")
    passed = {k: v for k, v in up.headers.items()
              if k.lower() in ("content-type", "content-length", "content-range", "accept-ranges")}
    return StreamingResponse(up.aiter_raw(), status_code=up.status_code, headers=passed,
                             background=BackgroundTask(up.aclose))

