async def merge_identities(body: MergeBody) -> Any:
    """Merge (or rename) on the PC, then the VPS side. Done within ~45 s: the result. Else 202
    ``{"queued": true, "job": …}``, and ``/api/merges/jobs/<job>`` says when it's finished."""
    now = time.time()
    for j, s in list(_merge_jobs.items()):
        if now - s.get("ended", now) > 3600:
            _merge_jobs.pop(j, None)
    job = f"{int(now * 1000)}-{body.gone}"
    st: dict[str, Any] = {"job": job, "state": "running", "keep": body.keep, "gone": body.gone, "rename": body.rename,
                          "at": int(now)}
    _merge_jobs[job] = st
    task = asyncio.create_task(_merge_job(st, body), name=f"merge-{job}")
    _merge_tasks.add(task)
    task.add_done_callback(_merge_tasks.discard)
    try:
        await asyncio.wait_for(asyncio.shield(task), MERGE_WAIT_S)
    except TimeoutError:
        return JSONResponse({"queued": True, "job": job, "keep": body.keep, "gone": body.gone}, status_code=202)
    if st["state"] == "failed":
        raise HTTPException(st.get("status", 500), st["error"])
    return st["result"]

