def real(site: str, viewers: int | None) -> int | None:
    """The likely number of real people behind a displayed count; None where unknown."""
    if viewers is None:
        return None
    v = max(0, int(viewers))
    if site == "camsoda":
        if v <= CS_POINTS[0][0]:
            return 0
        for (x0, y0), (x1, y1) in zip(CS_POINTS, CS_POINTS[1:]):
            if v <= x1:
                return round(y0 + (y1 - y0) * (v - x0) / (x1 - x0))
        x, y = CS_POINTS[-1]
        return round(y + (v - x) * CS_SLOPE_AFTER)
    if site == "chaturbate":
        return 0 if v <= CB_FLOOR else round((v / CB_FLOOR) ** CB_EXP)
    return None

