async def _run(self) -> None:
    await asyncio.sleep(FIRST_AFTER_S)
    while True:
        due = float(self.last.get("at") or 0) + EVERY_S
        if time.time() >= due:
            try:
                await self.make()
            except Exception as e:
                self.error = str(e)[:200]
                log.warning("backup: %s", e)
                due = time.time() + 3600  # try again in an hour
            else:
                due = time.time() + EVERY_S
        await asyncio.sleep(max(60.0, min(3600.0, due - time.time())))

