def toy_notice(text: str) -> dict[str, Any] | None:
    """A notice that says a toy is (about to be) running: its length and level when stated."""
    if not TOY_WORDS.search(text):
        return None
    secs = TOY_SECS.search(text)
    level = TOY_LEVEL.search(text)
    step = TOY_STEP.search(text)
    return {"secs": int(secs.group(1)) if secs else None,
            "level": " ".join(level.group(1).lower().split()) if level else (f"level {step.group(1)}" if step else None),
            # Only a short notice that says it runs now counts; menus, adverts, reminders don't.
            "menu": not (len(text) <= TOY_MAX_LEN and TOY_NOW.search(text) and not TOY_MENU.search(text))}

def __init__(self) -> None:
    self.events: list[str] = []
    self.templates: dict[str, Any] = {"v3.templates": ["templates"]}

def _fields(fields: list[str], arr: Any) -> dict[str, Any]:
    mask, vals = arr[0], list(arr[1])
    out = dict(arr[2]) if len(arr) > 2 and isinstance(arr[2], dict) else {}
    for i, f in enumerate(fields):
        if mask & (1 << i) and vals:
            out[f] = vals.pop(0)
    return out

def _sub(self, spec: dict[str, Any], v: Any) -> Any:
    if not v:
        return None
    if spec.get("type") == "object":
        return self._fields(spec["fields"], v)
    if spec.get("type") == "array":
        return [self._fields(spec["fields"], x) for x in v]
    return v

def decode(self, raw: str) -> tuple[str, Any]:
    m = json.loads(raw)
    n = self.name(m[0])
    data = m[1] if len(m) > 1 else None
    if len(m) > 3:
        data = dict(data or {})
        vals = list(m[3])
        for i, f in enumerate(self.templates.get(n) or []):
            if m[2] & (1 << i) and vals:
                v = vals.pop(0)
                if isinstance(f, str):
                    data[f] = v
                else:
                    data[f["key"]] = self._sub(f, v)
    if n == "v3.templates" and isinstance(data, dict) and isinstance(data.get("templates"), dict):
        self.templates = data["templates"]
        self.events = list(data.get("events") or self.events)
    return n, data

def cs_event(n: str, d: Any) -> dict[str, Any] | None:
    """One CamSoda frame (decoded) -> our event, or None for what we don't show."""
    if not isinstance(d, dict):
        return None
    ts = (d.get("created_at") or 0) / 1000 or time.time()
    if n == "v3.chat.message":
        text = _plain(str(d.get("message") or ""))
        if d.get("is_tip"):
            anon = str(d.get("sender_invisible_mode") or "").upper() not in ("", "USER", "OFF")
            return {"t": ts, "kind": "tip", "user": "" if anon else str(d.get("subject_username") or ""),
                    "amount": int(d.get("value") or 0), "text": ""}
        user = str(d.get("username") or d.get("from_username") or "")
        if not user or d.get("type") in ("app_announcement", "notice", "system"):
            if not text:
                return None
            toy = toy_notice(text)
            return {"t": ts, "kind": "toy" if toy else "notice", "text": text[:500], **(toy or {})}
        return {"t": ts, "kind": "msg", "user": user, "text": text[:500], "fan": False, "mod": bool(d.get("is_mod")),
                "host": bool(d.get("is_model")), "tipper": bool(d.get("recent_tips"))}
    if n == "v3.chat.subject":
        return {"t": ts, "kind": "title", "text": _plain(str(d.get("subject") or ""))}
    return None  # v3.lovense.vibrate is handled as runs (Chat._vibe)

def cb_event(d: dict[str, Any]) -> dict[str, Any] | None:
    """One Chaturbate push message → our event, or None for what we don't show."""
    topic = str(d.get("_topic") or "")
    ts = float(d.get("ts") or d.get("pub_ts") or time.time())
    if topic == "RoomMessageTopic":
        u = d.get("from_user") or {}
        return {"t": ts, "kind": "msg", "user": u.get("username") or "", "text": clean(str(d.get("message") or "")),
                "fan": bool(u.get("in_fanclub")), "mod": bool(u.get("is_mod")), "host": bool(u.get("is_broadcaster")),
                "tipper": bool(u.get("tipped_recently"))}
    if topic == "RoomTipAlertTopic":
        anon = bool(d.get("is_anonymous_tip"))
        return {"t": ts, "kind": "tip", "user": "" if anon else str(d.get("from_username") or ""),
                "amount": int(d.get("amount") or 0), "text": clean(str(d.get("message") or ""))}
    if topic == "RoomNoticeTopic":
        text = " ".join(clean(str(m)) for m in d.get("messages") or [] if str(m).strip("-– ")).strip()
        if not text:
            return None
        toy = toy_notice(text)
        return {"t": ts, "kind": "toy" if toy else "notice", "text": text[:500], **(toy or {})}
    if topic == "RoomTitleChangeTopic":
        return {"t": ts, "kind": "title", "text": clean(str(d.get("title") or ""))}
    if topic == "RoomStatusTopic":
        return {"t": ts, "kind": "status", "text": str(d.get("status") or "")}
    return None

def toy_run(self, now: float, secs: int | None) -> None:
    self.toy_marks.append(now)
    if not secs:
        return
    if self.runs and now <= self.runs[-1][1] + 1.0:
        self.runs[-1][1] = max(self.runs[-1][1], now + secs)
    else:
        self.runs.append([now, now + secs])

