def unwatch(self, key: str, q: asyncio.Queue[dict[str, Any]]) -> None:
    r = self.rooms.get(key)
    if r is not None:
        r.listeners.discard(q)
        r.linger_until = time.time() + LINGER_S

def _ensure(self, r: ChatRoom) -> None:
    if (r.task is None or r.task.done()) and r.key.split(":", 1)[0] in SITES:
        r.task = asyncio.create_task(self._run(r), name=f"chat {r.key}")

    async def _cs(self, r: ChatRoom) -> None:
        room = r.key.split(":", 1)[1]
        codec = self._cs_codec
        async with self._connecting, asyncio.timeout(40):
            s = await self._session()
            tok = await self._cs_auth(s)
            lobby = await self._cs_open(s, CS_LOBBY, tok)
            try:
                await lobby.send_str(codec.encode("v3.lobby.discover", {"room": room}))
                url = None
                while url is None:
                    n, d = codec.decode(await asyncio.wait_for(lobby.recv_str(), timeout=20))
                    if n == "v3.lobby.discovered" and isinstance(d, dict) and d.get("room") == room:
                        url = d.get("url") or ""
                        if not url:
                            raise ValueError("room not served (offline?)")
            finally:
                await lobby.close()
            ws = await self._cs_open(s, url, tok)
        self.stats["connects"] += 1
        try:
            r.connected = True
            r.up_since = time.time()
            r.fails = 0
            while True:
                n, d = codec.decode(await asyncio.wait_for(ws.recv_str(), timeout=180))
                if n == "v3.ping":
                    await ws.send_str(codec.encode("v3.pong", None))
                elif n == "v3.chat.history" and isinstance(d, dict):
                    for m in d.get("messages") or []:
                        if (ev := cs_event("v3.chat.message", m)) is not None:
                            r.buf.append(ev)  # the panel's backlog only: never counted twice
// ... [truncated]

def _close_run(self, r: ChatRoom, now: float, force: bool = False) -> None:
    run = r.live_run
    if run is None or (not force and now - run[1] <= VIBE_GAP):
        return
    r.live_run = None
    secs = max(1, round(run[1] - run[0] + 1))
    level = f"{run[2]:g}"
    self._toys.append((r.key, run[0], f"toy ran {secs}s (level up to {level})", secs, level))
    ev = {"t": now, "kind": "notice", "text": f"toy ran {secs}s (level up to {level})"}
    r.buf.append(ev)
    for q in list(r.listeners):
        if not q.full():
            q.put_nowait(ev)

def _emit(self, r: ChatRoom, ev: dict[str, Any]) -> None:
    if ev.get("kind") == "status":
        text = (ev.get("text") or "").lower()
        r.paid = "private" in text or "group" in text
        if self.on_status is not None:
            try:
                self.on_status(r.key, text, ev.get("t"))
            except Exception as e:
                log.debug("status %s: %s", r.key, e)
    r.buf.append(ev)
    self.stats["events"] += 1
    for q in list(r.listeners):
        if not q.full():
            q.put_nowait(ev)
    if ev["kind"] == "tip" and ev["amount"] > 0:
        self._tips.append((r.key, ev["t"], ev["user"], ev["amount"], ev.get("text", "")[:200]))
        self.stats["tips"] += 1
        bus.publish("chat_tip", {"key": r.key, **ev})
    elif ev["kind"] == "toy" and not ev.get("menu"):
        self._toys.append((r.key, ev["t"], ev["text"], ev.get("secs"), ev.get("level")))
        r.toy_run(time.time(), ev.get("secs"))  # our clock: what clips are timed by
        self.stats["toys"] += 1
        bus.publish("chat_toy", {"key": r.key, **ev})

async def flush(self) -> None:
    tips, self._tips = self._tips, []
    toys, self._toys = self._toys, []
    if tips:
        await self.store.c.executemany("INSERT INTO chat_tips VALUES (?, ?, ?, ?, ?)", tips)
    if toys:
        await self.store.c.executemany("INSERT INTO chat_toys VALUES (?, ?, ?, ?, ?)", toys)
    if tips or toys:
        await self.store.c.commit()

