def judge(r: ChatRoom, ts: float, now: float) -> int | None:
    """1 the toy ran through the clip's sound, 0 it surely didn't, None can't tell (yet)."""
    end = ts - ENCODE_S
    runs = [list(x) for x in r.runs]
    covers = [_overlap(runs, end - lat - AUDIO_SECONDS, end - lat) / AUDIO_SECONDS for lat in LATENCIES]
    if min(covers) >= POS_COVER_MIN and covers[len(covers) // 2] >= POS_COVER_MID:
        return 1
    lo = end - max(LATENCIES) - AUDIO_SECONDS - QUIET_BEFORE
    hi = end + QUIET_AFTER
    if now < hi:
        return None  # a notice may still come
    if r.up_since is None or r.up_since > lo:
        return None  # the chat was not followed through all of it
    if any(lo <= m <= hi for m in r.toy_marks) or _overlap(runs, lo, hi) > 0:
        return None
    if not any(ts - APP_ACTIVE_S <= m <= hi for m in r.toy_marks):
        return None  # this room's app isn't announcing: silence says nothing
    return 0

