def segment_id(url: str) -> str:
    """A segment without its query: tokens in the query can change between playlist reads."""
    return urlsplit(url).path

def _media_lines(text: str, base: str) -> tuple[str | None, list[tuple[float, str]]]:
    """(init segment URL or None, [(duration, segment URL)]) of a media playlist."""
    init = None
    segs: list[tuple[float, str]] = []
    dur = 0.0
    for line in text.splitlines():
        if line.startswith("#EXT-X-MAP"):
            m = re.search(r'URI="([^"]+)"', line)
            if m:
                init = urljoin(base, m.group(1))
        elif line.startswith("#EXTINF:"):
            try:
                dur = float(line[8:].split(",", 1)[0])
            except ValueError:
                dur = 0.0
        elif line and not line.startswith("#"):
            segs.append((dur, urljoin(base, line.strip())))
            dur = 0.0
    return init, segs

async def start(self) -> None:
    if not self.enabled:
        log.info("clip sampler off (rate 0 or no ffmpeg)")
        return
    for i in range(CONCURRENCY):
        self._tasks.append(asyncio.create_task(self._run(), name=f"clips-{i}"))
    if settings.long_clips_per_day > 0:
        self._tasks.append(asyncio.create_task(self._run_long(), name="clips-long"))

