    if self.enabled and len(self.wanted) < 100 and key not in self.wanted:
        self.wanted[key] = at

def _wanted(self) -> str | None:
    now = time.time()
    for key, at in list(self.wanted.items()):
        if now > at + 20 or key not in self.index.rooms:
            self.wanted.pop(key, None)  # too late: the moment has passed
        elif now >= at and key not in self._taken:
            self.wanted.pop(key, None)
            return key
    return None

def _next(self) -> str | None:
    if key := self._wanted():
        return key
    if not self._due or time.time() - self._due_at > 30:
        self._refresh_due()
    while self._due:
        key = self._due.pop(0)
        if key in self.index.rooms and key not in self._taken:
            return key
    return None

