def prune_files(self, max_age_s: float, live: Any) -> tuple[int, int]:
    """Offline rooms' sample files older than ``max_age_s`` go (4 Oct 2026: 3.2 GB of them on a
    disk at 90 %). Teach only offers clips from the last ``actions.RAM_S`` and training keeps
    its own copy of the features, so nothing reads them. Returns (files, bytes)."""
    cutoff = time.time() - max_age_s
    n = size = 0
    for f in self.dir.iterdir():
        if f.suffix not in (".jpg", ".ogg") or not f.is_file():
            continue
        key = f.stem.replace("__", ":", 1)
        try:
            st = f.stat()
            if st.st_mtime < cutoff and key not in live:
                f.unlink()
                n, size = n + 1, size + st.st_size
        except OSError:
            continue
    return n, size

