def normalize(name: str) -> str:
    """KFC identity names: lower-case letters and digits only."""
    return "".join(ch for ch in name.lower() if ch.isascii() and ch.isalnum())

def batch_hash(digests: list[bytes]) -> str:
    """ColONEL-KFC's archive hash (python-zipper ``gallery_naming.ts``)."""
    if not digests:
        return "00000000"
    val = int.from_bytes(hashlib.sha256(b"".join(digests)).digest()[:8], "big")
    out = ""
    for _ in range(8):
        out = B62[val % 62] + out
        val //= 62
    return out

def __init__(self, store: Store, root: Path) -> None:
    self.store = store
    self.root = root
    self.verdicts: dict[str, dict[str, Any]] = {}
    self.ingest: dict[str, dict[str, Any]] = {}
    self._members: dict[tuple[str, float], list[str]] = {}
    self._lock = threading.Lock()  # rewrites happen in worker threads

async def load(self) -> None:
    await self.store.c.executescript(SCHEMA)
    have = {r["name"] for r in await self.store.rows("PRAGMA table_info(dataset_verdicts)")}
    for col in VERDICT_COLUMNS:
        if col.split()[0] not in have:
            await self.store.c.execute(f"ALTER TABLE dataset_verdicts ADD COLUMN {col}")
    await self.store.c.commit()
    for r in await self.store.rows("SELECT * FROM dataset_verdicts"):
        self.verdicts[r["file"]] = {k: r[k] for k in ("verdict", "dropped", "ts", "target", "original", "auto")}
    for r in await self.store.rows("SELECT * FROM dataset_ingest"):
        self.ingest[r["file"]] = {k: r[k] for k in ("outcome", "identity", "added", "detail", "ts")}

# ---- reading --------------------------------------------------------------------------

def path(self, file: str) -> Path:
    """The archive's current place (top level or ``_rejected``); 404s are the caller's."""
    if not FILE_RE.match(file):
        raise FileNotFoundError(file)
    for p in (self.root / file, self.root / OFFLOADED / file, self.root / REJECTED / file,
              self.root / INGESTED / file):
        if p.is_file():
            return p
    raise FileNotFoundError(file)

def count(self, p: Path) -> int:
    """Photos in an archive (an offloaded one: its sidecar says)."""
    if self.offloaded(p):
        return len(self.sidecar(p).get("members") or [])
    return len(self.members(p))

def members(self, p: Path) -> list[str]:
    key = (str(p), p.stat().st_mtime)
    got = self._members.get(key)
    if got is None:
        with zipfile.ZipFile(p) as z:
            got = sorted(n for n in z.namelist() if Path(n).suffix.lower() in IMAGE_EXT)
        if len(self._members) > 5000:
            self._members.clear()
        self._members[key] = got
    return got

def sidecar(p: Path) -> dict[str, Any]:
    try:
        return json.loads(p.with_suffix(".json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}

    def listing(self) -> list[dict[str, Any]]:
        """Every archive, newest first, with what the page needs to show it."""
        out = []
        dirs = [(self.root, False), (self.root / OFFLOADED, False), (self.root / REJECTED, True),
                (self.root / INGESTED, False)]
        for d, rejected in dirs:
            if not d.is_dir():
                continue
            for p in d.glob("*.zip"):
                m = FILE_RE.match(p.name)
                if not m:
                    continue
                try:
                    st = p.stat()
                    side = self.sidecar(p)
                    files = ([x.get("file") for x in side.get("members") or []] if self.offloaded(p)
                             else self.members(p))
                except (OSError, zipfile.BadZipFile):
                    continue
                by_file = {x.get("file"): x.get("key") for x in side.get("members") or []}
                v = self.verdicts.get(p.name) or {}
                out.append({
                    "file": p.name, "name": m.group(1), "hash": m.group(2), "size": st.st_size,
                    "made": int(side.get("made") or st.st_mtime), "count": len(files),
                    "gallery": bool(side.get("gallery")),
                    "keys": [by_file.get(f) for f in files],
                    "verdict": "reject" if rejected else v.get("verdict"),
                    "dropped": v.get("dropped", 0),
                    "target": v.get("target"), "auto": bool(v.get("auto")),
                    "ingest": self.ingest.get(p.name),
                    "on_pc": self.offloaded(p),
                })
