def keys_of(self, file: str) -> list[str]:
    """The rooms an archive's photos came from (its sidecar), wherever it lies now."""
    try:
        side = self.sidecar(self.path(file))
    except FileNotFoundError:
        return []
    return [k for k in dict.fromkeys(m.get("key") for m in side.get("members") or []) if k]

def pending(self, limit: int = 300) -> list[dict[str, Any]]:
    """Kept archives the workstation has not taken into the gallery yet (oldest verdict first)."""
    out: list[dict[str, Any]] = []
    for file, v in sorted(self.verdicts.items(), key=lambda kv: kv[1]["ts"]):
        if v["verdict"] != "keep" or file in self.ingest:
            continue
        here = next((p for p in (self.root / file, self.root / OFFLOADED / file) if p.is_file()), None)
        if here is None:
            continue
        if not v.get("auto") and time.time() - v["ts"] < GRACE_S:
            continue  # just kept: Back still works
        side = self.sidecar(here)
        out.append({"file": file, "name": FILE_RE.match(file).group(1),  # type: ignore[union-attr]
                    "gallery": bool(side.get("gallery")), "target": v.get("target"),
                    "on_pc": here.parent.name == OFFLOADED, "made": side.get("made"),
                    "keys": [k for k in dict.fromkeys(m.get("key") for m in side.get("members") or []) if k]})
        if len(out) >= limit:
            break
    return out

async def auto_keep(self) -> int:
    """Operator (29 Sep 2026): more photos of an identity the gallery already has go in
    without a check when they all come from one room. Archives merged from several
    rooms (or of unknown source) still go through the page."""
    n = 0
    for p in sorted(self.root.glob("*.zip")):
        if p.name in self.verdicts or not FILE_RE.match(p.name):
            continue
        if time.time() - p.stat().st_mtime < GRACE_S:
            continue  # still being pushed
        # Operator (1 Oct 2026): everything goes in by its name ("auto" 2 = kept in bulk).
        auto = 2 if settings.datasets_keep_all else 1
        if auto == 1:
            side = self.sidecar(p)
            keys = {m.get("key") for m in side.get("members") or []}
            if not side.get("gallery") or len(keys) != 1 or None in keys:
                continue
        self.verdicts[p.name] = {"verdict": "keep", "dropped": 0, "ts": int(time.time()),
                                 "target": None, "original": None, "auto": auto}
        await self._save(p.name)
        n += 1
    if n:
        await self.store.c.commit()
    return n

    async def judge(self, file: str, verdict: str | None, drop: list[int], name: str | None = None) -> dict[str, Any]:
        """Apply the drops and the operator's name first (a new file name), then the verdict
        to what is left. ``name`` makes the workstation put it in that identity (existing
        or new) whatever the gallery compare says."""
        done = self.ingest.get(file)
        if done and done["outcome"] != "failed":
            raise PermissionError("already taken into the gallery")
        if done:  # a failed ingest: a new verdict is a retry
            self.ingest.pop(file)
            await self.store.c.execute("DELETE FROM dataset_ingest WHERE file = ?", (file,))
        prev = self.verdicts.get(file) or {}
        dropped = int(prev.get("dropped", 0))
        original, target = prev.get("original"), prev.get("target")
        new_name = normalize(name) if name else None
        if name is not None and not new_name:
            raise ValueError("a name needs letters or digits")
        renamed = bool(new_name) and new_name != FILE_RE.match(file).group(1)  # type: ignore[union-attr]
        here = self.path(file)
        count = self.count(here)
        drop_set = {i for i in drop if 0 <= i < count}
        if (drop_set or renamed) and self.offloaded(here):
            raise PermissionError("this archive waits on the PC now: keep or reject it as it is")
