def tip_part(tips: list[tuple[float, int]], now: float) -> tuple[float, int]:
    """(score, tokens in the window) from (t, amount) tips: 100 decayed tokens = 1.0."""
    recent = [(t, a) for t, a in tips if 0 <= now - t <= TIP_WINDOW_S and a > 0]
    decayed = sum(a * 0.5 ** ((now - t) / TIP_HALF_LIFE_S) for t, a in recent)
    return math.log2(1 + decayed / 100), sum(a for _, a in recent)

def toy_part(room: Any, now: float, vibe_gap: float) -> tuple[float, str | None]:
    """(score, level) when the room's toy runs right now, by its chat; (0, None) otherwise."""
    run = getattr(room, "live_run", None)
    if run is not None and now - run[1] <= vibe_gap:
        try:
            level = float(run[2])
        except (TypeError, ValueError):
            level = 0.0
        return 2.0 + min(level, 20.0) / 20.0, f"{level:g}"
    for start, end in reversed(getattr(room, "runs", ())):
        if start <= now <= end:
            return 2.0, None
        if end < now - 60:
            break
    return 0.0, None

def action_part(hits: dict[str, float], weight: dict[str, float] | None = None) -> float:
    """Pinned actions at p ≥ ACTION_P: up to 1.5 each, times how rare the action is now."""
    weight = weight or {}
    return sum(1.5 * min(1.0, (p - 0.5) * 2) * weight.get(name, 1.0) for name, p in hits.items() if p >= ACTION_P)

def taste_parts(ps: dict[str, float]) -> dict[str, tuple[float, float]]:
    """room -> (part, share of scored rooms at or above it) for the rooms in the top ``TASTE_TOP``.
    A rank, not the probability: the head is fitted on picked minutes, so its scale on every live
    room is not calibrated, its order is what was measured."""
    if not ps:
        return {}
    order = sorted(ps.items(), key=lambda kv: -kv[1])
    n = len(order)
    out = {}
    for i, (k, _) in enumerate(order):
        top = (i + 1) / n
        if top > TASTE_TOP:
            break
        out[k] = (TASTE_MAX * (1.0 - top / TASTE_TOP), top)
    return out

def reasons(*, tokens: int, toy: float, level: str | None, heat_gain: tuple[int | None, int],
            hits: dict[str, float], viewers: int, favorite: bool, taste_top: float | None = None) -> list[str]:
    out: list[str] = []
    if toy:
        out.append(f"toy running{f' (level {level})' if level else ''}")
    if tokens:
        out.append(f"{tokens:,} tk tipped in 5 min")
    base, gain = heat_gain
    if base is not None and gain > 0 and base >= 0:
        out.append(f"audience +{gain:,} ({gain / max(base, 1):.0%}) in 5 min")
    for name, p in sorted(hits.items(), key=lambda kv: -kv[1]):
        if p >= ACTION_P:
            out.append(f"{name.lower()} ({p:.0%})")
    if taste_top is not None:
        out.append(f"your kind of minute (top {max(1, round(taste_top * 100))}%)")
    if favorite:
        out.append("favourite")
    if not out or out == ["favourite"]:
        out.append(f"{viewers:,} watching")
    return out

