def publish(self, kind: str, data: Any) -> None:
    for q in list(self._subs):
        try:
            q.put_nowait((kind, data))
        except asyncio.QueueFull:
            # A reader that stopped reading loses events, not the server.
            self._subs.discard(q)

def merge(intervals: Iterable[tuple[int, int | None]], now: int) -> list[tuple[int, int]]:
    """Sorted, non-overlapping (start, end); open sessions end ``now``. Several rooms
    of one person merge the same way."""
    out: list[list[int]] = []
    for s, e in sorted((s, now if e is None else e) for s, e in intervals):
        if e <= s:
            continue
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return [(s, e) for s, e in out]

def _first_live(iv: list[tuple[int, int]], ends: list[int], a: int, b: int) -> int | None:
    """Earliest moment in [a, b) the room is live, or None."""
    i = bisect_left(ends, a + 1)  # first interval ending after a
    if i < len(iv) and iv[i][0] < b:
        return max(iv[i][0], a)
    return None

def kind(show: str) -> str:
    """public / paid (private, group, ticket, spy...) / away."""
    s = (show or "public").lower().strip()
    if s in ("public", "open", "online", "free", ""):
        return "public"
    if s in AWAY or "away" in s or "break" in s:
        return "away"
    return "paid"

def site_floor(prices: list[float]) -> float | None:
    """The lowest private price a site allows, read from its rooms: the smallest price at least
    2% of the priced rooms share (a few odd values below it are listing noise)."""
    ps = [p for p in prices if p > 0]
    if len(ps) < 50:
        return None
    c = Counter(ps)
    for p in sorted(c):
        if c[p] >= 0.02 * len(ps):
            return p
    return None

def refresh(self) -> int:
    # Browse filters live rooms only; a room panel asks ``labels`` itself.
    live = self.index.rooms if self.index is not None else set(self.traits.rooms) | set(self.rec)
    keys = [k for k in list(live) if k in self.traits.rooms or k in self.rec]
    self.ids = {k: ids for k in keys if (ids := {x["id"] for x in self.labels(k)})}
    return len(self.ids)

async def load(self) -> None:
    if self.store is None:
        return
    await self.store.c.executescript(SCHEMA)
    await self.store.c.commit()
    cutoff = time.time() - FORGET_S
    for r in await self.store.rows("SELECT key, body, ts FROM room_shows"):
        if r["key"] == CALIB_KEY:
            got = orjson.loads(r["body"])
            self.calib.update(got.get("calib") or {})
            self.words.update(got.get("words") or {})
        elif r["ts"] >= cutoff:
            self.rec[r["key"]] = r["body"].encode()  # cold until read (Cold)

def _shows(self, key: str) -> dict[str, Any]:
    s = self.rec.get(key)
    if s is None:
        s = self.rec[key] = {"obs": 0, "pub": 0, "paid": 0, "away": 0, "eps": 0, "short": 0, "durs": [],
                             "eps_min": 0, "short_min": 0, "min_s": 0, "gaps": 0, "gap_s": 0, "chat_eps": 0,
                             "days": []}
    self._dirty.add(key)
    return s

def _episode(self, key: str, dur: float, at_min: bool, chat: bool = False) -> None:
    s = self._shows(key)
    s["eps"] += 1
    s["short"] += int(dur < SHORT_S)
    s["durs"] = (s["durs"] + [int(dur)])[-DURS_KEPT:]
    if at_min:
        s["eps_min"] += 1
        s["short_min"] += int(dur < SHORT_S)
    if chat:
        s["chat_eps"] += 1

    def sweep(self, site: str, listed: dict[str, Any], now: float | None = None) -> None:
        """One site's sweep: ``listed`` = key -> Room as the listing has it now."""
        now = time.time() if now is None else now
        if site in KNOWN_FLOOR:
            self.floor[site] = KNOWN_FLOOR[site]
        elif site != "cam4":  # cam4 rows carry no price
            f = site_floor([r.private_price for r in listed.values()])
            if f is not None:
                self.floor[site] = f
        day = int(now // 86400)
        favs = self.index.favorites if self.index is not None else {}
        for key, room in listed.items():
            if room.gender == "m" and key not in favs:
                continue
            k = kind(room.show)
            lv = self.live.get(key)
            s = self._shows(key)
            if lv is not None and lv.get("gone") is not None:
                gap = now - lv["gone"]
                if site == "chaturbate" and GAP_MIN_S <= gap <= GAP_MAX_S and lv["show"] == "public":
                    s["gaps"] += 1
                    s["gap_s"] += int(gap)
                    if lv.get("chatted"):
                        self.calib["gaps"] += 1
                        self.calib["private"] += int(bool(lv.get("chat_was_paid")))
                lv["chat_was_paid"] = False
                lv = None if gap > GAP_MAX_S else lv
                if lv is not None:
                    lv["gone"] = None
                    lv["seen"] = now
            if lv is None:
                self.live[key] = {"show": k, "since": now, "seen": now, "price": room.private_price, "gone": None}
