async def _get(self, url: str) -> bytes:
    await asyncio.sleep(PAUSE_S)
    assert self.session is not None and self.direct is not None
    for sess in (self.session, self.direct):
        try:
            r = await sess.get(url)
        except Exception as e:
            last = str(e)
            continue
        if r.status_code == 200:
            return r.content
        last = f"{urlsplit(url).path} answered {r.status_code}"
        if r.status_code not in (403, 429):
            break
    raise RuntimeError(last)

async def _json(self, url: str) -> Any:
    return json.loads(await self._get(url))

