async def _camsoda(self, room: str) -> list[dict[str, str]]:
    """Free albums and videos (price 0, no fan-club level), full size via
    ``/api/v1/media/get/<id>`` — what the album page itself loads."""
    media = await self._json(f"https://www.camsoda.com/api/v1/user/{room}/media")
    items: list[dict[str, str]] = []
    for m in media.get("mediaList") or []:
        if m.get("token_price") or m.get("fanclub_access_level") or not m.get("id"):
            continue
        got = await self._json(f"https://www.camsoda.com/api/v1/media/get/{m['id']}")
        if got.get("access_type") != "free":
            continue
        for it in (got.get("media") or {}).get("items") or []:
            if it.get("url"):
                items.append({"url": it["url"], "kind": "video" if m.get("is_video") else "photo", "set": str(m["id"])})
    return items

async def _next(self) -> str | None:
    """The most popular live room never harvested with results (else not tried within ``REVISIT_DAYS``).

    Women's rooms only (operator, 28 Sep 2026): less volume, more value, and
    the face is on camera almost always. Couples and multi-person rooms are
    out; the workstation also skips rooms whose cam faces split into two people.
    """
    recent = {r["key"] for r in await self.store.rows(
        "SELECT key FROM harvested WHERE ts > ? OR items > 0", (int(time.time()) - REVISIT_DAYS * 86400,))}
    allowed = {x.strip() for x in settings.harvest_sites.split(",") if x.strip()}
    best = None
    for key, t in list(self.index.rooms.items()):
        if t.room.site not in SITES or t.room.site not in allowed or key in recent or t.room.show != "public" or t.room.gender != "f":
            continue
        if best is None or t.room.viewers > best[1]:
            best = (key, t.room.viewers)
    return best[0] if best else None

