            c = self.checks.setdefault(name, Check(ok, detail, now, pending=not ok))
            if c.ok != ok:
                c.ok, c.since, c.pending = ok, now, True
            c.detail = detail
            if not c.pending:
                continue
            if not ok and now - c.since >= self.hold_s:
                sent.append(f"⚠️ Panopticam: {html.escape(detail)}")
                c.pending, c.warned = False, True
            elif ok:
                # Back to fine: only worth a word if the operator heard it was broken.
                if c.warned:
                    sent.append(f"✅ Panopticam: {html.escape(detail)}")
                c.pending, c.warned = False, False
