def malloc_mb() -> dict[str, float] | None:
    """glibc's view: heap in use vs held free (fragmentation the trim can't give back)."""
    try:
        f = ctypes.CDLL(ctypes.util.find_library("c") or "libc.so.6").mallinfo2
    except (OSError, AttributeError):
        return None
    f.restype = _Mallinfo2
    m = f()
    mb = 1024 * 1024
    return {"in_use": round((m.uordblks + m.hblkhd) / mb, 1), "free_held": round(m.fordblks / mb, 1),
            "mmapped": round(m.hblkhd / mb, 1)}

def _size(o: object, seen: set[int], depth: int) -> float:
    """Rough deep size in bytes; big containers are sampled and scaled up."""
    if id(o) in seen:
        return 0
    seen.add(id(o))
    nbytes = getattr(o, "nbytes", None)
    if isinstance(nbytes, int) and hasattr(o, "dtype"):
        return sys.getsizeof(o) if getattr(o, "base", None) is not None else max(nbytes, sys.getsizeof(o))
    size = float(sys.getsizeof(o))
    if depth <= 0 or isinstance(o, (str, bytes, bytearray, int, float, bool, type(None))):
        return size
    if isinstance(o, dict):
        items = list(itertools.islice(o.items(), SAMPLE))
        if items:
            part = sum(_size(k, seen, depth - 1) + _size(v, seen, depth - 1) for k, v in items)
            size += part * len(o) / len(items)
        return size
    if isinstance(o, (list, tuple, set, frozenset, collections.deque)):
        items = list(itertools.islice(o, SAMPLE))
        if items:
            size += sum(_size(v, seen, depth - 1) for v in items) * len(o) / len(items)
        return size
    d = getattr(o, "__dict__", None)
    if isinstance(d, dict):
        size += _size(d, seen, depth)
    for s in getattr(type(o), "__slots__", ()):
        if (v := getattr(o, s, None)) is not None:
            size += _size(v, seen, depth - 1)
    return size

def list_owners(objs: list[object], sample: int = 400) -> dict[str, object]:
    """What the GC-tracked lists look like and what holds them: (length, first item's type)
    for every list, and the holders of a random sample (one pass over ``objs``)."""
    import random

    lists = [o for o in objs if type(o) is list]
    shapes = collections.Counter(
        (min(len(o), 10) if len(o) < 10 else "10+" if len(o) < 100 else "100+", type(o[0]).__name__ if o else "-")
        for o in lists)
    picked = {id(o) for o in random.sample(lists, min(sample, len(lists)))}
    owners: collections.Counter[str] = collections.Counter()
    example: dict[str, dict] = {}
    for o in objs:
        if type(o) is list and id(o) in picked:
            continue
        hits = sum(1 for r in gc.get_referents(o) if id(r) in picked)
        if not hits:
            continue
        name = type(o).__name__
        if isinstance(o, dict):
            keys = [k for k in itertools.islice(o, 4) if isinstance(k, str)]
            name += "{" + ",".join(k[:24] for k in keys) + "}"
            example.setdefault(name, o)
        owners[name] += hits
    del lists
    # 8 Oct 2026: the top holder was a dict keyed by room ("camsoda:…") — say whose attribute it is.
    top = {id(example[n]): n for n, _ in owners.most_common(8) if n in example}
    held: dict[str, str] = {}
    for o in objs:
        for r in gc.get_referents(o):
            if id(r) not in top or top[id(r)] in held:
                continue
