def census(roots: dict[str, object], top: int = 40) -> list[dict]:
    """Biggest attributes of the long-lived objects (MB, estimated). Run on the event
    loop so nothing it walks changes underneath it."""
    out = []
    seen = {id(r) for r in roots.values()}  # shared: an object counts once, under the first root reaching it
    for name, root in roots.items():
        for attr, v in list(vars(root).items()):
            if isinstance(v, types.ModuleType) or (callable(v) and not hasattr(v, "__len__")):
                continue
            mb = _size(v, seen, 6) / 1048576
            if mb >= 1:
                out.append({"where": f"{name}.{attr}", "mb": round(mb, 1),
                            "len": len(v) if hasattr(v, "__len__") else None, "type": type(v).__name__})
    out.sort(key=lambda r: -r["mb"])
    return out[:top]

def _gc(self, phase: str, info: dict) -> None:
    if phase == "start":
        self._gc_t = time.perf_counter()
    elif info.get("generation") == 2:
        self.gc2.append((time.time(), time.perf_counter() - self._gc_t))

def _watch(self) -> None:
    while True:
        time.sleep(0.2)
        late = time.monotonic() - self.last
        if late < self.STALL_S or self._dumped == self.last:
            continue
        self._dumped = self.last
        self.stalls.append(time.time())
        # The loop's own stack often ends in uvloop's C code: it is waiting for the GIL that
        # another thread holds. So: every busy thread's innermost frames, the loop's first.
        names = {t.ident: t.name for t in threading.enumerate()}
        frames = sys._current_frames()
        parts = []
        for ident in sorted(frames, key=lambda i: i != self._loop_thread):
            if ident == threading.get_ident():
                continue
            inner = "".join(traceback.format_stack(frames[ident])[-4:])
            if ident != self._loop_thread and "threading.py" in inner and "wait" in inner:
                continue  # idle pool workers
            parts.append(f"--- {names.get(ident, ident)}{' (loop)' if ident == self._loop_thread else ''}\n{inner}")
        log.warning("event loop stalled %.1f s so far, threads:\n%s", late, "".join(parts))

def status(self) -> dict[str, float | int]:
    now = time.time()
    late = [lag for t, lag in list(self.late) if t >= now - 300]
    return {"worst_5min_s": round(max(late, default=0.0), 3), "late_ticks_5min": len(late),
            "stalls_24h": sum(1 for t in list(self.stalls) if t >= now - 86400),
            "gc2_last_s": [round(d, 2) for _, d in list(getattr(self, "gc2", ()))[-5:]],
            "gc2_1h": sum(1 for t, _ in list(getattr(self, "gc2", ())) if t >= now - 3600)}

def _attr(line: str, name: str) -> str:
    m = re.search(rf'(?:^|[:,]){name}=("([^"]*)"|[^,]*)', line)
    if not m:
        return ""
    return m.group(2) if m.group(2) is not None else m.group(1)

def parse_master(text: str, base: str) -> list[Level]:
    lines = text.splitlines()
    audio: dict[str, str] = {}
    for line in lines:
        if not line.startswith("#EXT-X-MEDIA:") or _attr(line, "TYPE") != "AUDIO":
            continue
        group, uri = _attr(line, "GROUP-ID"), _attr(line, "URI")
        if not group or not uri:
            continue
        # The DEFAULT rendition wins a group; otherwise the first one listed.
        if group not in audio or _attr(line, "DEFAULT") == "YES":
            audio[group] = urljoin(base, uri)
    out: list[Level] = []
    for i, line in enumerate(lines):
        if not line.startswith("#EXT-X-STREAM-INF"):
            continue
        uri = lines[i + 1].strip() if i + 1 < len(lines) else ""
        if not uri or uri.startswith("#"):
            continue
        res = _RES.search(_attr(line, "RESOLUTION"))
        group = _attr(line, "AUDIO")
        bw = _attr(line, "BANDWIDTH")
        out.append(Level(
            height=int(res.group(2)) if res else 0,
            width=int(res.group(1)) if res else None,
            bandwidth=int(bw) if bw.isdigit() else None,
            url=urljoin(base, uri),
            audio_url=audio.get(group) if group else None,
        ))
    out.sort(key=lambda lv: (lv.height, lv.bandwidth or 0), reverse=True)
    return out

def pick_level(levels: list[Level], height: int | None = None) -> Level | None:
    """The level for a requested height: exact, else the next one down."""
    if not levels:
        return None
    if not height:
        return levels[0]
    for lv in levels:
        if lv.height == height:
            return lv
    for lv in levels:
        if lv.height < height:
            return lv
    return levels[-1]

def preview_level(levels: list[Level]) -> Level | None:
    """The lowest level of at least 240p: enough to recognise, cheap to open."""
    for lv in reversed(levels):
        if lv.height >= 240:
            return lv
    return levels[-1] if levels else None

def heat(self) -> float:
    """How hard the audience is jumping right now: gain over the window,
    damped for tiny rooms so +5 on 2 viewers doesn't top the list."""
    base, gain = self.heat_parts()
    if base is None or gain <= 0:
        return 0.0
    return gain / (base + 30)

def trend(self) -> int:
    if not self.recent:
        return 0
    now_t, now_v = self.recent[-1]
    for t, v in self.recent:
        if now_t - t <= TREND_WINDOW_S:
            return now_v - v
    return 0

