def fold(self, ordered: list[Tracked]) -> tuple[list[Tracked], dict[str, list[Tracked]]]:
    """One card per performer: walk the sorted rooms, and a room that is the same
    person as one already shown (a simulcast on another site) goes under that card
    instead of getting its own. The first in sort order leads the group."""
    heads: list[Tracked] = []
    also: dict[str, list[Tracked]] = {}
    claimed: dict[str, str] = {}  # room -> the head whose twin list names it
    for t in ordered:
        k = t.room.key
        mates = [m for m, sim in self.twins.get(k, ()) if sim >= FOLD_SIM]
        # Values of ``claimed`` are always heads: a mate already under a card pulls this room in too.
        head = claimed.get(k) or next((claimed[m] for m in mates if m in claimed), None)
        if head is None:
            heads.append(t)
            claimed[k] = k
            for m in mates:
                claimed.setdefault(m, k)
        else:
            also.setdefault(head, []).append(t)
            for m in mates:
                claimed.setdefault(m, head)
    return heads, also

def in_scope(self, key: str) -> bool:
    """Live and one the vision / sound features should spend time on."""
    t = self.rooms.get(key)
