#: Hair: sure when this many head readings agree this much; highlights in half of them.

def parse_runs(s: str) -> list[list[int]]:
    """'pid:first_day:last_day|…' → [[pid, first, last], …] (oldest first)."""
    return [[int(x) for x in part.split(":")] for part in s.split("|") if part]

def _merge(runs: list[list[int]]) -> list[list[int]]:
    out: list[list[int]] = []
    for r in runs:
        if out and out[-1][0] == r[0]:
            out[-1][2] = max(out[-1][2], r[2])
        else:
            out.append(list(r))
    return out

def add_day(s: str, pid: int, day: int) -> str:
    runs = parse_runs(s)
    if runs and runs[-1][0] == pid:
        runs[-1][2] = max(runs[-1][2], day)
    elif runs and runs[-1][1] == runs[-1][2] == day:
        runs[-1][0] = pid  # the host changed within its first day: keep the latest reading
        runs = _merge(runs)
    else:
        runs.append([pid, day, day])
    return dump_runs([r for r in runs if r[2] >= day - HOST_DAYS])

