def _has(self, family: str, value: str, state: str, subj: str) -> bool:
    s = self.sets.get(family, {}).get((value, state))
    return s is not None and subj in s

def _in_state(self, family: str, state: str, subj: str) -> list[str]:
    return sorted(v for (v, st), s in self.sets.get(family, {}).items() if st == state and subj in s)

# ---- who a label belongs to ---------------------------------------------------------------

def behaviour_of(self, key: str) -> str | None:
    subj = f"r:{key}"
    for b in ("rotating", "recycled"):
        if self._has("room", b, "yes", subj):
            return b
    got = self.behaviours.get(key)
    if got is None or self._has("room", got[0], "no", subj):
        return None
    return got[0]

def subject(self, key: str, family: str) -> str | None:
    """Where ``family``'s labels for room ``key`` live (None: a person label on a rotating room)."""
    if family in ROOM:
        return f"r:{key}"
    if self.behaviour_of(key) == "rotating":
        return None
    p = self.vision.persona.get(key)
    return f"p:{p['id']}" if p else f"r:{key}"

def of_room(self, key: str) -> dict[str, list[str]]:
    """Labels in force for a room, by family (what Browse rows carry)."""
    out: dict[str, list[str]] = {}
    for fam in LOCKED:
        if vals := self.values(self.subject(key, fam), fam):
            out[fam] = [v for v, _ in vals]
    if b := self.behaviour_of(key):
        out["room"] = [b]
    return out

def habits_of(self, key: str) -> set[str]:
    """habits.py's labels with the operator's verdicts applied."""
    subj = f"r:{key}"
    got = set(self.habits.ids.get(key, ()))
    for (v, st), subs in self.sets.get("habit", {}).items():
        if subj in subs:
            if st == "no":
                got.discard(v)
            elif st == "yes":
                got.add(v)
    return got

def rooms_with(self, family: str, values: set[str]) -> set[str]:
    """Live rooms whose ``family`` labels include any of ``values``."""
    if family == "habit":
        return {k for k in self.index.rooms if values <= self.habits_of(k)}
    if family == "room":
        return {k for k in self.index.rooms if self.behaviour_of(k) in values}
    subjects: set[str] = set()
    fam = self.sets.get(family, {})
    for v in values:
        subjects |= (fam.get((v, "auto"), set()) | fam.get((v, "yes"), set())) - fam.get((v, "no"), set())
    return {k for k in self.index.rooms if self.subject(k, family) in subjects} if subjects else set()

def counts(self, family: str) -> list[tuple[str, int]]:
    """Live rooms per value of a family, most first (Browse menus)."""
    per: dict[str, int] = {}  # subject -> live rooms (one pass, then per value: its subjects)
    for k in self.index.rooms:
        if (s := self.subject(k, family)) is not None:
            per[s] = per.get(s, 0) + 1
    fam = self.sets.get(family, {})
    n: dict[str, int] = {}
    for (v, st), subs in fam.items():
        if st == "no" or not subs:
            continue
        no = fam.get((v, "no"), set())
        if got := sum(per.get(s, 0) for s in subs if s not in no):
            n[v] = n.get(v, 0) + got
    return sorted(n.items(), key=lambda kv: -kv[1])

def detail(self, key: str) -> dict[str, Any]:
    """Room panel: every family with its values, states, vetoes and the detector's say."""
    fams: dict[str, Any] = {}
    for fam in LOCKED:
        subj = self.subject(key, fam)
        fams[fam] = {"on": "person" if subj and subj.startswith("p:") else ("off" if subj is None else "room"),
                     "values": [{"value": v, "state": st} for v, st in self.values(subj, fam)],
                     "vetoed": self._in_state(fam, "no", subj) if subj else [],
                     "suggest": self._candidate(key, fam)}
    rk = f"r:{key}"
    runs = parse_runs(self.hosts.get(key, ""))
    got = self.behaviours.get(key)
    b = self.behaviour_of(key)
    fams["room"] = {"on": "room", "values": [{"value": b, "state": "yes" if self._has("room", b, "yes", rk) else "auto"}] if b else [],
                    "since_day": got[1] if got else None, "hosts": len({r[0] for r in runs}),
                    "vetoed": self._in_state("room", "no", rk)}
    fams["habit"] = {"vetoed": self._in_state("habit", "no", rk), "pinned": self._in_state("habit", "yes", rk)}
    return fams

