    def _candidate(self, key: str, family: str) -> list[str]:
        """What the detector says now, when it is sure; [] otherwise."""
        if family == "lang":
            return list(self.speech.speaks.get(key, []))
        if family == "hair":
            from .traits import HAIR

            t = self.traits.rooms.get(key)
            if not t or not t.get("hair"):
                return []
            counts = {h: c for h, c in t["hair"].items() if h in HAIR}
            total = sum(counts.values())
            out = []
            if total >= HAIR_MIN:
                best = max(counts, key=lambda k: counts[k])
                if counts[best] / total >= HAIR_SHARE:
                    out.append(best)
            n = t.get("hair_n", 0)
            if n >= HAIR_MIN and t["hair"].get("highlights", 0) / n >= HIGHLIGHTS_SHARE:
                out.append("highlights")
            if n >= HAIR_MIN and t["hair"].get("short", 0) / n >= SHORT_SHARE:
                out.append("short")
            return out
        if family == "look":
            t = self.traits.rooms.get(key)
            n = (t or {}).get("hair_n", 0)
            out = []
            if n >= HAIR_MIN and (t.get("hair") or {}).get("glasses", 0) / n >= GLASSES_SHARE:
                out.append("glasses")
            tat = (t or {}).get("tat") or [0, 0]
            if tat[0] >= TATTOO_MIN and tat[1] / tat[0] >= TATTOO_SHARE:
                out.append("tattoos")
