async def _lock(self, key: str, family: str, now: int) -> bool:
    subj = self.subject(key, family)
    if subj is None:
        return False
    ck = f"{subj}|{family}"
    if now - self.checked.get(ck, 0) < RECHECK_S:
        return False  # locked (or re-checked) lately
    have = self.values(subj, family)
    if any(st == "yes" for _, st in have):
        return False  # the operator decided
    vetoed = set(self._in_state(family, "no", subj))
    want = [v for v in self._candidate(key, family) if v not in vetoed]
    if not want:
        if have:
            self.checked[ck] = now  # not sure today: keep what was locked
        return False
    self.checked[ck] = now
    if sorted(v for v, _ in have) == sorted(want):
        await self.store.c.execute("UPDATE labels SET checked = ? WHERE subject = ? AND family = ? AND state = 'auto'",
                                   (now, subj, family))
        return False
    for v, _ in have:
        await self._drop(subj, family, v)
    for v in want:
        await self._set(subj, family, v, "auto", now)
    return True

