async def verdict(self, key: str, family: str, value: str, verdict: str) -> dict[str, Any]:
    """``yes`` (lock for good), ``no`` (never again) or ``clear`` (back to the detector)."""
    if family not in PERSON | ROOM or verdict not in ("yes", "no", "clear"):
        raise ValueError("bad family or verdict")
    value = value.strip().lower()[:40]
    if not value:
        raise ValueError("no value")
    # A person label on a rotating room: the operator means this room.
    subj = self.subject(key, family) or f"r:{key}"
    now = int(time.time())
    if verdict == "clear":
        await self._drop(subj, family, value)
        self.checked.pop(f"{subj}|{family}", None)
    elif verdict == "no":
        await self._set(subj, family, value, "no", now)
        self.checked.pop(f"{subj}|{family}", None)  # let the detector offer its next best
    else:
        same = _exclusive().get(family, set())
        if value in same:
            for v, _ in self.values(subj, family):
                if v != value and v in same:
                    await self._drop(subj, family, v)
        await self._set(subj, family, value, "yes", now)
    await self.store.c.commit()
    return self.detail(key)

async def move_persona(self, old: int, new: int) -> None:
    """Identity merge: the gone persona's labels and host days go to the keeper."""
    if old == new:
        return
    a, b = f"p:{old}", f"p:{new}"
    for r in await self.store.rows("SELECT family, value, state, since, checked FROM labels WHERE subject = ?", (a,)):
        mine = any(self._has(r["family"], r["value"], st, b) for st in STATES)
        for st in STATES:
            self._s(r["family"], r["value"], st).discard(a)
        if not mine:
            self._s(r["family"], r["value"], r["state"]).add(b)
            await self.store.c.execute("INSERT OR IGNORE INTO labels VALUES (?, ?, ?, ?, ?, ?)",
                                       (b, r["family"], r["value"], r["state"], r["since"], r["checked"]))
    await self.store.c.execute("DELETE FROM labels WHERE subject = ?", (a,))
    for key, s in list(self.hosts.items()):
        runs = parse_runs(s)
        if any(r[0] == old for r in runs):
            for r in runs:
                if r[0] == old:
                    r[0] = new
            self._set_hosts(key, dump_runs(_merge(runs)))
    await self.store.c.commit()

