def _fold_dir(src: Path, dst: Path) -> int:
    n = 0
    dst.mkdir(parents=True, exist_ok=True)
    for sub in sorted(src.iterdir()):
        target = dst / sub.name
        if sub.is_dir() and target.is_dir():
            for f in sorted(sub.iterdir()):
                if not (target / f.name).exists():
                    shutil.move(str(f), str(target / f.name))
                    n += 1
            shutil.rmtree(sub, ignore_errors=True)
        else:
            shutil.move(str(sub), str(target))
            n += 1
    shutil.rmtree(src, ignore_errors=True)
    return n

def private_price(self) -> float:
    """Private show price per minute in the site's own unit (tokens; flirt4free:
    credits), 0 when privates are off or the listing doesn't say (camsoda)."""
    try:
        p = float(self.extra.get("private_price") or 0)
    except (TypeError, ValueError):
        return 0.0
    return p if p > 0 else 0.0

def event_of(parts: dict[str, float], heat_base: int | None) -> float:
    """The "something is happening" part of a Director score, with a fresh start's heat left out."""
    heat = parts.get("heat", 0.0) * HEAT_WEIGHT if heat_base is not None and heat_base >= HEAT_BASE else 0.0
    return (parts.get("tip", 0.0) + parts.get("toy", 0.0) + heat + parts.get("action", 0.0)
            + parts.get("taste", 0.0) * TASTE_WEIGHT)

async def start(self) -> None:
    if self.sampler.enabled:
        self._task = asyncio.create_task(self._run(), name="moments")

def _roll_day(self) -> None:
    today = time.strftime("%Y%m%d", time.gmtime())
    if today != self.day:
        self.day, self.today = today, 0

def bar(self) -> float:
    """The event a moment needs now: higher while only one credit is banked."""
    return MIN_EVENT + BAR_STEP * max(0.0, min(1.0, 2.0 - self.credits))

def _note(self, key: str, ts: int, rating: int | None, life: float | None) -> None:
    rec = [x for x in self.record.get(key, []) if x[0] != ts] + [(ts, rating, life)]
    self.record[key] = sorted(rec)[-TASTE_LAST:]

def taste(self, key: str, now: float | None = None) -> float:
    """``FLAT`` while the room's latest content verdict in the last ``FLAT_S`` is "doesn't
    react", else 1.0. Never above 1: liked rooms are not boosted (no closed loop)."""
    now = now or time.time()
    for ts, rating, _ in reversed(self.record.get(key, [])):
        if now - ts > FLAT_S:
            break
        if rating is not None and rating not in (-2, -3):
            return FLAT if rating == -1 else 1.0
    return 1.0

def pick(self, now: float | None = None, bar: float = MIN_EVENT) -> dict[str, Any] | None:
    """The best room something is happening in right now that may become a moment."""
    now = now or time.time()
    best = None
    for p in director.rank(self.index, self.chat, self.actions, limit=80, now=now, taste=self.live_taste):
        if not p["happening"]:
            break
        room = p["room"]
        key = room["key"]
        fav = key in self.index.favorites
        if room.get("gender") != "f" and not fav:
            continue
        if room.get("viewers", 0) < MIN_VIEWERS or now - self.last.get(key, -ROOM_GAP_S) < ROOM_GAP_S:
            continue
        if key in self.pending or key in self.sampler._taken:
            continue
        t = self.index.get(key)
        base = t.heat_parts()[0] if t is not None else None
        ev = event_of(p["parts"], base)
        if ev < bar:
            continue
        why = p["why"] if base is not None and base >= HEAT_BASE else [w for w in p["why"] if not w.startswith("audience")]
        taste = self.taste(key, now)
        rank = ev * taste * (director.FAVORITE_BOOST if fav else 1.0)
        if best is None or rank > best["rank"]:
            best = {"key": key, "name": room.get("name") or key.split(":", 1)[1], "event": round(ev, 3),
                    "rank": rank, "viewers": int(room.get("viewers") or 0), "why": why, "parts": p["parts"],
                    "taste": taste}
    if best is not None:
        best["pre"] = self.pre_sound(best["key"], now)
    return best

def _during(self, key: str, a: float, b: float) -> tuple[int, int]:
    """(tokens tipped, seconds of toy run) in the room's followed chat between a and b."""
    cr = self.chat.rooms.get(key)
    if cr is None:
        return 0, 0
    tokens = sum(int(e.get("amount") or 0) for e in list(cr.buf) if e.get("kind") == "tip" and a <= e["t"] <= b)
    toy = sum(max(0.0, min(e, b) - max(s, a)) for s, e in list(getattr(cr, "runs", ())))
    return tokens, int(toy)

async def sweep(self) -> int:
    """Old moments go (kept ones stay), then the oldest until under ``MAX_BYTES``."""
    cutoff = int(time.time() - KEEP_S)
    drop = [r["id"] for r in await self.store.rows("SELECT id FROM moments WHERE kept = 0 AND ts < ?", (cutoff,))]
    total = 0
    for r in await self.store.rows("SELECT id, bytes, kept FROM moments ORDER BY kept DESC, ts DESC"):
        if r["id"] in drop:
            continue
        total += r["bytes"]
        if total > MAX_BYTES and not r["kept"]:
            drop.append(r["id"])
    await self.delete(drop)
    return len(drop)

async def delete(self, ids: list[int]) -> None:
    if not ids:
        return
    await self.store.c.executemany("DELETE FROM moments WHERE id = ?", [(i,) for i in ids])
    await self.store.c.commit()
    self._vecs = None
    for i in ids:
        for part in ("mp4", "jpg"):
            self.path(i, part).unlink(missing_ok=True)

def _out(self, r: dict[str, Any]) -> dict[str, Any]:
    t = self.index.get(r["key"])
    out = {k: v for k, v in r.items() if k != "vec"}
    return {**out, "kept": bool(r["kept"]), "why": json.loads(r["why"]), "parts": json.loads(r["parts"]),
            "live": bool(t is not None and t.room.show == "public"), "similar": r.get("vec") is not None,
            "has_video": self.path(r["id"], "mp4").exists(), "taste": self.taste(r["key"])}

