async def similar(self, mid: int, limit: int = 12, same_room: bool = False) -> list[dict[str, Any]] | None:
    """The moments most like ``mid`` (see the module doc), best first, each with ``sim``;
    None when ``mid`` has no vector (yet)."""
    ids, keys, pic, snd, has = await self._load_vecs()
    at = np.flatnonzero(ids == mid)
    if not len(at):
        return None
    i = int(at[0])
    sim = pic @ pic[i]
    if has[i]:
        sim = np.where(has, SIM_PICTURE * sim + (1 - SIM_PICTURE) * (snd @ snd[i]), sim)
    sim[i] = -np.inf
    if not same_room:
        sim[np.array([k == keys[i] for k in keys])] = -np.inf
    best = [int(j) for j in np.argsort(-sim)[:limit] if np.isfinite(sim[j])]
    if not best:
        return []
    want = [int(ids[j]) for j in best]
    rows = {r["id"]: r for r in await self.store.rows(
        f"SELECT * FROM moments WHERE id IN ({','.join('?' * len(want))})", tuple(want))}
    return [{**self._out(rows[m]), "sim": round(float(sim[j]), 3)} for m, j in zip(want, best, strict=True)
            if m in rows]

