def _message(room: dict[str, Any], headline: str, note: str = "") -> dict[str, Any]:
    site = SITES.get(room["site"])
    label = site.label if site else room["site"]
    page = site.page_url(room["room"]) if site else ""
    here = f"{settings.public_url.rstrip('/')}/#/room/{room['site']}/{room['room']}" if settings.public_url else ""
    e = html.escape
    lines = [f"<b>{e(room['name'])}</b> {e(headline)}",
             f"{e(label)} · " + ("offline" if room.get("offline") else f"{room.get('viewers', 0):,} viewers")]
    if room.get("subject"):
        lines.append(f"<i>{e(room['subject'][:180])}</i>")
    if note:
        lines.append(e(note))
    links = []
    if here:
        links.append(f'<a href="{e(here)}">Panopticam</a>')
    if page:
        links.append(f'<a href="{e(page)}">{e(label)}</a>')
    if links:
        lines.append(" · ".join(links))
    return {"text": "\n".join(lines), "photo": room.get("thumb") or ""}

