async def _refresh_loop(self) -> None:
    while True:
        await asyncio.sleep(REFRESH_EVERY_S)
        try:
            await self.refresh()
        except asyncio.CancelledError:
            raise
        except Exception as e:
            log.warning("recording refresh failed: %s", e)

    async def refresh(self) -> None:
        mine = await self.store.active_recordings()
        if not mine:
            return
        status = {j["id"]: j for j in await self.jobs(200)}
        for rec in mine:
            job = status.get(rec["job_id"])
            st = job.get("status") if job else None
            if st and st not in ACTIVE:
                await self.store.update_recording(rec["job_id"], status=st, ended=int(time.time()),
                                                  error=(job or {}).get("error"))
                continue
            if not st and time.time() - rec["started"] > 86400:
                await self.store.update_recording(rec["job_id"], status="lost", ended=int(time.time()))
                continue
            if st:
                await self.store.update_recording(rec["job_id"], status=st)
            if rec.get("auto") and time.time() - rec["started"] > AUTO_MAX_S:
                log.info("auto recording %s (%s): %d min, stopped", rec["key"], rec["auto"], AUTO_MAX_S // 60)
