def due(self, now: float | None = None) -> list[str]:
    """Rooms reading empty right now that may get a frame, longest-waiting first."""
    now = now or time.time()
    self._roll_day()
    if self.today >= settings.room_frames_per_day:
        return []
    out = []
    states = self.vision.states
    # Live rooms only (the states dict keeps every room ever read: walking it took ~0.8 s, on the
    # event loop, every 20 s — 6 Oct 2026).
    for key, t in list(self.index.rooms.items()):
        st = states.get(key)
        if st is None or st.get("state") != "empty" or now - st.get("ts", 0) > FRESH_S:
            continue
        if t.room.site not in SITES or not t.room.playable or t.room.show != "public":
            continue
        if not self.index.in_scope(key) or self.identity(key) is None:
            continue
        if self.per_room.get(key, 0) >= PER_ROOM or now - self.last.get(key, 0.0) < ROOM_GAP_S:
            continue
        out.append(key)
    return sorted(out, key=lambda k: self.last.get(k, 0.0))

