    """Counts from the frame loop's last pass (6 Oct 2026: calling ``due()`` here walked every room's
    state on each /api/status poll — 0.7–1 s, every 5 s per open tab); files counted once a minute."""
    self._roll_day()
    now = time.time()
    if now - self._waiting[0] > 60:
        self._waiting = (now, sum(1 for _ in self.root.rglob("*.jpg")) if self.root.exists() else 0)
    return {"enabled": self.enabled, "per_day": settings.room_frames_per_day, "today": self.today,
            "empty_now": self._due_n, "waiting_for_pc": self._waiting[1], **self.stats}

