async def list_rooms(self) -> list[Room]:
    first = await self._page(0)
    total = int(first.get("total_count") or 0)
    pages = [first]
    offsets = list(range(CB_PAGE, total + CB_PAGE, CB_PAGE))
    sem = asyncio.Semaphore(settings.chaturbate_concurrency)

    async def one(off: int) -> dict[str, Any] | None:
        async with sem:
            try:
                return await self._page(off)
            except FetchError as e:
                if not e.status:  # no answer at all: fail the sweep (rooms kept), as before
                    raise
                log.warning("chaturbate page %s: %s", off, e)
                return None

    pages += [p for p in await asyncio.gather(*(one(o) for o in offsets)) if p]
    # The list moves while it is paged: a room can appear on two pages.
    seen: dict[str, Room] = {}
    for p in pages:
        for r in p.get("rooms") or []:
            room = self._room(r)
            if room.room and room.room not in seen:
                seen[room.room] = room
    return list(seen.values())

