async def list_rooms(self) -> list[Room]:
    url = f"{C4}/api/directoryCams?directoryJson=true&online=true&url=true&page="
    first = await net.json(self.id, url + "1")
    size = len(first.get("users") or []) or 60
    total = int(first.get("totalCount") or 0)
    sem = asyncio.Semaphore(4)

    async def one(n: int) -> dict[str, Any] | None:
        async with sem:
            try:
                return await net.json(self.id, url + str(n))
            except FetchError as e:
                if not e.status:  # no answer at all: fail the sweep (rooms kept), as before
                    raise
                log.warning("cam4 page %s: %s", n, e)
                return None

    pages = [first] + [p for p in await asyncio.gather(*(one(n) for n in range(2, min(total // size + 2, 200))))
                       if p]
    out: dict[str, Room] = {}
    for p in pages:
