def clean_line(text: str | None, logprob: float | None, rep: bool) -> str | None:
    """The line worth keeping from a transcript, or None (see the module doc)."""
    if not text or rep or logprob is None or logprob < MIN_LOGPROB:
        return None
    bare = " ".join(_NOISE.sub("", text).split())
    if not _LETTERS.search(bare) or HALLUCINATIONS.search(bare):
        return None
    return bare

def junk(text: str | None) -> bool:
    """A transcript with no words at all ("♪", "[M]", "..."): the clip was not speech."""
    return text is not None and not _LETTERS.search(_NOISE.sub("", text))

def fts_query(q: str) -> str | None:
    """Words of a search box → an FTS5 query (every word; the last one as a prefix)."""
    words = re.findall(r"[^\W_]+", q.lower())
    if not words:
        return None
    return " ".join([f'"{w}"' for w in words[:-1]] + [f'"{words[-1]}"*'])

def speaks_of(langs: dict[str, int]) -> list[str]:
    """The settled languages of a tally, most heard first ([] while unsure)."""
    total = sum(langs.values())
    if not total:
        return []
    ranked = sorted(langs.items(), key=lambda kv: -kv[1])
    top, n = ranked[0]
    if n < 2 or n / total < 0.6:
        return []
    out = [top]
    if len(ranked) > 1 and ranked[1][1] >= 2 and ranked[1][1] / total >= SECOND_SHARE:
        out.append(ranked[1][0])
    return out

def english_level(langs: dict[str, int], e: list[float] | None = None) -> str | None:
    """fluent / some / none, or None while too little was heard (see the module doc)."""
    total = sum(langs.values())
    en = langs.get("en", 0)
    if not en:
        return "none" if total >= 3 else None
    if total < 2:
        return None
    clear = not e or not e[0] or e[1] / e[0] >= FLUENT_LOGPROB
    return "fluent" if en >= 2 and en / total >= FLUENT_SHARE and clear else "some"

async def load(self) -> None:
    await self.store.c.executescript(SCHEMA)
    await self.store.c.commit()
    for r in await self.store.rows("SELECT key, body FROM room_speech WHERE ts >= ?", (int(time.time() - FORGET_S),)):
        rec = orjson.loads(r["body"])
        self.rec[r["key"]] = rec
        if got := speaks_of(rec.get("l") or {}):
            self.speaks[r["key"]] = got
    # English log-probs: rooms heard before 13 Oct get them from their kept lines (7 days).
    for r in await self.store.rows("SELECT key, COUNT(*) AS n, SUM(logprob) AS lp FROM heard WHERE lang = 'en' GROUP BY key"):
        if (rec := self.rec.get(r["key"])) is not None and "e" not in rec:
            rec["e"] = [int(r["n"]), round(float(r["lp"]), 3)]
    for key, rec in self.rec.items():
        if lvl := english_level(rec.get("l") or {}, rec.get("e")):
            self.english[key] = lvl
    for r in await self.store.rows("SELECT id, ts, key, lang, text FROM heard ORDER BY id DESC LIMIT ?", (RECENT,)):
        self.recent.appendleft(dict(r))

def consider(self, key: str, sound: str | None, long: bool = False) -> None:
    """A clip was just heard by the tower; queue it for Whisper if its room is due."""
    if sound in (None, "muted", "silent") or key in self.queue:
        return
    now = time.time()
    if key not in self.index.rooms:
        return
    rec = self.rec.get(key)
    if not self._due(key, now) or self.rests(key):
        # Its language is known: listened to again only for Heard, if it talks, last in line.
        if not (rec and rec.get("l") and now - rec.get("last", 0) >= HEARD_RETRY_S):
            return
        prio = -2 + (1 if sound == "talking" else 0)
    else:
        confirming = rec is not None and rec.get("l") and key not in self.speaks
        prio = (4 if confirming else 0) + (2 if sound == "talking" else (1 if long else 0))
    if len(self.queue) >= QUEUE:
        worst = min(self.queue, key=lambda k: self.queue[k][:2])
        if self.queue[worst][:2] >= (prio, now):
            return
        del self.queue[worst]
    self.queue[key] = (prio, now, long)

