    """Best queued clips first, with their sound (the room's latest sample of it)."""
    import base64

    out = []
    now = time.time()
    for key in sorted(self.queue, key=lambda k: self.queue[k][:2], reverse=True):
        if len(out) >= limit:
            break
        _, at, long = self.queue.pop(key)
        if now - at > 600 or key not in self.index.rooms:
            continue
        path = (self.sampler.long_paths(key)[2] if long else self.sampler.paths(key)[1])
        if not path.exists():
            path = self.sampler.paths(key)[1]
        try:
            audio = path.read_bytes()
        except OSError:
            continue
        rec = self.rec.setdefault(key, {"l": {}, "t": 0, "last": 0})
        rec["last"] = int(now)  # asked: not due again for a while, whatever comes back
        out.append({"key": key, "audio": base64.b64encode(audio).decode()})
    return out

