def summary(self, key: str) -> dict[str, Any] | None:
    rec = self.rec.get(key)
    if rec is None:
        return None
    e = rec.get("e") or [0, 0.0]
    return {"speaks": self.speaks.get(key, []), "heard": dict(sorted(rec.get("l", {}).items(), key=lambda kv: -kv[1])),
            "tries": rec.get("t", 0), "english": self.english.get(key),
            "english_logprob": round(e[1] / e[0], 2) if e[0] else None}

def live_langs(self) -> list[tuple[str, int]]:
    """Languages of the live rooms, most rooms first (for Browse's menu)."""
    n: dict[str, int] = {}
    for key, langs in self.speaks.items():
        if key in self.index.rooms:
            for lang in langs:
                n[lang] = n.get(lang, 0) + 1
    return sorted(n.items(), key=lambda kv: -kv[1])

def status(self) -> dict[str, Any]:
    agree = checked = 0
    for key, langs in self.speaks.items():
        t = self.index.rooms.get(key)
        want = COUNTRY_LANG.get((t.room.country or "").upper()) if t is not None else None
        if want:
            checked += 1
            agree += want in langs
    live = sum(1 for k in self.speaks if k in self.index.rooms)
    return {"rooms": len(self.rec), "settled": len(self.speaks), "settled_live": live, "queued": len(self.queue),
            "heard": self.heard, "confident": self.confident, "lines": self.lines, "lines_dropped": self.dropped,
            "country_agrees": round(agree / checked, 3) if checked else None, "country_checked": checked,
            "langs_live": self.live_langs()[:12]}

async def start(self) -> None:
    await self.store.c.executescript(SCHEMA)
    have = {r["name"] for r in await self.store.rows("PRAGMA table_info(stills)")}
    for col in COLUMNS:
        if col.split()[0] not in have:
            await self.store.c.execute(f"ALTER TABLE stills ADD COLUMN {col}")
    await self.store.c.commit()
    for r in await self.store.rows("SELECT * FROM stills"):
        self.state[r["key"]] = {k: r[k] for k in ("visits", "frames", "last", "done", "identity", "again", "rnd")}
    if not settings.stills:
        return
    (self.root / "work").mkdir(parents=True, exist_ok=True)
    (self.root / "ready").mkdir(parents=True, exist_ok=True)
    self._tasks = [asyncio.create_task(self._loop(i)) for i in range(CONCURRENCY)]

async def visit(self, key: str) -> int:
    site, room = key.split(":", 1)
    folder = self.root / "work" / f"stills__{site}__{room}"
    folder.mkdir(parents=True, exist_ok=True)
    st = self.state.get(key) or {"visits": 0, "frames": 0}
    v = int(st["visits"] or 0)
    if site in SNAPSHOT_SITES:
        t = self.index.get(key)
        if t is None or not t.room.thumb:
            return await self._save(key, got=0)
        sep = "&" if "?" in t.room.thumb else "?"
        data = await net.get(f"{site}-cdn", f"{t.room.thumb}{sep}_={int(time.time())}")
        if len(data) < 2000 or not await asyncio.to_thread(self._keep, data, folder):
            return await self._save(key, got=0)
        (folder / f"v{v:02d}_00.{self._ext(t.room.thumb)}").write_bytes(data)
        return await self._save(key, got=1)
    s = await resolve(site, room)
    if not s.live or not s.levels:
        return await self._save(key, got=0, visit=False)
    level = min(s.levels, key=lambda lv: (abs((lv.height or 0) - HEIGHT), -(lv.bandwidth or 0)))
    video, seconds = await self.sampler._track(site, level.url, SPAN_S)
    per = FRAMES // VISITS
    got = await asyncio.to_thread(self._frames, video, seconds or SPAN_S, per, folder, v,
                                  lambda b: self._keep(b, folder))
    return await self._save(key, got=got)

def _ext(url: str) -> str:
    tail = url.rsplit("/", 1)[-1].lower()
    return "webp" if tail.endswith(".webp") or "doppiocdn" in url else "jpg"

def dhash(data: bytes, n: int = 16) -> np.ndarray:
    im = Image.open(io.BytesIO(data))
    im.draft("L", (8 * (n + 1), 8 * n))  # JPEG: decode at up to 1/8 scale, ~10x less work for a 17x16 hash
    a = np.asarray(im.convert("L").resize((n + 1, n)), dtype=np.int16)
    return (a[:, 1:] > a[:, :-1]).ravel()

def _kept_hashes(self, folder: Path) -> list[np.ndarray]:
    got = self._hashes.get(str(folder))
    if got is None:  # after a restart: rebuild from the frames already there
        got = []
        for f in sorted(folder.glob("v*_*.*")):
            try:
                got.append(self.dhash(f.read_bytes()))
            except Exception:
                continue
        self._hashes[str(folder)] = got
    return got

def _keep(self, data: bytes, folder: Path) -> bool:
    """Not a copy of a frame already kept for this room, and one clear female face
    (VPS pre-filter; every frame passes that part without the model)."""
    try:
        h = self.dhash(data)
    except Exception:
        return False
    kept = self._kept_hashes(folder)
    if any(int(np.count_nonzero(h != k)) <= DUP_BITS for k in kept):
        self.duplicates += 1
        return False
    if self.filter is not None:
        try:
            ok = self.filter.one_face(data)
        except Exception:
            ok = False
        if not ok:
            self.dropped += 1
            return False
    kept.append(h)
    return True

