def forecast_log(self, since: int, until: int) -> list[tuple[int, str, int, float, float]]:
    """(ts, key, horizon, chance, share) logged in [since, until). Read-only, run in a thread."""
    db = sqlite3.connect(f"file:{self.path.as_posix()}?mode=ro", uri=True)
    try:
        return db.execute("SELECT ts, key, horizon, chance, share FROM forecast_log WHERE ts >= ? AND ts < ?",
                          (since, until)).fetchall()
    finally:
        db.close()

