def __init__(self, store: Store) -> None:
    self.store = store
    self.w: np.ndarray | None = None
    self.b = 0.0
    self.meta: dict[str, Any] = {}
    #: key -> recent (ts, p), newest last
    self.recent: dict[str, deque[tuple[int, float]]] = {}
    #: which rooms count (index.in_scope, set by app.py): women's / couples' rooms, sites we show
    self.scope: Any = None

async def load(self) -> None:
    raw = await self.store.get_kv(KV)
    if raw:
        try:
            d = json.loads(raw)
            self._set(np.frombuffer(base64.b64decode(d["w"]), np.float32).copy(), float(d["b"]), d.get("meta") or {})
        except (ValueError, KeyError) as e:
            log.warning("taste: stored head unreadable (%s)", e)

def _set(self, w: np.ndarray, b: float, meta: dict[str, Any]) -> None:
    if w.shape != (X_DIM,) or not np.isfinite(w).all() or not np.isfinite(b):
        raise ValueError(f"taste head must be {X_DIM} finite weights")
    self.w, self.b, self.meta = w.astype(np.float32), float(b), meta
    self.recent.clear()  # old p's came from another head

def on_clip(self, key: str, ts: int, x: np.ndarray) -> None:
    """A room's new clip (``Actions.ingest``)."""
    if self.w is None:
        return
    p = float(_sigmoid(float(x.astype(np.float32) @ self.w) + self.b))
    q = self.recent.setdefault(key, deque(maxlen=SMOOTH))
    if q and q[-1][0] == ts:
        q.pop()
    q.append((ts, p))

def of(self, key: str, now: float | None = None, fresh_s: float = SMOOTH_S) -> float | None:
    """The room's taste now: mean p of its recent clips (the newest within ``fresh_s``), None = no clip."""
    q = self.recent.get(key)
    if not q:
        return None
    now = now or time.time()
    if now - q[-1][0] > fresh_s:
        if now - q[-1][0] > FORGET_S:
            self.recent.pop(key, None)
        return None
    ps = [p for ts, p in q if now - ts <= SMOOTH_S]
    return sum(ps) / len(ps)

def scores(self, keys: Any = None, fresh_s: float = SMOOTH_S) -> dict[str, float]:
    now = time.time()
    out = {}
    for k in list(keys if keys is not None else self.recent.keys()):
        if keys is None and self.scope is not None and not self.scope(k):
            continue
        p = self.of(k, now, fresh_s)
        if p is not None:
            out[k] = p
    return out

def forget(self, keys: list[str]) -> None:
    for k in keys:
        self.recent.pop(k, None)

def status(self) -> dict[str, Any]:
    sc = self.scores()
    return {"on": self.w is not None, **{k: v for k, v in self.meta.items() if k != "w"},
            "rooms": len(sc), "above": sum(p >= SHOW_P for p in sc.values())}

def toy_tagged(room: Any) -> bool:
    text = " ".join([*(room.tags or []), room.subject or ""]).lower()
    return bool(TOY_WORDS.search(text))

def buzz_action(actions: dict[int, dict[str, Any]]) -> int | None:
    """The "Toy buzzing" action (by name: the operator may rename or re-create it)."""
    for aid, a in actions.items():
        name = str(a.get("name") or "").lower()
        if "toy" in name and ("buzz" in name or "vibrat" in name):
            return aid
    return None

def __init__(self, index: Any, sampler: Any) -> None:
    self.index = index
    self.sampler = sampler
    self.root = settings.harvest_dir / "toys"
    self.queue: asyncio.Queue[tuple[str, str, float]] = asyncio.Queue(maxsize=20)
    self.day = ""
    self.taken: dict[str, int] = {"pos": 0, "neg": 0}
    self.per_room: dict[str, int] = {}
    self.pending: set[str] = set()
    self.last_neg = 0.0
    self.stats = {"ok": 0, "failed": 0}
    self._task: asyncio.Task[None] | None = None

def _roll_day(self) -> None:
    today = time.strftime("%Y%m%d", time.gmtime())
    if today != self.day:
        self.day, self.taken, self.per_room = today, {"pos": 0, "neg": 0}, {}

    def consider(self, scores: dict[int, dict[str, float]], actions: dict[int, dict[str, Any]]) -> int:
        """Called with each batch of clip scores; queues captures. Returns how many."""
        if not self.enabled:
            return 0
        aid = buzz_action(actions)
        if aid is None or aid not in scores:
            return 0
