def chat_toy(self, key: str, secs: int | None) -> bool:
    """The room's chat just said its toy is running (``chat.py``): the surest positive there
    is, named ``__chat__``. Same daily budget and per-room cap as sound positives; skipped
    when the run is too short to still be on by the time a segment is fetched."""
    if not self.enabled or (secs is not None and secs < 5):
        return False
    self._roll_day()
    cap = settings.toy_frames_per_day
    t = self.index.get(key)
    if t is None or t.room.site not in SITES or not t.room.playable or t.room.show != "public":
        return False
    if key in self.pending or self.per_room.get(key, 0) >= PER_ROOM:
        return False
    if self.taken["pos"] >= cap - int(cap * NEG_SHARE):
        return False
    try:
        self.queue.put_nowait((key, "chat", 1.0))
    except asyncio.QueueFull:
        return False
    self.pending.add(key)
    self.taken["pos"] += 1
    self.per_room[key] = self.per_room.get(key, 0) + 1
    return True

async def stop(self) -> None:
    if self._task:
        self._task.cancel()

async def _run(self) -> None:
    while True:
        key, kind, p = await self.queue.get()
        try:
            if await self.capture(key, kind, p):
                self.stats["ok"] += 1
            else:
                raise RuntimeError("no frame")
        except Exception as e:
            self.stats["failed"] += 1
            bucket = "neg" if kind == "neg" else "pos"  # chat captures spend the positives' budget
            self.taken[bucket] = max(0, self.taken[bucket] - 1)
            log.info("toy frame %s (%s): %s", key, kind, e)
        finally:
            self.pending.discard(key)
        await asyncio.sleep(GAP_S)

def status(self) -> dict[str, Any]:
    self._roll_day()
    ready = self.root / "ready"
    return {"enabled": self.enabled, "per_day": settings.toy_frames_per_day, "today": dict(self.taken),
            "queued": self.queue.qsize(), "waiting_for_pc": sum(1 for _ in ready.glob("*.jpg")) if ready.exists()
            else 0, **self.stats}

def get(self, key: Any, default: Any = None) -> Any:
    v = dict.get(self, key, default)
    if isinstance(v, bytes):
        v = orjson.loads(v)
        dict.__setitem__(self, key, v)
    return v

def peek(v: Any) -> Any:
    """A raw value from ``items()`` decoded, without warming it."""
    return orjson.loads(v) if isinstance(v, bytes) else v

def chill(self, warm: Any, dirty: set[str]) -> int:
    """Back to bytes: every record not in ``warm`` (the live rooms) and not waiting to be written."""
    n = 0
    for k, v in list(self.items()):
        if not isinstance(v, bytes) and k not in warm and k not in dirty:
            dict.__setitem__(self, k, orjson.dumps(v))
            n += 1
    return n

def set_vocab(self, embed: Any) -> None:
    """Embed the tag prompts once (``embed``: text → unit vector, SigLIP's text tower)."""
    import numpy as np

    self.vocab = {g: (list(tags), np.stack([embed(p) for p in tags.values()]).astype(np.float32))
                  for g, tags in TAG_GROUPS.items()}
    self.hair_vocab = {g: (list(tags), np.stack([embed(p) for p in tags.values()]).astype(np.float32))
                       for g, (tags, _, _) in HEAD_GROUPS.items()}
    self.tat_vocab = (list(TATTOOS), np.stack([embed(p) for p in TATTOOS.values()]).astype(np.float32))

def set_sound_vocab(self, embed: Any) -> None:
    import numpy as np

    self.sound_vocab = (list(SOUND_PROMPTS), np.stack([embed(p) for p in SOUND_PROMPTS.values()]).astype(np.float32))

def sound_of(self, loud: float, a: Any) -> str | None:
    """'muted' (no audio stream), 'silent', the winning SOUND_PROMPTS name, or None."""
    if loud == NO_AUDIO_DB:
        return "muted"
    if loud <= SILENT_DB:
        return "silent"
    if a is None or self.sound_vocab is None:
        return None
    import numpy as np

    names, T = self.sound_vocab
    return names[int(np.argmax(T @ np.asarray(a, np.float32)))]

def hair_probs(self, X: Any) -> Any:
    """Hair-colour logits (before the learned bias) for unit head vectors (n, d)."""
    names, T = self.hair_vocab["hair"]
    return SIGLIP_SCALE * (X @ T.T)

async def flush_heads(self) -> int:
    """Fold the head crops seen since the last call into each room's stored mean."""
    import numpy as np

    if not self._heads:
        return 0
    pending, self._heads = self._heads, {}
    keys = list(pending)
    old: dict[str, tuple[int, Any]] = {}
    for i in range(0, len(keys), 500):
        chunk = keys[i:i + 500]
        for r in await self.store.rows(f"SELECT key, n, v FROM room_heads WHERE key IN ({','.join('?' * len(chunk))})", chunk):
            old[r["key"]] = (r["n"], np.frombuffer(r["v"], np.float16).astype(np.float32))
    now = int(time.time())
    rows = []
    for k, (s, n) in pending.items():
        n0, m0 = old.get(k, (0, None))
        total = s + (m0 * n0 if m0 is not None and m0.shape == s.shape else 0)
        rows.append((k, n0 + n, (total / (n0 + n)).astype(np.float16).tobytes(), now))
    await self.store.c.executemany("INSERT OR REPLACE INTO room_heads VALUES (?, ?, ?, ?)", rows)
    await self.store.c.commit()
    return len(rows)

async def head_vectors(self, keys: list[str]) -> dict[str, Any]:
    """key -> unit mean head vector, for the rooms that have one."""
    import numpy as np

    out: dict[str, Any] = {}
    for i in range(0, len(keys), 500):
        chunk = keys[i:i + 500]
        for r in await self.store.rows(f"SELECT key, v FROM room_heads WHERE key IN ({','.join('?' * len(chunk))})", chunk):
            v = np.frombuffer(r["v"], np.float16).astype(np.float32)
            out[r["key"]] = v / (np.linalg.norm(v) or 1.0)
    return out

def _room(self, key: str) -> dict[str, Any]:
    t = self.rooms.get(key)
    if t is None:
        t = self.rooms[key] = {"since": int(time.time()), "looks": 0, "states": {}, "clips": 0, "acts": {},
                               "loud": 0.0, "motion": 0.0, "long": 0, "prof": []}
    self._dirty.add(key)
    return t

    def summary(self, key: str, action_names: dict[int, str]) -> dict[str, Any] | None:
        """Shares a person can read, or None when there is too little yet."""
        t = self.rooms.get(key)
        if t is None or (t["looks"] < MIN_LOOKS and t["clips"] < MIN_CLIPS):
            return None
        out: dict[str, Any] = {"since": t["since"], "looks": t["looks"], "clips": t["clips"], "long": t["long"]}
        if t["looks"] >= MIN_LOOKS:
            out["states"] = {s: round(n / t["looks"], 3) for s, n in sorted(t["states"].items(), key=lambda x: -x[1])}
        if t["clips"] >= MIN_CLIPS:
            out["loud_db"] = round(t["loud"] / t["clips"], 1)
            out["motion"] = round(t["motion"] / t["clips"], 4)
            acts = []
            for aid, (n, hits, psum) in t["acts"].items():
                if int(aid) in action_names and n >= MIN_CLIPS:
                    acts.append({"id": int(aid), "name": action_names[int(aid)], "share": round(hits / n, 3),
                                 "mean_p": round(psum / n, 3), "clips": n})
            out["actions"] = sorted(acts, key=lambda a: -a["share"])
        if t["long"] and t["prof"]:
            out["profile"] = {name: round(t["prof"][i] / t["long"], 3) for i, name in PROFILE_NAMES.items()
                              if i < len(t["prof"])}
        n = t.get("tag_looks", 0)
        if n >= MIN_LOOKS and t.get("tags"):
            # Per group, the tags that won at least a tenth of the looks.
            groups: dict[str, list[dict[str, Any]]] = {}
            for tag, c in sorted(t["tags"].items(), key=lambda x: -x[1]):
                if c / n >= 0.1 and tag in TAG_GROUP_OF:
                    groups.setdefault(TAG_GROUP_OF[tag], []).append({"tag": tag, "share": round(c / n, 3)})
            out["looks_like"] = groups
            out["tag_looks"] = n
        if (hn := t.get("hair_n", 0)) >= 3 and t.get("hair"):
            out.setdefault("looks_like", {})["hair"] = [
                {"tag": h, "share": round(c / hn, 3)} for h, c in sorted(t["hair"].items(), key=lambda x: -x[1]) if c / hn >= 0.1]
