def share(self, key: str, trait: str) -> tuple[float, int] | None:
    """(share, readings) of one room for ``state:``/``action:``/``tag:`` — habit alerts."""
    t = self.rooms.get(key)
    if t is None:
        return None
    kind, _, what = trait.partition(":")
    if kind == "state" and t["looks"]:
        return t["states"].get(what, 0) / t["looks"], t["looks"]
    if kind == "action" and (a := t["acts"].get(what)) and a[0]:
        return a[1] / a[0], a[0]
    if kind == "tag" and t.get("tag_looks"):
        return t.get("tags", {}).get(what, 0) / t["tag_looks"], t["tag_looks"]
    return None

def top(self, trait: str, keys: list[str] | None = None, min_n: int = 20) -> list[tuple[str, float, int]]:
    """(room, share, readings) for ``state:<name>``, ``action:<id>`` or ``tag:<name>``,
    highest share first."""
    kind, _, what = trait.partition(":")
    out = []
    for k, raw in list(self.rooms.items()):
        if keys is not None and k not in keys:
            continue
        t = Cold.peek(raw)
        if kind == "state" and t["looks"] >= min_n:
            out.append((k, t["states"].get(what, 0) / t["looks"], t["looks"]))
        elif kind == "action" and (a := t["acts"].get(what)) and a[0] >= min_n:
            out.append((k, a[1] / a[0], a[0]))
        elif kind == "tag" and t.get("tag_looks", 0) >= min_n:
            out.append((k, t.get("tags", {}).get(what, 0) / t["tag_looks"], t["tag_looks"]))
    out.sort(key=lambda x: (-x[1], -x[2]))
    return out

def _unb64(s: str, dim: int) -> np.ndarray:
    a = np.frombuffer(base64.b64decode(s), dtype=np.float16).astype(np.float32)
    if a.shape != (dim,):
        raise ValueError(f"expected {dim} floats, got {a.shape}")
    n = np.linalg.norm(a)
    return a / n if n else a

def unload_if_idle(self, idle_s: float = TEXT_IDLE_S) -> bool:
    with self._lock:
        if self._sess is None or time.time() - self.used < idle_s:
            return False
        self._sess = None
        return True

    def __init__(self, store: Store, index: Index):
        self.store = store
        self.index = index
