        #: persona id → the operator's own name for it (wins over the Atlas label)
        self.names: dict[int, str] = {}
        #: keys handed to a worker and not yet answered, per role: key → when
        self._leases: dict[str, dict[str, float]] = {"all": {}, "tower": {}, "faces": {}}
        self._leased = self._leases["all"]
