        self.face_seen: dict[str, int] = {}
        #: room → recent views (ts, unit SigLIP) the room's look is averaged from
        self.views: dict[str, list[tuple[int, np.ndarray]]] = {}
        self.worker_seen = 0.0
        self.role_seen: dict[str, float] = {}
        #: room → last tower attempt whose thumbnail couldn't be read (not re-queued at once)
        self.tried: dict[str, float] = {}
