def _set_sum(self, key: str, total: np.ndarray, count: int) -> None:
    """Centroid from the sum of ``count`` unit vectors (the mean's direction is the sum's)."""
    n = np.linalg.norm(total)
    if n:
        self.face[key] = ((total / n).astype(np.float16), count)

def trim_ram(self, now: float | None = None) -> int:
    """Drop in-memory vectors of offline rooms (they stay in SQLite): looks read more than
    ``CLIP_RAM_DAYS`` ago, faces more than ``RAM_DAYS`` ago. Returns how many rooms were trimmed."""
    now = now or time.time()
    cutoff, clip_cutoff = now - RAM_DAYS * 86400, now - CLIP_RAM_DAYS * 86400
    old = [k for k, (ts, v) in self.clip.items() if ts < clip_cutoff and k not in self.index.rooms
           and (v is not _NO_VECTOR or (ts < cutoff and k in self.face))]
    for k in old:
        ts = self.clip[k][0]
        self.clip[k] = (ts, _NO_VECTOR)
        if ts < cutoff:
            self.face.pop(k, None)
    return len(old)

def _db_rows(self, sql: str, args: tuple[Any, ...]) -> list[tuple[Any, ...]]:
    """A read on a connection of its own: the lazy loaders run in request handlers
    that are synchronous, off the event loop."""
    import sqlite3
    db = sqlite3.connect(f"file:{self.store.path.as_posix()}?mode=ro", uri=True)
    try:
        return db.execute(sql, args).fetchall()
    finally:
        db.close()

def _clip_of(self, key: str) -> np.ndarray | None:
    got = self.clip.get(key)
    if got is not None and got[1].any():
        return got[1].astype(np.float32)
    rows = self._db_rows("SELECT clip FROM vision WHERE key = ? AND clip IS NOT NULL", (key,))
    if not rows:
        return None
    v = np.frombuffer(rows[0][0], np.float16).astype(np.float32)
    return v / (np.linalg.norm(v) or 1.0) if v.shape == (DIM,) and v.any() else None

def _face_of(self, key: str) -> tuple[np.ndarray, int] | None:
    got = self.face.get(key)
    if got is not None:
        return got[0].astype(np.float32), got[1]
    vs = [np.frombuffer(e, np.float16).astype(np.float32) for (e,) in
          self._db_rows("SELECT emb FROM faces WHERE key = ?", (key,))]
    vs = [v / (np.linalg.norm(v) or 1) for v in vs if v.shape == (FACE_DIM,)]
    if not vs:
        return None
    m = np.mean(vs, axis=0)
    return m / (np.linalg.norm(m) or 1.0), len(vs)

async def prune(self, keep_days: int = VISION_KEEP_DAYS, now: float | None = None) -> int:
    """Forget vectors, faces and persona rows of rooms gone ``keep_days``."""
    cutoff = (now or time.time()) - keep_days * 86400
    linked = {k for pair in self.links for k in pair}
    rooms_of: dict[int, int] = {}
    for p in self.persona.values():
        rooms_of[p["id"]] = rooms_of.get(p["id"], 0) + 1

    def keep(k: str) -> bool:
        p = self.persona.get(k)
        return (k in self.index.rooms or k in self.index.favorites or k in linked
                or (p is not None and (rooms_of[p["id"]] > 1 or p["id"] in self.names)))

    old = [k for k, (ts, _) in self.clip.items() if ts < cutoff and not keep(k)]
    if not old:
        return 0
    rows = [(k,) for k in old]
    for table in ("vision", "faces", "personas"):
        await self.store.c.executemany(f"DELETE FROM {table} WHERE key = ?", rows)
    await self.store.c.commit()
    for k in old:
        self.clip.pop(k, None)
        self.face.pop(k, None)
        self.persona.pop(k, None)
        self.states.pop(k, None)
    return len(old)

