def _live_matrix(self) -> tuple[list[str], np.ndarray]:
    keys = [k for k in self.index.rooms if k in self.clip and self.clip[k][1].any()]
    if not keys:
        return [], np.zeros((0, DIM), np.float32)
    return keys, np.stack([self.clip[k][1] for k in keys]).astype(np.float32)

def scores_for_text(self, text: str) -> dict[str, float]:
    keys, m = self._live_matrix()
    if not keys:
        return {}
    s = m @ self.text.embed(text)
    return dict(zip(keys, s.tolist(), strict=True))

def scores_like(self, key: str) -> dict[str, float]:
    ref = self._clip_of(key)
    if ref is None:
        return {}
    keys, m = self._live_matrix()
    if not keys:
        return {}
    s = m @ ref
    out = dict(zip(keys, s.tolist(), strict=True))
    out.pop(key, None)
    return out

def _face_matrix(self) -> tuple[np.ndarray, list[str]]:
    """Every face centroid stacked once (12 Oct 2026: stacking 179k little arrays on each call made the
    room panel's matches take 4-8 s). Rebuilt every ``FACE_MATRIX_S`` or when the room count changes;
    the dict's vectors become views of its rows, so the faces are held once, not twice."""
    with self._fm_lock:
        if len(self._fm_keys) == len(self.face) and time.monotonic() - self._fm_at < FACE_MATRIX_S:
            return self._fm, self._fm_keys
        items = list(self.face.items())
        m = (np.stack([v[0] for _, v in items]).astype(np.float16, copy=False) if items
             else np.zeros((0, FACE_DIM), np.float16))
        for i, (k, (vec, n)) in enumerate(items):
            cur = self.face.get(k)
            if cur is not None and cur[0] is vec:  # not replaced meanwhile
                self.face[k] = (m[i], n)
        self._fm, self._fm_keys, self._fm_at = m, [k for k, _ in items], time.monotonic()
        return m, self._fm_keys

    def identity(self, key: str, limit: int = 12) -> list[dict[str, Any]]:
        """Other rooms (any site, live or not) that are probably the same person.

        Face matches below ``SAME_PERSON_STRONG`` are left out when they are implausible (operator, 12 Oct
        2026): same site; live while this room is offline or the other way round; already part of another
        identity with ``COMPLETE_ROOMS`` rooms; or this room's own identity already has that many."""
        me = self._face_of(key)
        site = key.split(":", 1)[0]
