def also_live(self, key: str) -> list[str]:
    """Likely same-person rooms that are live right now (for badges on cards)."""
    return [o["key"] for o in self.identity(key, 6) if o["likely"] and o["key"] in self.index.rooms]

    def compute_twins(self) -> dict[str, list[tuple[str, float]]]:
        """All live rooms' likely cross-site twins, in one blocked matrix product.

        Run in a thread every few minutes; ~8k live faces is 8k x 8k x 512
        multiply-adds, done 1024 rows at a time so memory stays small.
        """
        keys = [k for k in list(self.index.rooms) if k in self.face]
        out: dict[str, list[tuple[str, float]]] = {}
        cands: list[tuple[str, str, float]] = []
        m = np.stack([self.face[k][0] for k in keys]).astype(np.float32) if len(keys) >= 2 else np.zeros((0, FACE_DIM))
        sites = np.array([k.split(":", 1)[0] for k in keys])
        for start in range(0, len(m), 1024):
            block = m[start:start + 1024] @ m.T
            for i, row in enumerate(block):
                a = start + i
                for j in np.nonzero(row >= SAME_PERSON_MAYBE)[0]:
                    if j > a and sites[j] != sites[a] and _pair(keys[a], keys[j]) not in self.links:
                        cands.append((keys[a], keys[int(j)], float(row[j])))
                hits = np.nonzero(row >= SAME_PERSON_LIKELY)[0]
                found = [(keys[j], float(row[j])) for j in hits if sites[j] != sites[a]
                         and self.links.get(_pair(keys[a], keys[j])) != 0]
                if found:
                    out[keys[a]] = sorted(found, key=lambda x: -x[1])[:4]
        groups: dict[int, list[str]] = {}
        for k, p in list(self.persona.items()):
            if k in self.index.rooms:
                groups.setdefault(p["id"], []).append(k)
        for members in groups.values():
            for a in members:
                for b in members:
                    if a != b and a.split(":", 1)[0] != b.split(":", 1)[0] and self.links.get(_pair(a, b)) != 0                             and all(k != b for k, _ in out.get(a, [])):
                        out.setdefault(a, []).append((b, 0.99))
// ... [truncated]

def review_queue(self, limit: int, skip: set[str]) -> list[tuple[str, str, float]]:
    """Pairs for the operator to judge: both rooms still live, not yet judged, not skipped."""
    out = []
    sizes: dict[int, int] = {}
    for pr in list(self.persona.values()):
        sizes[pr["id"]] = sizes.get(pr["id"], 0) + 1
    for a, b, sim in self.candidates:
        p = _pair(a, b)
        if p in self.links or f"{p[0]}|{p[1]}" in skip:
            continue
        pa, pb = self.persona.get(a), self.persona.get(b)
        if sim < SAME_PERSON_STRONG and any(x is not None and sizes.get(x["id"], 0) >= COMPLETE_ROOMS for x in (pa, pb))                     and not (pa and pb and pa["id"] == pb["id"]):
            continue  # one side already belongs to a complete identity (operator, 12 Oct 2026)
        if a in self.index.rooms and b in self.index.rooms:
            out.append((a, b, sim))
            if len(out) >= limit:
                break
    return out

