def label(self, pid: int) -> str:
    if pid in self.names:
        return self.names[pid]
    for p in self.persona.values():
        if p["id"] == pid:
            return p["label"]
    return f"persona-{pid}"

def performers(self) -> dict[int, dict[str, Any]]:
    """Persona id → its rooms (live or not), label and whether the gallery vouches for it.

    Rooms are grouped by the Atlas's persona; rooms the operator confirmed
    as the same person join too, even before the workstation merges them.
    """
    out: dict[int, dict[str, Any]] = {}
    of: dict[str, int] = {}
    for key, p in self.persona.items():
        g = out.setdefault(p["id"], {"id": p["id"], "label": p["label"], "verified": False, "keys": []})
        g["keys"].append(key)
        g["verified"] = g["verified"] or bool(p["verified"])
        if p["verified"]:
            g["label"] = p["label"]
        of[key] = p["id"]
    for (a, b), v in self.links.items():
        if v != 1:
            continue
        pa, pb = of.get(a), of.get(b)
        if pa is not None and pb is None:
            out[pa]["keys"].append(b)
            of[b] = pa
        elif pb is not None and pa is None:
            out[pb]["keys"].append(a)
            of[a] = pb
    for pid, g in out.items():
        if pid in self.names:
            g["label"] = self.names[pid]
            g["named"] = True
    return out

