def test_cold_decodes_on_read_and_chills_back():
    c = Cold()
    c["a"] = b'{"n": 1}'
    c["b"] = {"n": 2}
    raw = dict(c.items())
    assert raw["a"] == b'{"n": 1}' and Cold.peek(raw["a"]) == {"n": 1}
    assert c.get("a") == {"n": 1} and dict.get(c, "a") == {"n": 1}  # warmed by the read
    c["a"]["n"] += 1
    assert c.chill(warm={"b"}, dirty=set()) == 1  # "a" goes cold with its change, "b" stays warm
    assert dict.get(c, "a") == b'{"n":2}' and c["a"] == {"n": 2}
    assert c.get("missing") is None and c.chill(warm=set(), dirty={"a", "b"}) == 0

