def _telemetry_stats() -> dict | bool:
    """The ADK recorder's counters (queued / drained / posted / spooled …), or False without it."""
    if ModelRun is None:
        return False
    try:
        from vaultwares_adk import telemetry

        return telemetry.stats()
    except Exception:  # noqa: BLE001
        return True

def do_GET(self) -> None:
    if self.path.rstrip("/") in ("/health", ""):
        return self._json(200, EMB.health() if EMB else {"loading": True})
    self._json(404, {"error": "not found"})

def do_POST(self) -> None:
    if self.path.rstrip("/") != "/embed":
        return self._json(404, {"error": "not found"})
    if EMB is None:
        return self._json(503, {"error": "loading"})
    try:
        n = int(self.headers.get("Content-Length") or 0)
        body = json.loads(self.rfile.read(n) if 0 < n <= 64 * 2**20 else b"{}")
        items = body.get("inputs") or []
        dim = int(body.get("dim", 768))
        if not items or len(items) > 64 or dim not in (768, 512, 256, 128):
            return self._json(400, {"error": "1-64 inputs, dim 768/512/256/128"})
        t0 = time.perf_counter()
        vecs = EMB.embed(items, dim, str(body.get("project") or "unknown")[:64], body.get("caller"))
        self._json(200, {"embeddings": vecs, "dim": dim, "ms": round(1000 * (time.perf_counter() - t0))})
    except (ValueError, KeyError, OSError) as e:
        EMB.errors += 1
        self._json(400, {"error": f"{type(e).__name__}: {e}"})
    except Exception as e:  # noqa: BLE001 — out of memory and the like: the caller retries later
        EMB.errors += 1
        log.exception("embed")
        if EMB.cuda:
            EMB.torch.cuda.empty_cache()
        self._json(503, {"error": f"{type(e).__name__}: {e}"})

def load(self) -> None:
    self._read_gallery()
    for pid, kfc, label in self.db.execute("SELECT id, kfc_name, label FROM personas"):
        self.p_label[pid] = label
        if kfc:
            self.p_kfc[kfc] = pid
    sums: dict[int, np.ndarray] = {}
    counts: dict[int, int] = {}
    for pid, emb in self.db.execute("SELECT persona_id, emb FROM sightings WHERE persona_id IS NOT NULL"):
        v = _unit(np.frombuffer(emb, np.float16))
        sums[pid] = sums.get(pid, 0) + v
        counts[pid] = counts.get(pid, 0) + 1
    self.p_sum, self.p_n = sums, counts
    for pid, total in sums.items():
        self._bump(pid, total)
    dropped = self.untie_weak() if self.kfc_names else 0
    dropped += self.untie_missing()
    moved = self.revalidate_verified()
    if moved:
        log.info("atlas: moved %d rooms out of verified personas the gallery doesn't vouch for", moved)
    if dropped:
        log.info("atlas: untied %d weak gallery matches", dropped)
    log.info("atlas: %d personas (%d tied to the gallery), %d sightings",
             len(self.p_label), len(self.p_kfc), sum(counts.values()))

