def _stage(self, name: str, room: str, crop: Image.Image) -> None:
    if not self.gallery or not INBOX:
        return
    day = time.strftime("%Y-%m-%d")
    if day != self.inbox_day:
        self.inbox_day, self.inbox_today = day, {}
    if self.inbox_today.get(name, 0) >= INBOX_PER_IDENTITY_PER_DAY:
        return
    d = self.gallery / "_panopticam_inbox" / name
    d.mkdir(parents=True, exist_ok=True)
    crop.save(d / f"{room.replace(':', '_')}_{int(time.time())}.jpg", quality=92)
    self.inbox_today[name] = self.inbox_today.get(name, 0) + 1

def revalidate_verified(self, names: set[str] | None = None) -> int:
    """Move rooms out of verified personas when the gallery doesn't vouch for them.

    A room stays if at least one of its sightings in that persona clears
    ``VERIFIED_MATCH`` against that identity's own crops; otherwise it gets
    a persona of its own again. Returns how many rooms were moved out.
    ``names`` limits it to those identities.
    """
    if not self.kfc_names:
        return 0
