def prune(folder: Path, pattern: str, keep: int) -> list[Path]:
    """Delete all but the ``keep`` newest (by name: they carry a UTC stamp)."""
    old = sorted(folder.glob(pattern))[:-keep] if keep > 0 else []
    for p in old:
        p.unlink(missing_ok=True)
    return old

def atlas_due(self) -> bool:
    newest = max((p.stat().st_mtime for p in (self.dest / "atlas").glob("atlas-*.db.gz")), default=0)
    return time.time() - newest >= ATLAS_EVERY_S

def run(self) -> None:
    (self.dest / "vps").mkdir(parents=True, exist_ok=True)
    time.sleep(300)  # let the worker settle first
    while True:
        try:
            if got := self.pull():
                log.info("backups: %d VPS snapshot(s) in %s", got, self.dest / "vps")
        except Exception as e:
            log.warning("backups: %s", e)
        if self.atlas_db is not None and self.atlas_db.exists() and self.atlas_due():
            try:
                t0 = time.time()
                out = snapshot_atlas(self.atlas_db, self.dest / "atlas")
                prune(self.dest / "atlas", "atlas-*.db.gz", KEEP_ATLAS)
                log.info("backups: atlas → %s (%.0f MB, %.0f s)", out.name, out.stat().st_size / 1e6, time.time() - t0)
            except Exception as e:
                log.warning("backups: atlas: %s", e)
        time.sleep(EVERY_S)

