def tunnel_ok() -> bool:
    """A real SOCKS5 round trip through the tunnel (a listening port alone proves nothing)."""
    try:
        with socket.create_connection(("127.0.0.1", SOCKS_PORT), timeout=5) as s:
            s.sendall(SOCKS_HELLO)
            if s.recv(2) != SOCKS_OK:
                return False
            host = b"api.ipify.org"
            s.sendall(SOCKS_CONNECT_DOMAIN + bytes([len(host)]) + host + (80).to_bytes(2, "big"))
            return s.recv(10)[:2] == SOCKS_OK
    except OSError:
        return False

def restart_tunnel() -> None:
    if _proc is not None:
        _proc.terminate()
        try:
            _proc.wait(5)
        except subprocess.TimeoutExpired:
            _proc.kill()
    if not tunnel_ok():
        _start_tunnel()

def motion_of(tiles: list[Image.Image]) -> float:
    g = [np.asarray(t.convert("L").resize((64, 36), Image.BILINEAR), dtype=np.float32) / 255.0 for t in tiles]
    if len(g) < 2:
        return 0.0
    return float(np.mean([np.abs(a - b).mean() for a, b in zip(g, g[1:])]))

def one(self, c: dict[str, Any]) -> dict[str, Any]:
    tiles = split_sprite(base64.b64decode(c["sprite"]), int(c.get("frames") or 4))
    # A long clip's frames span a minute: all of them (it says so), whatever the budget.
    use = tiles if c.get("all_frames") or not self.frames_embedded or self.frames_embedded >= len(tiles) else (
        [tiles[0], tiles[-1]] if self.frames_embedded == 2 else tiles[:self.frames_embedded])
    v = self.embed(use).mean(axis=0)
    v /= np.linalg.norm(v) or 1.0
    out: dict[str, Any] = {"key": c["key"], "ts": c["ts"], "motion": round(motion_of(tiles), 5),
                           "v": base64.b64encode(v.astype(np.float16).tobytes()).decode(), "loud": -90.0}
    if c.get("audio") and self.sound is not None:
        from sound import decode, rms_db
        try:
            wave = decode(base64.b64decode(c["audio"]))
            out["loud"] = round(rms_db(wave), 2)
            if out["loud"] > SILENT_DB:
                a = self.sound.embed_audio(wave)
                out["a"] = base64.b64encode(a.astype(np.float16).tobytes()).decode()
        except Exception as e:
            log.debug("clip sound %s: %s", c["key"], e)
    return out

def run(self) -> None:
    idle = 0
    while True:
        try:
            clips = self.api("GET", "/api/vision/clips?limit=4")
        except Exception as e:
            log.warning("clips: %s", e)
            time.sleep(30)
            continue
        if not clips:
            idle += 1
            time.sleep(min(20, 2 * idle))
            continue
        idle = 0
        results = []
        for c in clips:
            try:
                results.append(self.one(c))
            except Exception as e:
                log.warning("clip %s: %s", c.get("key"), e)
        if results:
            try:
                self.api("POST", "/api/vision/clip-results", results)
            except Exception as e:
                log.warning("clip results: %s", e)
        self.done += len(results)
        if self.done and self.done % 200 < len(results):
            log.info("clips: %d analysed (%.2f/s)", self.done, self.done / (time.time() - self.t0))

def batch_hash(digests: list[bytes]) -> str:
    """base62 of the first 8 bytes of SHA-256 over the files' SHA-256 digests (gallery_naming.ts)."""
    if not digests:
        return "00000000"
    val = int.from_bytes(hashlib.sha256(b"".join(digests)).digest()[:8], "big")
    out = ""
    for _ in range(8):
        out = B62[val % 62] + out
        val //= 62
    return out

