def push(self) -> int:
    """Finished archives → the VPS (rclone move: nothing stays here)."""
    if not REMOTE_DATASETS:
        return 0
    zips = list(self.out.glob("*.zip"))
    if not zips:
        return 0
    r = subprocess.run([RCLONE, "move", str(self.out), self._remote(REMOTE_DATASETS), "--include", "*.zip",
                        "--include", "*.json", "--transfers", "4", "--retries", "2", "--log-level", "NOTICE"],
                       capture_output=True, text=True, timeout=1800)
    if r.returncode != 0:
        log.warning("rclone push (exit %s): %s", r.returncode, (r.stderr or r.stdout).strip()[-400:])
        return 0
    return len(zips)

def _reference(self, key: str) -> np.ndarray | None:
    rows = self.atlas.db.execute("SELECT emb FROM sightings WHERE room = ?", (key,)).fetchall()
    if not rows:
        return None
    m = np.stack([np.frombuffer(e, np.float16).astype(np.float32) for (e,) in rows])
    m /= np.linalg.norm(m, axis=1, keepdims=True)
    c = m.mean(axis=0)
    return c / np.linalg.norm(c)

def _feed_reference(self, folder: Path, meta: dict) -> np.ndarray | None:
    """The dominant face across a feed's photos: at least ``FEED_MIN`` faces and
    ``FEED_SHARE`` of the photos that show a face, or no identity at all."""
    faces: list[np.ndarray] = []
    with_face = 0
    for item in meta.get("items") or []:
        f = folder / item["file"]
        if f.suffix.lower() in VIDEO_EXT:
            continue
        embs = self._faces_of(f)
        if embs:
            with_face += 1
            faces.extend(embs)
    if len(faces) < FEED_MIN:
        return None
    m = np.stack(faces)
    agree = (m @ m.T) >= 0.45
    best = int(np.argmax(agree.sum(axis=1)))
    members = m[agree[best]]
    if len(members) < FEED_MIN or len(members) < FEED_SHARE * with_face:
        return None
    c = members.mean(axis=0)
    return c / np.linalg.norm(c)

