def sweep_pending(self) -> int:
    """Empty leftovers in ``_pending``: nothing but an empty ``.sources.json``."""
    n = 0
    for d in self.pending.iterdir():
        try:
            files = [f for f in d.iterdir()] if d.is_dir() else None
            if files is not None and all(f.name == SOURCES for f in files) and not self._sources(d):
                shutil.rmtree(d)
                n += 1
        except OSError:
            continue
    return n

def cycle(self) -> dict[str, int]:
    if not getattr(self, "_swept", False):
        self._swept = True
        if gone := self.sweep_pending():
            log.info("dataset: %d empty _pending folders removed", gone)
    pulled = self.pull()
    stats = self.process()
    stats["pulled"] = pulled
    stats["pushed"] = self.push()
    return stats

