def auc(score, y):
    score, y = np.asarray(score, float), np.asarray(y, int)
    pos, neg = score[y == 1], score[y == 0]
    if not len(pos) or not len(neg):
        return float("nan")
    return float(((pos[:, None] > neg[None, :]).sum() + 0.5 * (pos[:, None] == neg[None, :]).sum()) / (len(pos) * len(neg)))

def load(kind):
    if kind == "bf16":
        return AutoModel.from_pretrained(MODEL, dtype=torch.bfloat16).to("cuda").eval()
    q = (BitsAndBytesConfig(load_in_8bit=True) if kind == "int8" else
         BitsAndBytesConfig(load_in_4bit=True, bnb_4bit_quant_type="nf4", bnb_4bit_compute_dtype=torch.bfloat16))
    return AutoModel.from_pretrained(MODEL, dtype=torch.bfloat16, quantization_config=q, device_map="cuda").eval()

def embed(model, **kw):
    inp = proc(**kw, return_tensors="pt").to("cuda")
    h = model(**inp).last_hidden_state
    if h.dim() == 3:
        m = inp["attention_mask"].unsqueeze(-1).to(h.dtype)
        h = (h * m).sum(1) / m.sum(1)
    v = h.float()[0]
    return (v / v.norm()).cpu().numpy()

def frames(mp4: Path, t: float) -> list[Image.Image]:
