def cached(image_input, auto_rotate: bool = True):
    if not isinstance(image_input, str) or not os.path.isfile(image_input):
        return original(image_input, auto_rotate=auto_rotate)
    with open(image_input, "rb") as f:
        key = (hashlib.sha1(f.read()).digest(), bool(auto_rotate))
    if key in cache:
        cache.move_to_end(key)
        stats["hits"] += 1
        return list(cache[key])
    stats["misses"] += 1
    found = original(image_input, auto_rotate=auto_rotate)
    cache[key] = list(found)
    while len(cache) > size:
        cache.popitem(last=False)
    return found

def cards() -> list[dict[str, str]]:
    """[{index, name, uuid, free_mb}] from nvidia-smi ([] without one)."""
    try:
        out = subprocess.run(["nvidia-smi", "--query-gpu=index,name,uuid,memory.free", "--format=csv,noheader,nounits"],
                             capture_output=True, text=True, timeout=15, creationflags=NO_WINDOW).stdout
    except (OSError, subprocess.SubprocessError):
        return []
    rows = []
    for line in out.splitlines():
        parts = [p.strip() for p in line.split(",")]
        if len(parts) == 4:
            rows.append(dict(zip(("index", "name", "uuid", "free_mb"), parts, strict=True)))
    return rows

def pick(want: str, found: list[dict[str, str]] | None = None) -> dict[str, str] | None:
    """The card ``want`` names (index, UUID or part of the name), or None."""
    want = (want or "").strip()
    if not want:
        return None
    for c in cards() if found is None else found:
        if want == c["index"] or want.lower() == c["uuid"].lower() or want.lower() in c["name"].lower():
            return c
    return None

def apply(env: dict, want: str) -> dict:
    """``env`` with CUDA_VISIBLE_DEVICES pinned to the chosen card (unchanged when there's none)."""
    card = pick(want)
    if card is None:
        if want:
            log.info("gpu: no card matches %r, helpers see every GPU", want)
        return env
    log.info("gpu: helpers use %s (#%s, %s MB free)", card["name"], card["index"], card["free_mb"])
    return {**env, "CUDA_VISIBLE_DEVICES": card["uuid"]}

