            if line and not line.startswith("#") and "=" in line:
                k, v = line.split("=", 1)
                out[k.strip()] = v.strip().strip("\"'")
    return out

def __init__(self, folder: Path, cache: Path = ROOMS_CACHE) -> None:
    self.folder = folder
    self.cache = cache
    self.first: dict[str, float] = {}
    #: room key -> the name its first archive was written under (14 Oct 2026: rooms came back as "name2")
    self.name: dict[str, str] = {}
    self.ready = False
    self.lock = threading.Lock()

def note(self, side: dict, name: str | None = None) -> None:
    made = float(side.get("made") or 0)
    if not made:
        return
    name = name or side.get("name")
    with self.lock:
        for m in side.get("members") or []:
            k = m.get("key")
            if k and (k not in self.first or made < self.first[k]):
                self.first[k] = made
                if name:
                    self.name[k] = name

def name_of(self, key: str) -> str | None:
    with self.lock:
        return self.name.get(key)

def build(self) -> None:
    since = 0.0
    try:
        got = json.loads(self.cache.read_text(encoding="utf-8"))
        self.first, self.name = {k: float(v) for k, v in got["first"].items()}, dict(got["name"])
        since = float(got["scanned"])  # a cache without names (before 14 Oct) fails above: full scan
    except (OSError, ValueError, KeyError):
        pass
    t0, n = time.time(), 0
    try:
        for e in os.scandir(self.folder):
            # Creation time: rclone / cross-disk moves keep a file's old mtime (Windows ctime = created here).
            if e.name.endswith(".json") and max(e.stat().st_mtime, e.stat().st_ctime) >= since - 3600:
                try:
                    self.note(json.loads(Path(e.path).read_text(encoding="utf-8")), e.name.split("_" * 10)[0])
                    n += 1
                except (OSError, ValueError):
                    pass
    except OSError as ex:
        log.warning("ingest: archive rooms scan: %s", ex)
        return
    self.ready = True
    try:
        with self.lock:
            body = json.dumps({"scanned": t0, "first": self.first, "name": self.name})
        self.cache.write_text(body, encoding="utf-8")
    except OSError:
        pass
    log.info("ingest: %d rooms already archived (%d sidecars read in %.0f s)", len(self.first), n, time.time() - t0)

def revisit(self, keys: list[str], made: float | None) -> str | None:
    """Why this archive is a revisit, or None."""
    if not self.ready or not keys or not made:
        return None
    with self.lock:
        firsts = [self.first.get(k) for k in keys]
    if any(f is None or f > made - REVISIT_GAP_S for f in firsts):
        return None
    return "revisit: room archived since " + time.strftime("%a, %d %b %Y", time.localtime(min(firsts)))

def _close(self) -> None:
    if self.fh is not None:
        if os.name == "nt":
            import msvcrt
            try:
                self.fh.seek(0)
                msvcrt.locking(self.fh.fileno(), msvcrt.LK_UNLCK, 1)
            except OSError:
                pass
        self.fh.close()
        self.fh = None

def _alive(pid: int) -> bool:
    try:
        import psutil
        return psutil.pid_exists(pid)
    except ImportError:
        return True

def __init__(self, root: Path) -> None:
    self.dir = root / ".claims"
    self.dir.mkdir(parents=True, exist_ok=True)

def take(self, keys: list[str]) -> bool:
    got: list[Path] = []
    for key in keys:
        p = self._path(key)
        if not self._one(p, key):
            for q in got:
                q.unlink(missing_ok=True)
            return False
        got.append(p)
    return True

def _one(self, p: Path, key: str) -> bool:
    for _ in range(2):
        try:
            fd = os.open(p, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        except FileExistsError:
            try:
                pid, at = p.read_text(encoding="utf-8").split()[:2]
                stale = not _alive(int(pid)) or time.time() - float(at) > self.STALE_S
            except (OSError, ValueError):
                stale = False  # being written right now
            if not stale:
                return False
            p.unlink(missing_ok=True)
            continue
        os.write(fd, f"{os.getpid()} {time.time():.0f} {key}".encode("utf-8"))
        os.close(fd)
        return True
    return False

def drop(self, keys: list[str]) -> None:
    for key in keys:
        self._path(key).unlink(missing_ok=True)

def _env() -> dict:
    """The hosts pick their device from PANOPTICAM_HOST_DEVICE (default cuda, operator 5 Oct
    2026); the worker's own CUDA_VISIBLE_DEVICES must not hide the GPU from them."""
    env = {**os.environ}
    # The libraries under the tagger (OpenCV, BLAS, OpenMP) size their own pools from the core
    # count unless told; the job object's cap (worker.cpu_cap) is the ceiling, this the sizing.
    n = env.get("PANOPTICAM_HOST_THREADS", "4")
    for var in ("OMP_NUM_THREADS", "MKL_NUM_THREADS", "OPENBLAS_NUM_THREADS", "NUMEXPR_NUM_THREADS",
                "OPENCV_FOR_THREADS_NUM"):
        env.setdefault(var, n)
    if env.get("PANOPTICAM_HOST_DEVICE", "cuda") != "cpu":
        env.pop("CUDA_VISIBLE_DEVICES", None)
        import gpu  # PANOPTICAM_GPU: the card Panopticam may use (9 Oct 2026, the RTX 2060)
        env = gpu.apply(env, env.get("PANOPTICAM_GPU", ""))
    return env

def _read(self, timeout: float) -> dict | None:
    box: list[str] = []
    t = threading.Thread(target=lambda: box.append(self.proc.stdout.readline()), daemon=True)
    t.start()
    t.join(timeout)
    if not box or not box[0]:
        return None
    try:
        return json.loads(box[0])
    except ValueError:
        return None

def stop(self) -> None:
    if self.proc and self.proc.poll() is None:
        self.proc.kill()
    self.proc = None

def call(self, req: dict, timeout: float = 1800) -> dict | None:
    with self.lock:
        try:
            return self._call(req, timeout)
        finally:
            self.used = time.time()

def sweep_stale(self, max_age_s: float = 3600) -> int:
    """Work folders a killed run left behind: empty (no file anywhere inside) and older than
    ``max_age_s``. 36 had piled up by 6 Oct 2026, one per worker restart mid-archive."""
    n = 0
    for d in self.root.iterdir():
        try:
            if (d.is_dir() and not d.name.startswith(".") and time.time() - d.stat().st_mtime > max_age_s
                    and not any(f.is_file() for f in d.rglob("*"))):
                shutil.rmtree(d)
                n += 1
        except OSError as e:
            log.debug("ingest: sweep %s: %s", d.name, e)
    return n

def comparison(img: Path) -> dict:
    """compare-face-gallery's verdict, from the image's sidecar (``<file>.json``)."""
    for side in (img.with_name(img.name + ".json"), img.with_suffix(".json")):
        try:
            return json.loads(side.read_text(encoding="utf-8")).get("gallery_comparison") or {}
        except (OSError, ValueError):
            continue
    return {}

def people(img: Path) -> int | None:
    """tag-images' person count (YOLO pose), from the same sidecar."""
    for side in (img.with_name(img.name + ".json"), img.with_suffix(".json")):
        try:
            n = (json.loads(side.read_text(encoding="utf-8")).get("image") or {}).get("people_count")
            return int(n) if n is not None else None
        except (OSError, ValueError, TypeError):
            continue
    return None

def identity_size(self, name: str) -> int:
    d = self.gallery / name
    return sum(1 for p in d.iterdir() if p.is_file() and p.suffix.lower() in IMAGE_EXT) if d.is_dir() else 0

def aliases(self) -> dict[str, str]:
    """Names the operator merged away -> the identity they live on in (``.aliases.json``,
    re-read when it changes)."""
    f = self.root / ".aliases.json"
    try:
        mtime = f.stat().st_mtime
    except OSError:
        return {}
    if getattr(self, "_aliases_at", None) != mtime:
        try:
            self._aliases = json.loads(f.read_text(encoding="utf-8"))
        except ValueError:
            self._aliases = {}
        self._aliases_at = mtime
    return self._aliases

def ours(self) -> set[str]:
    """Identities this pipeline created from dataset archives (``.ours.txt``)."""
    if getattr(self, "_ours", None) is None:
        f = self.root / ".ours.txt"
        self._ours = set(f.read_text(encoding="utf-8").split()) if f.exists() else set()
    return self._ours

def same_photos(self, imgs: list[Path], name: str) -> bool:
    """Half or more of these photos are already in the identity, byte for byte: our own
    earlier attempt at this archive (a worker restart between creating the identity and
    reporting it made ``01ashleyy-2``, 1 Oct 2026), not a namesake."""
    d = self.gallery / name
    if not imgs or not d.is_dir():
        return False
    have = {hashlib.sha256(p.read_bytes()).digest() for p in d.iterdir()
            if p.is_file() and p.suffix.lower() in IMAGE_EXT}
    same = sum(hashlib.sha256(p.read_bytes()).digest() in have for p in imgs)
    return same * 2 >= len(imgs)

def drop_present(self, pick: Path, name: str) -> int:
    """Take out of ``pick`` the photos already in the identity, byte for byte:
    new-face-model copies its six samples in, and add-model-images on the same
    folder copied them a second time as ``*_added1`` (29 Sep 2026)."""
    d = self.gallery / name
    if not d.is_dir():
        return 0
    have = {hashlib.sha256(p.read_bytes()).digest() for p in d.iterdir()
            if p.is_file() and p.suffix.lower() in IMAGE_EXT}
    n = 0
    for p in list(pick.iterdir()):
        if p.suffix.lower() in IMAGE_EXT and hashlib.sha256(p.read_bytes()).digest() in have:
            p.unlink()
            p.with_name(p.name + ".json").unlink(missing_ok=True)
            n += 1
    return n

def add(self, pick: Path, name: str) -> None:
    self.drop_present(pick, name)
    if any(p.suffix.lower() in IMAGE_EXT for p in pick.iterdir()):
        answer = self.host.call({"op": "add", "path": str(pick), "identity": name, "gallery": str(self.gallery)})
        if answer is None:
            self.vw("add-model-images", "-Path", str(pick), "-Identity", name, "-Gallery", str(self.gallery),
                    "-Execute", "-Device", "cpu")
        elif not answer["ok"]:
            raise RuntimeError(f"add-model-images: {answer['out'].strip()[-800:]}")

def tag(self, folder: Path) -> None:
    taggers = getattr(self, "taggers", None)
    answer = None
    if taggers:
        # an idle one if any, else wait for a lane-spread one
        tagger = next((t for t in taggers if not t.lock.locked()), taggers[hash(folder.name) % len(taggers)])
        answer = tagger.call({"op": "tag", "input": str(folder)})
    if answer is None:
        self.vw("tag-images", "-Input", str(folder), "-SkipDedupe")
    elif not answer["ok"]:
        raise RuntimeError(f"tag-images: {answer['out'].strip()[-800:]}")

def pick(folder: Path, imgs: list[Path], n: int, prefer: str | None) -> Path:
    """``n`` photos (with sidecars) into ``folder/pick``: the add commands read one flat folder."""
    pick = folder / "pick"
    pick.mkdir(exist_ok=True)

    def rank(p: Path) -> tuple[int, float]:
        c = Ingest.comparison(p)
        return (0 if prefer and c.get("identity") == prefer else 1, -float(c.get("closest_score") or 0))

    # A new identity keeps the archive's order (its sources in turn); an existing one
    # takes its own best matches first.
    for p in (sorted(imgs, key=rank) if prefer else imgs)[:max(0, n)]:
        for f in (p, p.with_name(p.name + ".json")):
            if f.exists():
                shutil.move(str(f), pick / f.name)
    return pick

# ---- one archive ---------------------------------------------------------------------

def rank(p: Path) -> tuple[int, float]:
    c = Ingest.comparison(p)
    return (0 if prefer and c.get("identity") == prefer else 1, -float(c.get("closest_score") or 0))

