# takes its own best matches first.

def one(self, item: dict, remote_dir: str) -> dict:
    file, name = item["file"], item["name"]
    if why := self.rooms.revisit(item.get("keys") or [], item.get("made")):
        return {"outcome": "revisit", "identity": None, "added": 0, "detail": why}
    if not item.get("target") and name in self.aliases():
        # The operator merged this name into another identity (2 Oct 2026): the Atlas still
        # names that person's archives the old way, so follow the merge.
        item = {**item, "target": self.aliases()[name]}
    early = item.get("target") or name
    if (self.gallery / early).is_dir() and (item.get("target") or item.get("gallery") or early in self.ours()):
        have = self.identity_size(early)
        if have >= CAP:  # nothing to add: skip the copy and the tagger (~80 s on a big archive)
            return {"outcome": "full", "identity": early, "added": 0, "total": have,
                    "detail": f"already {have} photos"}
    folder = self.fetch(file, remote_dir)
    videos = [p for p in folder.iterdir() if p.suffix.lower() in VIDEO_EXT]
    for v in videos:
        self.vw("ingest-video-faces", "-Path", str(v), "-Gallery", str(self.gallery), "-Device", "cpu")
        v.unlink()
    self.tag(folder)
    imgs = self.images(folder)
    with self.write_lock:
        return self._write(item, name, folder, imgs)

def later(self, name: str) -> str:
    """Bulk (1 Oct 2026): the crop rebuild (~25 s each) waits until the backlog is done;
    until then the identity matches on new-face-model's first crops."""
    with (self.root / ".reindex-later").open("a", encoding="utf-8") as f:
        f.write(name + "\n")
    return "crops rebuilt once the backlog is done"

def reindex_later(self) -> int:
    marker = self.root / ".reindex-later"
    if not marker.exists():
        return 0
    names = list(dict.fromkeys(marker.read_text(encoding="utf-8").split()))
    marker.unlink()
    for name in names:
        if (self.gallery / name).is_dir():
            log.info("ingest: %s %s", name, self.reindex(name))
    return len(names)

def free_name(self, name: str) -> str:
    n = 2
    while (self.gallery / f"{name}-{n}").exists():
        n += 1
    return f"{name}-{n}"

def _claim(self, item: dict) -> str | None:
    names = {item["name"], item.get("target") or item["name"]}
    with self.claim_lock:
        if item["file"] in self.taken or names & self.busy:
            return None
        claims = getattr(self, "claims", None)
        if claims and not claims.take([item["file"], *sorted("name=" + n for n in names)]):
            return None  # another ingest process has it
        self.taken.add(item["file"])
        self.busy |= names
    return item["file"]

def _unreported(self) -> dict[str, dict]:
    if getattr(self, "_unrep", None) is None:
        try:
            self._unrep = json.loads((self.root / ".unreported.json").read_text(encoding="utf-8"))
        except (OSError, ValueError):
            self._unrep = {}
    return self._unrep

def _save_unreported(self) -> None:
    try:
        (self.root / ".unreported.json").write_text(json.dumps(self._unreported()), encoding="utf-8")
    except OSError as e:
        log.warning("ingest: can't keep the unreported list: %s", e)

def report(self, file: str, res: dict) -> bool:
    try:
        self.api("POST", "/api/vision/datasets", {"file": file, **res})
        return True
    except Exception as e:
        log.warning("ingest %s: report failed (%s); sent again next cycle", file, e)
        with self.claim_lock:
            self._unreported()[file] = res
            self._save_unreported()
        return False

def resend(self) -> int:
    n = 0
    with self.claim_lock:
        todo = dict(self._unreported())
    for file, res in todo.items():
        try:
            self.api("POST", "/api/vision/datasets", {"file": file, **res})
        except Exception:
            break  # still down: next cycle
        with self.claim_lock:
            self._unreported().pop(file, None)
            self._save_unreported()
        n += 1
    if n:
        log.info("ingest: %d report(s) sent again", n)
    return n

