def file_local(self, file: str) -> None:
    """An offloaded zip, once ingested, goes where the VPS's ingested ones go (nothing deleted)."""
    local = self.queue / file
    mapped = self.local_sources.path_of(file) if getattr(self, "local_sources", None) else None
    if mapped is not None and mapped.is_file():
        local = mapped
        if mapped.parent == self.queue:
            # Zipped from an import folder that stays where it is: archiving the copy would
            # put the same photos on F: twice (24 GB of them on 6 Oct 2026).
            mapped.unlink()
    if local.is_file():
        dest = self.gallery / ".dataset-archive"
        dest.mkdir(parents=True, exist_ok=True)
        shutil.move(str(local), dest / file)  # another disk: a copy, then the delete
    if mapped is not None:
        self.local_sources.done(file)

