def raw_head(w: np.ndarray, b: float, mu: np.ndarray, sd: np.ndarray, live: np.ndarray) -> tuple[np.ndarray, float]:
    """A head fitted on ``(X - mu) / sd`` over the ``live`` dims → weights on raw X (zeros elsewhere)."""
    out = np.zeros(X_DIM, np.float64)
    out[live] = w / sd
    return out, float(b - (w / sd) @ mu)

def _embed(self, imgs: list[Image.Image]) -> np.ndarray:
    x = np.stack([((np.asarray(im.resize((224, 224), Image.BICUBIC), np.float32) / 255 - 0.5) / 0.5).transpose(2, 0, 1)
                  for im in imgs])
    outs = [o.name for o in self._siglip.get_outputs()]
    o = self._siglip.run(None, {self._siglip.get_inputs()[0].name: x})[outs.index("pooler_output")].astype(np.float32)
    v = (o / np.linalg.norm(o, axis=1, keepdims=True)).mean(0)
    return v / (np.linalg.norm(v) or 1.0)

