def _duration(self, mp4: Path) -> float:
    r = self._run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", str(mp4)], text=True)
    try:
        return float(r.stdout.strip())
    except ValueError:
        return 0.0

def _frames(self, mp4: Path, t: float) -> list[Image.Image]:
    out = []
    for dt in FRAME_AT:
        r = self._run(["ffmpeg", "-hide_banner", "-loglevel", "error", "-ss", f"{t + dt:.2f}", "-i", str(mp4),
                       "-frames:v", "1", "-vf", "scale=-2:224", "-f", "image2pipe", "-c:v", "png", "pipe:1"])
        if r.returncode == 0 and r.stdout:
            out.append(Image.open(io.BytesIO(r.stdout)).convert("RGB"))
    return out

def _audio(self, mp4: Path, t: float) -> np.ndarray:
    from sound import SR

    r = self._run(["ffmpeg", "-hide_banner", "-loglevel", "error", "-ss", f"{max(0.0, t - 6.8):.2f}", "-t", "10",
                   "-i", str(mp4), "-vn", "-ac", "1", "-ar", str(SR), "-f", "f32le", "pipe:1"])
    return np.frombuffer(r.stdout, np.float32) if r.returncode == 0 else np.zeros(0, np.float32)

def rated(self) -> list[tuple[str, int, str]]:
    """(file under the moments folder, label, room) of every rated minute whose mp4 is there."""
    out = []
    folder = self.emb.folder
    for js in folder.glob("*/*.json"):
        try:
            meta = json.loads(js.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        y = TASTE_LABEL.get(meta.get("rating"))
        if y is None or js.name.startswith("_"):
            continue
        mp4 = next(iter(js.parent.rglob(js.stem + ".mp4")), None)
        if mp4 is not None:
            out.append((str(mp4.relative_to(folder)), y, meta.get("key") or js.stem))
    return out

def run_once(self) -> dict | None:
    rated = self.rated()
    with self.emb.lock:
        have = {r[0] for r in self.emb.db.execute("SELECT DISTINCT file FROM windows")}
    todo = [r for r in rated if r[0] not in have][:PER_RUN]
    if todo:
        t0 = time.time()
        self._load()
        try:
            for file, _, _ in todo:
                try:
                    ws = self.windows_of(self.emb.folder / file)
                except Exception as e:
                    log.warning("live taste: %s: %s", file, e)
                    continue
                with self.emb.lock:
                    self.emb.db.executemany(
                        "INSERT OR REPLACE INTO windows VALUES (?, ?, ?, ?, ?, ?)",
                        [(file, i, v.astype(np.float16).tobytes(), a.astype(np.float16).tobytes() if a is not None else None,
                          float(m), float(loud)) for i, v, a, m, loud in ws]
                        or [(file, -1, np.zeros(V_DIM, np.float16).tobytes(), None, 0.0, -90.0)])  # too short: once
                    self.emb.db.commit()
        finally:
            self._drop()
        log.info("live taste: %d rated minutes cut into windows in %.0f s", len(todo), time.time() - t0)
    return self.refit(rated)

    def refit(self, rated: list[tuple[str, int, str]]) -> dict | None:
        lab = {f: (y, k) for f, y, k in rated}
        with self.emb.lock:
            rows = self.emb.db.execute("SELECT file, v, a, motion, loud FROM windows WHERE w >= 0").fetchall()
        rows = [r for r in rows if r[0] in lab]
        y = np.array([lab[r[0]][0] for r in rows], float)
        if int(y.sum()) < MIN_SIDE or int((1 - y).sum()) < MIN_SIDE:
            log.info("live taste: waits for %d windows a side (%d / %d)", MIN_SIDE, int(y.sum()), int((1 - y).sum()))
            return None
        if len(rows) == self.sent_n:
            return None  # nothing new since the head in force
        X = np.stack([featurize(np.frombuffer(v, np.float16).astype(np.float32),
                                np.frombuffer(a, np.float16).astype(np.float32) if a is not None else None, m, loud)
                      for _, v, a, m, loud in rows])
        live = X.std(0) > 1e-6
        mu, sd = X[:, live].mean(0), X[:, live].std(0)
        Z = (X[:, live] - mu) / sd
        rooms = [lab[r[0]][1] for r in rows]
        score = held_out_auc(Z, y, rooms)
        w, b = fit(Z, y)
        W, B = raw_head(w, b, mu, sd, live)
        out = {"w": W.round(6).tolist(), "b": round(B, 6), "auc": round(score, 3), "n": len(rows),
               "minutes": len({r[0] for r in rows}), "liked": int(y.sum())}
        log.info("live taste: head on %d windows of %d minutes (%d liked), rooms-held-out AUC %.3f",
                 out["n"], out["minutes"], out["liked"], score)
        if self.emb.api is not None:
            try:
                got = self.emb.api("POST", "/api/vision/taste", out)
                self.sent_n = len(rows)
                log.info("live taste: sent; the server scored %s rooms, %s in its top band", got.get("scored"), got.get("above"))
            except Exception as e:
                log.info("live taste: sending the head failed (%s), next run", e)
