def clean_name(raw: str) -> str:
    """A gallery-style name: lower case letters and digits ("goth_dolll" → "gothdolll";
    "ashleyscott_batch_2_final" → "ashleyscott")."""
    raw = re.sub(r"_batch.*$", "", raw.lower())
    return re.sub(r"[^a-z0-9]", "", raw)

def loose_name(filename: str) -> str:
    """The set a loose photo belongs to, from its file name ("" = none):
    ``_bexleydean_batch_1_3.jpg`` → ``bexleydean``, ``rosieholt_photos_07.jpg`` → ``rosieholt_photos``."""
    stem = Path(filename).stem.lower()
    return re.sub(r"(_batch.*|_\d+.*|\s*\(\d+\).*)$", "", stem).strip("_ ")

def set_name(raw: str) -> str:
    """A set's gallery name ("" = skip it): ``samantha-woos_gallery`` → ``samanthawoos``."""
    if not raw or SKIP.search(raw):
        return ""
    return clean_name(re.sub(r"_(gallery|photos|pics|videos?)$", "", raw.lower()))

def path_of(self, file: str) -> Path | None:
    p = self.state["paths"].get(file)
    return Path(p) if p else None

def done(self, file: str) -> None:
    """Ingested: forget the path (the zip has moved to ``.dataset-archive``)."""
    with self.lock:
        if self.state["paths"].pop(file, None) is not None:
            self._save()

