def _dataset_items(self) -> list[dict[str, Any]]:
    out = []
    for z in sorted((self.gallery / ".dataset").glob("*.zip")):
        m = NAME_RE.match(z.name)
        if m:
            file = z.name
        else:
            stem = z.stem.split(SEPARATOR)[0]
            name = clean_name(stem)
            if not name:
                continue
            digest = batch_hash([hashlib.sha256(f"{z.name}:{z.stat().st_size}".encode()).digest()])
            file = f"{name}{SEPARATOR}{digest}.zip"
        if file in self.state["registered"]:
            continue
        out.append({"file": file, "path": z, "source": "dataset"})
    return out

def _zip_folder(self, folder: Path, name: str | None = None) -> list[dict[str, Any]]:
    files = sorted(p for p in folder.iterdir() if p.is_file())
    return self._zip_set(clean_name(folder.name) if name is None else name, files)

def _extra_sets(self, root: Path) -> list[tuple[str, str, list[Path]]]:
    """(state key, name, files) of an extra root: its identity folders, then its loose photo groups."""
    out = []
    loose: dict[str, list[Path]] = {}
    for p in sorted(root.iterdir()):
        if p.name.startswith("."):
            continue
        if p.is_dir():
            if name := set_name(p.name):
                out.append((str(p), name, sorted(f for f in p.iterdir() if f.is_file())))
        elif p.suffix.lower() in IMAGE_EXT and (name := set_name(loose_name(p.name))):
            loose.setdefault(name, []).append(p)
    # A misspelt tail of a longer set ("hopewalkerrbatc66h") joins that set.
    names = sorted({n for _, n, _ in out} | set(loose), key=len)
    for name in sorted(loose, key=len, reverse=True):
        base = next((n for n in names if len(n) >= 6 and n != name and name.startswith(n)), None)
        if base is not None and base in loose:
            loose[base] += loose.pop(name)
        elif base is not None:
            loose[base] = loose.pop(name)
    out += [(f"{root}|loose|{name}", name, files) for name, files in sorted(loose.items())]
    return out

def _members(z: Path) -> list[str]:
    with zipfile.ZipFile(z) as zf:
        return sorted(n for n in zf.namelist() if Path(n).suffix.lower() in IMAGE_EXT)

