def system_commit() -> tuple[int, int] | None:
    """(committed, limit) in bytes, or None off Windows."""
    if os.name != "nt":
        return None
    pi = _PerfInfo()
    pi.cb = ctypes.sizeof(pi)
    if not ctypes.windll.psapi.GetPerformanceInfo(ctypes.byref(pi), pi.cb):
        return None
    return pi.CommitTotal * pi.PageSize, pi.CommitLimit * pi.PageSize

def private_of(p: Any) -> int:
    m = p.memory_info()
    return int(getattr(m, "private", 0) or getattr(m, "vms", 0))

def label(p: Any) -> str:
    try:
        cmd = " ".join(p.cmdline()[-2:])
    except Exception:
        cmd = p.name()
    for name in ("worker.py", "gallery_host.py", "tag_host.py", "server.py", "ffmpeg", "rclone", "ssh"):
        if name in cmd:
            return f"{name.removesuffix('.py')}:{p.pid}"
    return f"{p.name()}:{p.pid}"

def processes(self) -> list[Any]:
    import psutil
    me = psutil.Process()
    out = [me]
    try:
        out += me.children(recursive=True)
    except psutil.Error:
        pass
    for p in psutil.process_iter(["name", "cmdline"]):
        cmd = " ".join(p.info.get("cmdline") or [])
        if "embed" in cmd and cmd.rstrip().endswith("server.py") and p.pid not in {q.pid for q in out}:
            out.append(p)
    return out

def _tell(self, text: str, always: bool = False) -> None:
    log.warning("memguard: %s", text)
    if always or time.time() - self.told > TELL_EVERY_S:
        self.told = time.time()
        try:
            self.notify(f"Panopticam (PC): {text}")
        except Exception as e:
            log.info("memguard: notify: %s", e)

def embed_alive() -> bool:
    """The embedding server answers /health (``loading`` counts: it's on its way)."""
    import urllib.request
    try:
        with urllib.request.urlopen(EMBED_HEALTH, timeout=10) as r:
            return r.status == 200
    except Exception:
        return False

def check_embed(self, now: float, alive: bool) -> None:
    if alive:
        if self.embed_told_down:
            self._tell("the embedding server answers again", always=True)
        self.embed_down_since, self.embed_told_down = None, False
        return
    if self.embed_down_since is None:
        self.embed_down_since = now
        return
    down = now - self.embed_down_since
    if down >= EMBED_DOWN_S and now - self.embed_restarted > 900 and EMBED_RESTART.exists():
        self._tell(f"the embedding server hasn't answered for {down / 60:.0f} min: restarting it",
                   always=not self.embed_told_down)
        self.embed_told_down = True
        self._restart_embed(now)

