def run(self) -> None:
    while True:
        try:
            self.check()
        except Exception:
            log.exception("memguard")
        time.sleep(EVERY_S)

def pair_score(a: np.ndarray, b: np.ndarray) -> float:
    """Two identities' crops: each crop's best match on the other side, averaged both ways."""
    x = a @ b.T
    return float((x.max(axis=1).mean() + x.max(axis=0).mean()) / 2)

def _unique(p: Path) -> Path:
    """``p``, or ``x__mergedN.jpg.json`` for ``x.jpg.json``: the suffix goes before the first
    dot, so a photo and its ``<photo>.json`` stay a pair when both had to be renamed."""
    if not p.exists():
        return p
    head, dot, tail = p.name.partition(".")
    i = 1
    while True:
        q = p.with_name(f"{head}__merged{i}{dot}{tail}")
        if not q.exists():
            return q
        i += 1

def preview(self, keep: str, gone: str) -> dict[str, Any]:
    self._check(keep, gone)
    with self._db() as db:
        rows = {r["name"]: dict(r) for r in db.execute(
            "SELECT name, status, sample_count FROM identities WHERE name IN (?, ?)", (keep, gone))}
    return {"keep": keep, "gone": gone, "photos": {keep: self.photos(keep), gone: self.photos(gone)},
            "identities": rows, "archives": len(self._archives(gone))}

def _check(self, keep: str, gone: str, rename: bool = False) -> None:
    if not (NAME_OK.match(keep) and NAME_OK.match(gone)):
        raise MergeError("bad identity name")
    if keep == gone:
        raise MergeError("same identity")
    with self._db() as db:
        have = {r[0] for r in db.execute("SELECT name FROM identities WHERE name IN (?, ?)", (keep, gone))}
    if rename:  # a merge into a name nobody has yet
        if (self.gallery / keep).exists() or keep in have:
            raise MergeError(f"{keep} exists already: merge instead")
        if not (self.gallery / gone).is_dir() or gone not in have:
            raise MergeError(f"no identity {gone}")
        return
    for n in (keep, gone):
        if not (self.gallery / n).is_dir():
            raise MergeError(f"no folder for {n}")
    missing = {keep, gone} - have
    if missing:
        raise MergeError(f"not in gallery.db: {', '.join(sorted(missing))}")

def _archives(self, name: str) -> list[Path]:
    d = self.gallery / ".dataset-archive"
    return sorted(d.glob(f"{name}{SEP}*")) if d.is_dir() else []

def _merge_files(self, keep: str, gone: str, j: dict) -> None:
    kd, gd = self.gallery / keep, self.gallery / gone
    plan = self._plan_folder(keep, gone)
    j["plan"] = plan
    for old, new in plan.items():
        self._move(gd / old, self._unique(kd / new), j["moves"])
    for sub in sorted(p for p in gd.iterdir() if p.is_dir()):
        dst = kd / sub.name
        if dst.exists():
            dst = self._unique(kd / f".merged-{gone}" / sub.name)
        self._move(sub, dst, j["moves"])
    left = list(gd.iterdir())
    if left:
        raise MergeError(f"{gone}: {len(left)} entries could not be moved")
    gd.rmdir()
    j["removed_dir"] = str(gd)

def _merge_archives(self, keep: str, gone: str, j: dict) -> None:
    for p in self._archives(gone):
        dst = self._unique(p.with_name(keep + p.name[len(gone):]))
        if p.suffix == ".json":
            try:
                d = json.loads(p.read_text(encoding="utf-8"))
                if d.get("name") == gone:
                    d["name"] = keep
                    p.write_text(json.dumps(d), encoding="utf-8")
                    j["sidecars"].append(str(dst))
            except (ValueError, OSError) as e:
                log.warning("merge: sidecar %s: %s", p.name, e)
        self._move(p, dst, j["moves"])

def _alias(self, keep: str, gone: str, j: dict) -> None:
    f = self.ingest_root / ".aliases.json"
    try:
        al = json.loads(f.read_text(encoding="utf-8")) if f.exists() else {}
    except ValueError:
        al = {}
    j["alias"] = {"before": dict(al)}
    # Names merged into ``gone`` earlier follow it into ``keep``.
    al = {k: (keep if v == gone else v) for k, v in al.items()}
    al[gone] = keep
    al.pop(keep, None)
    f.parent.mkdir(parents=True, exist_ok=True)
    f.write_text(json.dumps(al, indent=1, sort_keys=True), encoding="utf-8")

def _reindex_later(self, keep: str) -> None:
    with (self.ingest_root / ".reindex-later").open("a", encoding="utf-8") as f:
        f.write(keep + "\n")

def _merge_rooms(self, keep: str, gone: str, j: dict) -> None:
    if not self.rooms_dir or not (self.rooms_dir / gone).is_dir():
        return
    src, dst = self.rooms_dir / gone, self.rooms_dir / keep
    try:
        for sub in sorted(src.iterdir()):
            target = dst / sub.name
            if sub.is_dir() and target.is_dir():
                for f in sorted(sub.iterdir()):
                    self._move(f, self._unique(target / f.name), j["moves"])
                sub.rmdir()
            else:
                self._move(sub, self._unique(target), j["moves"])
        src.rmdir()
        j["rooms_removed"] = str(src)
    except OSError as e:
        log.warning("merge: room frames %s: %s", gone, e)

def _unmove(moves: list[list[str]]) -> None:
    for src, dst in reversed(moves):
        try:
            Path(src).parent.mkdir(parents=True, exist_ok=True)
            shutil.move(dst, src)
        except OSError as e:
            log.warning("undo move %s: %s", dst, e)

def history(self, limit: int = 50, since: float = 0) -> list[dict[str, Any]]:
    if not self.journals.is_dir():
        return []
    out = []
    for f in sorted(self.journals.glob("*.json"), reverse=True)[:limit]:
        try:
            j = json.loads(f.read_text(encoding="utf-8"))
        except ValueError:
            continue
        if j["at"] < since:
            break  # newest first
        h = {"id": j["id"], "keep": j["keep"], "gone": j["gone"], "at": j["at"], "undone": j.get("undone", False)}
        if since:  # what the server needs to catch up on a merge it missed (merges.apply)
            h.update(self._landed(j), persona=j.get("atlas"))
        out.append(h)
    return out

def _landed(self, j: dict) -> dict[str, int]:
    """Where ``gone``'s photos sit among the keeper's as the photo endpoint counts them (sorted, no
    ``*_added`` copies): from ``start``, ``count`` of them. For the batch review list."""
    num = re.compile(rf"^{re.escape(j['keep'])}_(\d+)")
    photo = lambda n: Path(n).suffix.lower() in {".jpg", ".jpeg", ".png", ".webp"} and "_added" not in Path(n).stem
    new = [int(m.group(1)) for v in (j.get("plan") or {}).values() if photo(v) and (m := num.match(v))]
    kd = self.gallery / j["keep"]
    if not new or not kd.is_dir():
        return {}
    first = min(new)
    start = sum(1 for p in kd.iterdir() if photo(p.name) and (m := num.match(p.name)) and int(m.group(1)) < first)
    return {"start": start, "count": len(new)}

    def undo(self, jid: str) -> dict[str, Any]:
        if not re.fullmatch(r"[\w.-]+", jid):
            raise MergeError("bad id")
        f = self.journals / f"{jid}.json"
        if not f.exists():
            raise MergeError("no such merge")
        j = json.loads(f.read_text(encoding="utf-8"))
        if j.get("undone"):
            raise MergeError("already undone")
        keep, gone = j["keep"], j["gone"]
        if (self.gallery / gone).exists():
