def _drain(self) -> None:
    while True:
        with self._q_lock:
            if not self._queue:
                self._draining = False
                return
        n, t0 = 0, time.time()
        with self.merger.lock:
            while True:
                with self._q_lock:
                    if not self._queue:
                        break
                    keep, gone, rename, done, box = self._queue.pop(0)
                try:
                    box["res"] = self._merge_now(keep, gone, rename)
                except Exception as e:
                    box["error"] = e
                done.set()
                n += 1
        log.info("merge: %d merge(s) in one hold of the gallery lock (%.0f s)", n, time.time() - t0)

