def one(self, mp4: Path) -> dict | None:
    """Re-encode one minute in place. Returns {"from", "to"} bytes, or None when left as is."""
    before = mp4.stat().st_size
    if codec(mp4) == "av1":
        return {"from": before, "to": before}
    part = mp4.with_name(mp4.stem + ".av1.part")
    cmd = ["ffmpeg", "-hide_banner", "-loglevel", "error", "-y", "-i", str(mp4), "-map", "0:v:0", "-map", "0:a:0?",
           *ENCODE, "-f", "mp4", str(part)]
    try:
        r = subprocess.run(cmd, capture_output=True, timeout=3600, creationflags=NO_WINDOW)
        if r.returncode != 0 or not part.exists():
            log.warning("archive %s: %s", mp4.name, r.stderr.decode(errors="replace")[-300:])
            return None
        after = part.stat().st_size
        if after >= before or abs(duration(part) - duration(mp4)) > DURATION_SLACK_S:
            log.warning("archive %s: kept the original (%d -> %d bytes)", mp4.name, before, after)
            return {"from": before, "to": before, "kept": True}
        os.replace(part, mp4)
        return {"from": before, "to": after}
    except (OSError, subprocess.TimeoutExpired) as e:
        log.warning("archive %s: %s", mp4.name, e)
        return None
    finally:
        part.unlink(missing_ok=True)

def day(self, day: Path) -> int:
    done = self._done(day)
    saved = 0
    for mp4 in sorted(day.rglob("*.mp4")):
        if mp4.name.startswith("_") or mp4.name in done:
            continue
        got = self.one(mp4)
        if got is None:
            continue
        done[mp4.name] = got
        saved += got["from"] - got["to"]
        (day / "_archive.json").write_text(json.dumps(done, indent=1), encoding="utf-8")
    return saved

def run(self) -> None:
    time.sleep(600)
    while True:
        for d in self.due():
            try:
                t0 = time.time()
                saved = self.day(d)
                if saved:
                    self.saved += saved
                    log.info("moments: %s archived to AV1, %.0f MB saved (%.0f s)", d.name, saved / 1e6,
                             time.time() - t0)
            except Exception as e:
                log.warning("moments: archive %s: %s", d.name, e)
        time.sleep(EVERY_S)

def auc(score: np.ndarray, y: np.ndarray) -> float:
    pos, neg = score[y == 1], score[y == 0]
    if not len(pos) or not len(neg):
        return float("nan")
    return float(((pos[:, None] > neg[None, :]).sum() + 0.5 * (pos[:, None] == neg[None, :]).sum()) / (len(pos) * len(neg)))

def held_out_auc(X: np.ndarray, y: np.ndarray, rooms: list[str], folds: int = 5) -> float:
    """Out-of-fold AUC with every room's moments in one fold (a probe must not just know rooms)."""
    order = sorted(set(rooms))
    fold_of = {r: i % folds for i, r in enumerate(np.random.default_rng(0).permutation(order))}
    f = np.array([fold_of[r] for r in rooms])
    out = np.zeros(len(y))
    for k in range(folds):
        tr, te = f != k, f == k
        if not te.any() or len(set(y[tr])) < 2:
            continue
        w, b = fit(X[tr], y[tr])
        out[te] = X[te] @ w + b
    return auc(out, y)

