def reel_value(m: dict[str, Any]) -> float:
    """Rated ones first (gold > more > okay), then the event score weighed by how lively it was."""
    life = m.get("life")
    return 10.0 * max(0, m.get("rating") or 0) + float(m.get("score") or 0) * (0.5 + (0.5 if life is None else life))

