def kind_of(m: dict[str, Any]) -> str:
    """What mostly made a moment: "toy", "tip", "heat" or "action" (its biggest score part)."""
    p = {k: float(v or 0) for k, v in (m.get("parts") or {}).items()}
    return max(p, key=p.get) if p and max(p.values()) > 0 else ""

def plan_reels(moments: list[dict[str, Any]], top: int = REEL_TOP) -> list[tuple[str, str, list[dict[str, Any]]]]:
    """(suffix, title, moments in time order) per reel: the day's best mixed, then the best toy
    runs and tips not shown yet, then the rest by value. Rated down = left out everywhere."""
    ranked = sorted((m for m in moments if (m.get("rating") or 0) >= 0), key=lambda m: -reel_value(m))
    used: set[Any] = set()
    out = []
    for suffix, title, kind in REEL_KINDS:
        pick = [m for m in ranked if m["id"] not in used and (kind is None or kind_of(m) == kind)][:top]
        if len(pick) < (1 if suffix == "" else REEL_MIN):
            continue
        used |= {m["id"] for m in pick}
        out.append((suffix, title, sorted(pick, key=lambda m: m["ts"])))
    return out

