        bits.append(f"{int(m['viewers']):,} watching")
    if m.get("tokens"):
        bits.append(f"{int(m['tokens']):,} tk this minute")  # the moment's own minute (why says the 5 min before)
    lv = re.search(r"level (\d+)", " ".join(m.get("why") or []))
    if lv:
