def _fade_alpha(t_in: float, t_out: float, d: float = 0.4) -> str:
    return (f"alpha='if(lt(t,{t_in}),0,if(lt(t,{t_in + d}),(t-{t_in})/{d},"
            f"if(lt(t,{t_out}),1,if(lt(t,{t_out + d}),({t_out + d}-t)/{d},0))))'")

    def pull(self) -> int:
        got = 0
        for m in self.api("GET", "/api/moments?days=4&limit=1000")["moments"]:
            day, stem = stem_of(m)
            folder = self.dest / day
            js = folder / f"{stem}.json"
            if js.exists():
                if m.get("rating") is not None:  # rated on the page: the folder copy learns it
                    have = json.loads(js.read_text(encoding="utf-8"))
                    if have.get("rating") != m["rating"] and have.get("rated_by") != "folder":
                        js.write_text(json.dumps({**have, "rating": m["rating"], "rated_by": "page"}, indent=1),
                                      encoding="utf-8")
                continue
            if not m.get("has_video"):
                continue
            folder.mkdir(parents=True, exist_ok=True)
            try:
                self._get(f"/api/moments/{m['id']}/video.mp4", folder / f"{stem}.mp4")
                try:
                    self._get(f"/api/moments/{m['id']}/sprite.jpg", folder / f"{stem}.jpg")
                except Exception:
                    pass  # the frames are a nicety
            except Exception as e:
                log.debug("moment %s: %s", m["id"], e)
                continue
            keep = {k: m.get(k) for k in ("id", "key", "name", "ts", "score", "viewers", "why", "parts", "tokens", "toy")}
            if m.get("rating") is not None:
                keep.update(rating=m["rating"], rated_by="page")
            (folder / f"{stem}.json").write_text(json.dumps(keep, indent=1), encoding="utf-8")  # written last: "done"
            got += 1
        return got

