def make_reels(self, day: Path) -> list[Path]:
    """Every reel of a day (``plan_reels``), then ``_reels.json`` saying they're done."""
    plan = plan_reels([m for m in self.moments_of(day) if m["_mp4"] is not None])
    made = []
    for suffix, title, chosen in plan:
        out = self.make_reel(day, chosen, suffix, title)
        if out is not None:
            made.append(out)
    if made:
        (day / "_reels.json").write_text(json.dumps({"v": REEL_VERSION, "reels": [p.name for p in made]}, indent=1),
                                         encoding="utf-8")
