def run(self) -> None:
    self.dest.mkdir(parents=True, exist_ok=True)
    time.sleep(120)
    while True:
        try:
            if got := self.pull():
                log.info("moments: %d new in %s", got, self.dest)
        except Exception as e:
            log.warning("moments: %s", e)
        try:
            sent, scored = self.sync()
            if sent or scored:
                log.info("moments: %d ratings sent, %d minutes scored", sent, scored)
        except Exception as e:
            log.warning("moments: ratings: %s", e)
        for day in self.reel_due():
            try:
                t0 = time.time()
                for out in self.make_reels(day):
                    log.info("moments: reel %s (%.0f MB)", out, out.stat().st_size / 1e6)
                log.info("moments: reels of %s in %.0f s", day.name, time.time() - t0)
            except Exception as e:
                log.warning("moments: reel %s: %s", day.name, e)
                (day / "_reel.failed").write_text(str(e), encoding="utf-8")
        time.sleep(EVERY_S)

def rating_of(parts: tuple[str, ...]) -> int | None:
    """The rating a folder path means: the innermost folder with a known word wins."""
    for name in reversed(parts):
        low = name.lower()
        for word, rating in FOLDERS:
            if word in low:
                return rating
    return None

def frames_moving(mp4: Path) -> float:
    r = subprocess.run(["ffmpeg", "-v", "error", "-i", str(mp4), "-vf", "fps=2,scale=160:90,format=gray",
                        "-f", "rawvideo", "pipe:1"], capture_output=True, timeout=120, creationflags=NO_WINDOW)
    g = np.frombuffer(r.stdout, np.uint8)
    if len(g) < 2 * 160 * 90:
        return 0.0
    g = g[: len(g) // (160 * 90) * 160 * 90].reshape(-1, 90, 160).astype(np.int16)
    changed = (np.abs(np.diff(g, axis=0)) > 20).mean(axis=(1, 2))
    return float((changed > 0.02).mean())

def audio_of(mp4: Path, sr: int) -> np.ndarray:
    r = subprocess.run(["ffmpeg", "-v", "error", "-i", str(mp4), "-vn", "-ac", "1", "-ar", str(sr), "-f", "f32le",
                        "pipe:1"], capture_output=True, timeout=120, creationflags=NO_WINDOW)
    return np.frombuffer(r.stdout, np.float32)

