        except (OSError, ValueError):
            self._prompts = {k: self._sound.embed_text(t) for k, t in PROMPTS.items()}
            cache.write_text(json.dumps({k: v.tolist() for k, v in self._prompts.items()}))
        self._sound._text = None  # the text tower is only needed once
    return self._sound

def features(self, mp4: Path, tip: float) -> dict[str, float]:
    from sound import SR
    snd = self._clap()
    wave = audio_of(mp4, SR)
    if len(wave) >= SR:
        embs = np.stack([snd.embed_audio(wave[i:i + 10 * SR]) for i in range(0, max(1, len(wave) - 5 * SR), 10 * SR)])
        silence = float((embs @ self._prompts["silence"]).mean())
        moan = float((embs @ self._prompts["moan"]).max())
    else:  # no sound track at all: as quiet as the quietest seen
        mu, sd = self.model["mu"][0], self.model["sd"][0]
        silence, moan = mu + 2 * sd, 0.0
    return {"silence": round(silence, 5), "moving": round(frames_moving(mp4), 4), "tip": round(float(tip), 3),
            "moan": round(moan, 5)}

def life(self, f: dict[str, float]) -> float:
    m = self.model
    z = sum(w * (f[c] - mu) / (sd or 1.0) for c, w, mu, sd in zip(COLS, m["w"], m["mu"], m["sd"], strict=True))
    return round(1 / (1 + math.exp(-(z + m["b"]))), 3)

def rebuild_aliases(gallery: Path) -> None:
    import json
    have = {d.name for d in gallery.iterdir() if d.is_dir() and not d.name.startswith(".")}
    root = gallery / ".dataset-imports" / "panopticam"
    ours = (root / ".ours.txt").read_text(encoding="utf-8").split() if (root / ".ours.txt").exists() else []
    old = root / ".aliases.json"
    alias: dict[str, str] = json.loads(old.read_text(encoding="utf-8")) if old.exists() else {}
    by: dict[str, list[str]] = defaultdict(list)
