        by[norm(h)].append(h)
    unclear = []
    for n in sorted({n for n in ours if n not in have}):
        base = re.sub(r"-\d+$", "", n)
        if base != n and base in have:
            alias[n] = base
            continue
        cand = [c for c in by.get(norm(n), []) if c != n]
        if len(cand) == 1:
            alias[n] = cand[0]
        else:
            unclear.append(n)
    # A target merged away later follows on to where it went.
    for k in list(alias):
        seen = {k}
        while alias[k] in alias and alias[k] not in seen:
            seen.add(alias[k])
            alias[k] = alias[alias[k]]
    old.write_text(json.dumps(alias, indent=1, sort_keys=True), encoding="utf-8")
    print(f"{len(alias)} aliases -> {old}" + (f"; no clear target for: {', '.join(unclear)}" if unclear else ""))
