def _letterbox(im: Image.Image) -> np.ndarray:
    scale = SIZE / max(im.width, im.height)
    w, h = max(1, round(im.width * scale)), max(1, round(im.height * scale))
    canvas = Image.new("RGB", (SIZE, SIZE), (114, 114, 114))
    canvas.paste(im.resize((w, h), Image.BILINEAR), ((SIZE - w) // 2, (SIZE - h) // 2))
    return (np.asarray(canvas, dtype=np.float32) / 255.0).transpose(2, 0, 1)

def parts(self, im: Image.Image) -> dict[str, float]:
    """Best confidence per class present above ``CONF``."""
    return self._parts(self._run(im))

def _parts(out: np.ndarray) -> dict[str, float]:
    scores = out[4:].max(axis=1)  # best anchor per class
    return {CLASSES[i]: round(float(s), 3) for i, s in enumerate(scores) if s >= CONF}

def _face_box(out: np.ndarray, im: Image.Image) -> tuple[float, float, float, float] | None:
    """The surest FACE_FEMALE box in the frame's own pixels (x1, y1, x2, y2), or None."""
    row = 4 + CLASSES.index("FACE_FEMALE")
    i = int(out[row].argmax())
    if out[row, i] < FACE_SURE:
        return None
    scale = SIZE / max(im.width, im.height)
    px, py = (SIZE - round(im.width * scale)) // 2, (SIZE - round(im.height * scale)) // 2
    cx, cy, w, h = (float(v) for v in out[:4, i])
    return ((cx - w / 2 - px) / scale, (cy - h / 2 - py) / scale, (cx + w / 2 - px) / scale, (cy + h / 2 - py) / scale)

def state(self, im: Image.Image, has_face: bool, want_face: bool = False) -> dict[str, object]:
    """The frame's state; with ``want_face``, also ``face``: the surest female face box (or None)."""
    out = self._run(im)
    p = self._parts(out)
    found = set(p)
    if found & NUDE:
        state = "nude"
    elif found & TOPLESS:
        state = "topless"
    elif found & PARTIAL:
        state = "partial"
    elif found or has_face:
        state = "covered"
    else:
        state = "empty"
    got: dict[str, object] = {"state": state, "parts": sorted(k for k in found if k.endswith("_EXPOSED"))}
    if want_face:
        got["face"] = self._face_box(out, im)
    return got

def head_crop(im: Image.Image, box: tuple[float, float, float, float]) -> Image.Image | None:
    """Head and hair around a face box: 2.4 face widths across, from 0.9 face heights above the
    face to 0.9 below it (long hair falls past the chin). None when the face is too small to say."""
    x1, y1, x2, y2 = box
    w, h = x2 - x1, y2 - y1
    if w < MIN_HEAD_PX:
        return None
    cx = (x1 + x2) / 2
    return im.crop((int(max(0, cx - 1.2 * w)), int(max(0, y1 - 0.9 * h)), int(min(im.width, cx + 1.2 * w)),
                    int(min(im.height, y2 + 0.9 * h))))

