def db() -> sqlite3.Connection:
    DB.parent.mkdir(parents=True, exist_ok=True)
    c = sqlite3.connect(DB)
    c.executescript(SCHEMA)
    cols = {r[1] for r in c.execute("PRAGMA table_info(refusals)")}
    for col, decl in (("subs_last_day", "INTEGER"), ("text", "TEXT")):
        if col not in cols:
            c.execute(f"ALTER TABLE refusals ADD COLUMN {col} {decl}")
    return c

def _meta(c: sqlite3.Connection, k: str, default: int = 0) -> int:
    r = c.execute("SELECT v FROM meta WHERE k = ?", (k,)).fetchone()
    return int(r[0]) if r else default

def _set_meta(c: sqlite3.Connection, k: str, v: int) -> None:
    c.execute("INSERT OR REPLACE INTO meta VALUES (?, ?)", (k, str(v)))
    c.commit()

def _subs_blocked_for(c: sqlite3.Connection) -> int:
    """Seconds left in the current pause (0 = may subscribe)."""
    return max(0, _meta(c, "subs_blocked_until") - int(time.time()))

def _may_subscribe(c: sqlite3.Connection) -> bool:
    return (_subs_last_hour(c) < MAX_SUBS_PER_HOUR and _subs_last_day(c) < MAX_SUBS_PER_DAY
            and not _subs_blocked_for(c))

def _media_urls(post: dict) -> list[tuple[str, str]]:
