        files = sorted((p for p in self.cache.glob("*.mp4") if not p.name.endswith(".part.mp4")),
                       key=lambda p: p.stat().st_mtime, reverse=True)
        total = 0
        for p in files:
            total += p.stat().st_size
            if total > CACHE_MAX_BYTES:
                p.unlink(missing_ok=True)


