#: the Datasets page previews them through ``/dataset/<file>/photo/<i>`` (6 Oct 2026).

def dataset_photo(file: str, i: int, width: int | None) -> bytes | None:
    """The ``i``-th photo (sorted, as the VPS numbers them) of an archive kept on this PC, as JPEG."""
    import io
    import zipfile

    from PIL import Image
    if not DATASET_RE.match(file):
        return None
    mapped = PHOTO_LOOKUP[0](file) if PHOTO_LOOKUP[0] else None
    for z in ([mapped] if mapped else []) + [d / file for d in PHOTO_DIRS]:
        if z.is_file() and z.stat().st_size > 0:
            with zipfile.ZipFile(z) as zf:
                names = sorted(n for n in zf.namelist() if Path(n).suffix.lower() in PHOTO_EXT)
                if not 0 <= i < len(names):
                    return None
                data = zf.read(names[i])
            im = Image.open(io.BytesIO(data)).convert("RGB")
            if width:
                im.thumbnail((width, width * 2))
            buf = io.BytesIO()
            im.save(buf, "JPEG", quality=82)
            return buf.getvalue()
    return None

