def do_POST(self) -> None:
    if not token or not hmac.compare_digest(self.headers.get("X-Token", ""), token):
        return self._plain(403, "forbidden")
    path = urllib.parse.urlsplit(self.path).path
    if path in ("/merge", "/merge/undo", "/merge/batch"):
        return self._merge(path)
    if path != "/whois":
        return self._plain(404, "not found")
    if WHOIS[0] is None:
        return self._plain(503, "no face models here")
    size = int(self.headers.get("Content-Length") or 0)
    if not 0 < size <= WHOIS_MAX_BYTES:
        return self._plain(413, "send one photo, at most 16 MB")
    data = self.rfile.read(size)
    try:
        got = WHOIS[0](data)
    except Exception as e:
        log.warning("whois: %s", e)
        return self._plain(400, f"can't read that photo ({type(e).__name__})")
    self._json(got)

def _merge(self, path: str) -> None:
    desk = MERGE[0]
    if desk is None:
        return self._plain(503, "merges need the gallery and ingest on this worker")
    size = int(self.headers.get("Content-Length") or 0)
    try:
        body = json.loads(self.rfile.read(size) or b"{}") if 0 <= size <= 1048576 else {}
    except ValueError:
        return self._plain(400, "bad json")
    from merge import MergeError
    try:
        if path == "/merge/undo":
            got = desk.undo(str(body.get("id", "")))
        elif path == "/merge/batch":
            got = {"results": desk.merge_many(list(body.get("pairs") or [])[:500])}
        else:
            got = desk.merge(str(body.get("keep", "")), str(body.get("gone", "")), bool(body.get("rename")))
    except MergeError as e:
        return self._plain(409, str(e))
    except Exception as e:
        log.exception("merge %s", body)
        return self._plain(500, f"{type(e).__name__}: {e}")
    self._json(got)

def do_DELETE(self) -> None:
    if not token or not hmac.compare_digest(self.headers.get("X-Token", ""), token):
        return self._plain(403, "forbidden")
    path = urllib.parse.urlsplit(self.path).path
    src = lib.source(urllib.parse.unquote(path[5:])) if path.startswith("/rec/") else None
    if src is None:
        return self._plain(404, "no such recording")
