        gone = lib.delete(src)
    except OSError as e:
        return self._plain(500, str(e))
    log.info("recordings: recycled %s", ", ".join(gone))
    data = json.dumps({"recycled": gone}).encode()
    self.send_response(200)
    self.send_header("Content-Type", "application/json")
    self.send_header("Content-Length", str(len(data)))
    self.end_headers()
    self.wfile.write(data)

