def __init__(self) -> None:
    self.proc: subprocess.Popen | None = None
    self.port = REMOTE_PORTS[0]

def _kill_stale() -> None:
    """A tunnel left by a worker that was killed (its ssh child outlives it) holds
    the remote port, and ours would fail with 'remote port forwarding failed'."""
    try:
        import psutil
    except ImportError:
        return
    marks = {f"127.0.0.1:{port}:127.0.0.1:{PORT}" for port in REMOTE_PORTS}
    for p in psutil.process_iter(["name", "cmdline"]):
        with contextlib.suppress(psutil.Error):
            if (p.info["name"] or "").lower().startswith("ssh") and marks & set(p.info["cmdline"] or []):
                log.info("recordings: stopping a stale tunnel (pid %d)", p.pid)
                p.kill()

def watch(self) -> None:
    backoff = 5.0
    while True:
        if self.proc is None or self.proc.poll() is not None:
            if self.proc is not None:
                err = (self.proc.stderr.read() or b"").decode(errors="replace").strip() if self.proc.stderr else ""
                log.warning("recordings: tunnel exited (%s) %s", self.proc.returncode, err[-200:])
                if "remote port forwarding failed" in err:  # held on the server: the next port
                    self.port = REMOTE_PORTS[(REMOTE_PORTS.index(self.port) + 1) % len(REMOTE_PORTS)]
                time.sleep(backoff)
                backoff = min(60.0, backoff * 2)  # a stale forward on the server clears in ~3 min
            self._start()
        else:
            backoff = 5.0
        time.sleep(10)

