def queue(root: Path, everything: bool) -> list[Path]:
    conf: dict[str, float] = {}
    f = root / "_proposals" / "proposals.csv"
    if f.exists():
        for row in csv.reader(f.open(encoding="utf-8")):
            if len(row) >= 4:
                conf[row[0]] = max(conf.get(row[0], 0.0), float(row[3]))
    frames = sorted(root.glob("*.jpg"))
    proposed = [p for p in frames if (root / "_proposals" / f"{p.stem}.txt").exists()]
    proposed.sort(key=lambda p: -conf.get(p.name, 0.0))
    rest = [p for p in frames if p not in set(proposed)] if everything else []
    return proposed + rest

def to_px(self, b: list[float]) -> tuple[int, int, int, int]:
    h, w = self.img.shape[:2]
    s = self.scale
    cx, cy, bw, bh = b[1] * w * s, b[2] * h * s, b[3] * w * s, b[4] * h * s
    return int(cx - bw / 2), int(cy - bh / 2), int(cx + bw / 2), int(cy + bh / 2)

def on_mouse(self, ev: int, x: int, y: int, *_: object) -> None:
    self.mouse = (x, y)
    if ev == cv2.EVENT_LBUTTONDOWN:
        self.drag = (x, y)
    elif ev == cv2.EVENT_LBUTTONUP and self.drag:
        (x0, y0), self.drag = self.drag, None
        if abs(x - x0) > 4 and abs(y - y0) > 4:
            h, w = self.img.shape[:2]
            s = self.scale
            cx, cy = (x + x0) / 2 / s / w, (y + y0) / 2 / s / h
            self.boxes.append([self.cls, cx, cy, abs(x - x0) / s / w, abs(y - y0) / s / h])
    elif ev == cv2.EVENT_RBUTTONDOWN:
        for b in reversed(self.boxes):
            x1, y1, x2, y2 = self.to_px(b)
            if x1 <= x <= x2 and y1 <= y <= y2:
                self.boxes.remove(b)
                break

    def run(self) -> None:
        win = "toy proposals"
        cv2.namedWindow(win, cv2.WINDOW_AUTOSIZE)
        cv2.setMouseCallback(win, self.on_mouse)
        while self.frames:
            self.i = min(self.i, len(self.frames) - 1)
            self.load()
            while True:
                cv2.imshow(win, self.draw())
                k = cv2.waitKey(30) & 0xFF
                if k == 255:
                    if cv2.getWindowProperty(win, cv2.WND_PROP_VISIBLE) < 1:
                        return
                    continue
                c = chr(k).lower() if k < 128 else ""
                if c in ("q",) or k == 27:
                    return
                if c == "1":
                    self.cls = 0
                elif c == "2":
                    self.cls = 1
                elif c == "z" and self.boxes:
                    self.boxes.pop()
                elif c == "c":  # right place, wrong toy: flip the class of the box under the cursor
                    x, y = self.mouse
                    for b in reversed(self.boxes):
                        x1, y1, x2, y2 = self.to_px(b)
                        if x1 <= x <= x2 and y1 <= y <= y2:
                            b[0] = 1 - int(b[0])
                            break
                elif c == "y" or k == 13:
                    self.decide(self.boxes)
