def embed_audio(self, wave: np.ndarray) -> np.ndarray:
    """Unit 512-d embedding of a clip's sound."""
    (out,) = self.audio.run(None, {"input_features": features(wave)[None]})
    v = out[0].astype(np.float32)
    return v / (np.linalg.norm(v) or 1.0)

def rms_db(wave: np.ndarray) -> float:
    """Loudness of the clip in dBFS (silence ≈ -90)."""
    return float(20 * np.log10(max(1e-9, float(np.sqrt(np.mean(np.square(wave)))) if len(wave) else 1e-9)))

def _hz_to_mel(f: np.ndarray) -> np.ndarray:
    f = np.asarray(f, dtype=np.float64)
    log_step = 27.0 / np.log(6.4)
    return np.where(f >= 1000.0, 15.0 + np.log(np.maximum(f, 1e-10) / 1000.0) * log_step, 3.0 * f / 200.0)

def _mel_to_hz(m: np.ndarray) -> np.ndarray:
    m = np.asarray(m, dtype=np.float64)
    return np.where(m >= 15.0, 1000.0 * np.exp(np.log(6.4) / 27.0 * (m - 15.0)), 200.0 * m / 3.0)

