def _byte_decoder() -> dict[str, int]:
    """GPT-2's printable stand-ins for raw bytes, reversed (Whisper's BPE uses them)."""
    bs = list(range(ord("!"), ord("~") + 1)) + list(range(ord("¡"), ord("¬") + 1)) + list(range(ord("®"), ord("ÿ") + 1))
    cs = bs[:]
    n = 0
    for b in range(256):
        if b not in bs:
            bs.append(b)
            cs.append(256 + n)
            n += 1
    return {chr(c): b for b, c in zip(bs, cs)}

def detokenize(pieces: list[str]) -> str:
    """BPE pieces (vocab.json's strings) → text."""
    return bytes(_BYTES[ch] for p in pieces for ch in p if ch in _BYTES).decode("utf-8", errors="replace").strip()

def looping(ids: list[int], max_period: int = 6, times: int = 3) -> bool:
    """True when the tail is one short token run repeated ``times`` (Whisper's decoding loops)."""
    for n in range(1, max_period + 1):
        if len(ids) >= n * times and all(ids[-n * k - n:len(ids) - n * k] == ids[-n:] for k in range(1, times)):
            return True
    return False

def run(self) -> None:
    import base64
    import logging
    import time

    log = logging.getLogger("panopticam.speech")
    while True:
        t0 = time.time()
        try:
            work = self.api("GET", "/api/speech/work?limit=1")
        except Exception as e:
            log.warning("speech: %s", e)
            time.sleep(60)
            continue
        results = []
        for w in work or []:
            try:
                results.append({"key": w["key"], **self.speech.detect(decode(base64.b64decode(w["audio"])))})
            except Exception as e:
                log.debug("speech %s: %s", w.get("key"), e)
        if results:
            try:
                self.api("POST", "/api/speech/results", results)
            except Exception as e:
                log.warning("speech results: %s", e)
            self.done += len(results)
            if self.done % 200 < len(results):
                log.info("speech: %d clips heard", self.done)
        time.sleep(max(1.0, self.every - (time.time() - t0)) if work else 20.0)

def start(self) -> None:
    import threading

    threading.Thread(target=self.run, name="speech", daemon=True).start()

