def keyframes(path: str, max_side: int = 960) -> list[Image.Image]:
    """Every keyframe, downscaled, decoded in one ffmpeg run (MJPEG over a pipe)."""
    cmd = [FFMPEG, "-v", "error", "-skip_frame", "nokey", "-i", path,
           "-vf", f"scale='min({max_side},iw)':-2", "-fps_mode", "vfr",
           "-f", "image2pipe", "-c:v", "mjpeg", "-q:v", "3", "pipe:1"]
    data = subprocess.run(cmd, capture_output=True, timeout=600).stdout
    frames, start = [], 0
    while True:
        a = data.find(b"\xff\xd8", start)
        if a < 0:
            break
        b = data.find(b"\xff\xd9", a)
        if b < 0:
            break
        try:
            frames.append(Image.open(io.BytesIO(data[a:b + 2])).convert("RGB"))
        except Exception:
            pass
        start = b + 2
    return frames

def halving_order(n: int) -> list[int]:
    """0..n-1, middle first, then the quarter points, then the eighths…"""
    out, seen, spans = [], set(), [(0, n)]
    while spans:
        nxt = []
        for lo, hi in spans:
            if lo >= hi:
                continue
            mid = (lo + hi) // 2
            if mid not in seen:
                seen.add(mid)
                out.append(mid)
            nxt += [(lo, mid), (mid + 1, hi)]
        spans = nxt
    return out

