def read(img: Image.Image, scale: float, dx: float, dy: float) -> list:
    out = []
    for f in faces.get(np.asarray(img)[:, :, ::-1].copy()):
        x1, y1, x2, y2 = (float(c) for c in f.bbox)
        if f.det_score < min_score or min(x2 - x1, y2 - y1) < min_px:
            continue
        box = (x1 / scale + dx, y1 / scale + dy, x2 / scale + dx, y2 / scale + dy)
        out.append((f.normed_embedding.astype(np.float32), float(f.det_score), box))
    return out

def load_env() -> dict[str, str]:
    env = dict(os.environ)
    f = HOME / "vision.env"
    if f.exists():
        for line in f.read_text(encoding="utf-8").splitlines():
            if "=" in line and not line.lstrip().startswith("#"):
                k, v = line.split("=", 1)
                env.setdefault(k.strip(), v.strip())
                # Ingest's settings and its helper processes read os.environ (7 Oct 2026: the lane and
                # thread caps in vision.env never reached them).
                if k.strip().startswith("PANOPTICAM_"):
                    os.environ.setdefault(k.strip(), v.strip())
    return env

