def embed_images(self, imgs: list[Image.Image]) -> np.ndarray:
    x = np.stack([
        ((np.asarray(im.resize((224, 224), Image.BICUBIC), dtype=np.float32) / 255.0 - 0.5) / 0.5).transpose(2, 0, 1)
        for im in imgs
    ])
    # In small runs: ONNX's arena keeps the biggest run's activations for good. Measured
    # (30 Sep 2026, int8 CPU, 2 threads, 64 images): one run 1.45 GB kept, 9.5 s; runs of
    # 8 keep 0.37 GB and take 8.4 s.
    out = np.concatenate([self.siglip.run(None, {self.siglip_in: x[i:i + EMBED_CHUNK]})[self.siglip_out]
                          for i in range(0, len(x), EMBED_CHUNK)]).astype(np.float32)
    return out / np.linalg.norm(out, axis=1, keepdims=True)

